window.APP_DATA = window.APP_DATA || {};
window.APP_DATA.slang = [
  // 諺語 Grade 1-6（20條）
  { id: "s001", grade: 1, term: "一枝草一點露", kind: "諺語", meaning: "天無絕人之路，每個人都有自己的生存之道，不必絕望。", example: "別灰心，一枝草一點露，總會找到出路的。", deep: "這句話怎麼來的：這是臺灣民間流傳的閩南語諺語，講的是清晨田野的景象——再不起眼的一根小草，葉尖上也會落到一滴屬於它的露水。\n字面意思：一根草，就有一點露水養它。\n引申意思：老天不會餓死任何一個人，每個人都有自己活下去的辦法。多用在安慰陷入困境的人，叫他不要絕望。" },
  { id: "s002", grade: 2, term: "苦盡甘來", kind: "諺語", meaning: "經歷困難和痛苦之後，終會迎來幸福和喜樂的日子。", example: "只要堅持下去，苦盡甘來，你會嚐到成功的滋味。", deep: "這句話怎麼來的：元代的戲曲裡就常常出現這句話，用來寫主角熬過磨難之後終於苦出頭。\n字面意思：苦味到了盡頭，甜味就跟著來了。\n引申意思：熬過艱難的日子，好日子就會來。重點在「苦要熬到盡頭」，不是苦一下就會有甜。" },
  { id: "s003", grade: 3, term: "一分辛苦一分收穫", kind: "諺語", meaning: "付出多少努力就會得到相應的成果，不勞則無獲。", example: "學習是一分辛苦一分收穫，不可能不花力氣就考高分。", deep: "這句話怎麼來的：是農家長期的生活經驗變成的俗諺——田裡下多少工夫，秋天就收多少穀子，騙不了人。\n字面意思：付出一分辛苦，就得到一分收穫。\n引申意思：努力和成果成正比，沒有不勞而獲的事。常用來勸人踏實用功，不要想走捷徑。" },
  { id: "s004", grade: 4, term: "三思而後行", kind: "諺語", meaning: "做任何事都要經過深思熟慮，不可輕率決定。", example: "重大決定要三思而後行，別一時衝動就後悔。", deep: "典故由來：出自《論語．公冶長》。魯國大夫季文子做事一定「三思而後行」，孔子聽到卻說「再，斯可矣」——想兩次就夠了。\n字面意思：想過三次以後才行動。\n引申意思：做事要先想清楚再動手。有趣的是孔子的原意是提醒季文子想太多會誤事，後人反而把它當成「要多想一想」的勸告。" },
  { id: "s005", grade: 2, term: "知足常樂", kind: "諺語", meaning: "懂得知足就能常保快樂心境，貪心只會帶來煩惱。", example: "有人為了賺更多錢而累得半死，我們卻知足常樂。", deep: "典故由來：源頭是《老子》的「知足者富」「知足不辱，知止不殆」，後人化用成「知足常樂」四個字。\n字面意思：知道滿足，就能常常快樂。\n引申意思：快樂來自於對現有的東西感到夠了，而不是拿到更多。它勸的是收斂欲望，不是叫人不求上進。" },
  { id: "s006", grade: 3, term: "虛心使人進步", kind: "諺語", meaning: "態度謙遜虛心，才能不斷學習進步；自滿就會停滯。", example: "你要虛心使人進步，多聽別人的意見和建議。", deep: "這句話怎麼來的：古典的源頭是《尚書．大禹謨》的「滿招損，謙受益」——自滿招來損失，謙虛得到好處。現代把它講成「虛心使人進步」。\n字面意思：心裡空著（不自滿），人就會往前走。\n引申意思：肯承認自己不足、肯聽別人意見的人才學得進東西。常和「驕傲使人落後」成對出現。" },
  { id: "s007", grade: 4, term: "驕傲使人落後", kind: "諺語", meaning: "自傲自滿會導致進步停滯，甚至被超越淘汰。", example: "他因為一次成功就開始驕傲使人落後，結果被同學超越。", deep: "這句話怎麼來的：和「虛心使人進步」是一組對句，古典源頭同樣是《尚書》的「滿招損，謙受益」。\n字面意思：驕傲會讓人往後退。\n引申意思：一有成績就自滿，就會停下來不再學，很快被別人追過去。它警告的是「成功之後」的危險，不是失敗的時候。" },
  { id: "s008", grade: 1, term: "勤能補拙", kind: "諺語", meaning: "靠著勤奮努力可以彌補天賦不足，勤奮是成功的關鍵。", example: "我不是最聰明的，但勤能補拙，我相信能趕上別人。", deep: "典故由來：出自白居易的詩句「救煩無若靜，補拙莫如勤」——要治煩躁沒有比安靜更好的，要補笨拙沒有比勤勞更好的。\n字面意思：勤勞可以補上笨拙的不足。\n引申意思：天分不夠可以用努力補回來。它承認人有資質差別，但主張差別是補得起來的。" },
  { id: "s009", grade: 2, term: "天無絕人之路", kind: "諺語", meaning: "即使陷入困境也總會有出路，絕望時不應放棄希望。", example: "失業時很難過，但天無絕人之路，找到了新工作。", deep: "這句話怎麼來的：元代戲曲和明清小說裡常用的俗語，人物走投無路時旁人就這樣勸他。\n字面意思：老天不會把人的路全部堵死。\n引申意思：再糟的處境也會留一條出路，不要絕望。用在安慰別人，不適合拿來當作自己不努力的藉口。" },
  { id: "s010", grade: 3, term: "鐵杵磨成繡花針", kind: "諺語", meaning: "只要持之以恆，就算最困難的事也能成功；強調耐心和毅力。", example: "他每天練琴十年，這就是鐵杵磨成繡花針的道理。", deep: "典故由來：出自李白小時候的傳說。他讀書讀到一半跑出去玩，在溪邊看到一位老婆婆拿鐵棒在石頭上磨，說要磨成繡花針；李白受到觸動就回去把書讀完了。\n字面意思：把鐵棒磨成繡花的細針。\n引申意思：只要肯一直做下去，再難的事也做得成。重點在「持續」，不在一次用多大的力氣。" },
  { id: "s011", grade: 4, term: "團結力量大", kind: "諺語", meaning: "許多人共同合作的力量遠大於單獨一人的力量。", example: "班級要參加比賽，團結力量大，我們一起加油。", deep: "這句話怎麼來的：是現代常用的一句口號式諺語，源頭是「眾志成城」「眾擎易舉」這一類古語的白話說法。\n字面意思：團結起來的力量很大。\n引申意思：許多人朝同一個方向使力，效果遠遠超過各自為政。用的時候通常在講合作，不是在講人多。" },
  { id: "s012", grade: 1, term: "聞過則喜", kind: "諺語", meaning: "聽到自己的錯誤不會生氣反而高興，因為能改進不足。", example: "媽媽聞過則喜地接受我的批評，決心改改她的脾氣。", deep: "典故由來：出自《孟子．公孫丑上》。孟子稱讚子路：「人告之以有過，則喜」——別人指出他的過錯，他反而高興。\n字面意思：聽到自己的過錯就高興。\n引申意思：把批評當成改進的機會，而不是攻擊。這是一種很高的修養，比「聽得進批評」還要更進一步。" },
  { id: "s013", grade: 2, term: "己所不欲勿施於人", kind: "諺語", meaning: "自己不想遭受的待遇，就不要加諸於他人身上。", example: "不要欺負別人，己所不欲勿施於人，要尊重他人。", deep: "典故由來：出自《論語．顏淵》。子貢問怎樣做人，孔子答「其恕乎！己所不欲，勿施於人」——這叫做「恕」。\n字面意思：自己不想要的，不要加在別人身上。\n引申意思：用自己的感受去推想別人的感受。它講的是「不做」什麼，是道德的底線，不是要你去做多少好事。" },
  { id: "s014", grade: 5, term: "千里之行始於足下", kind: "諺語", meaning: "再遠大的目標也是從踏出第一步開始的，強調開始的重要性。", example: "想去環遊世界，千里之行始於足下，先計畫好就出發。", deep: "典故由來：出自《老子》第六十四章「合抱之木，生於毫末；九層之臺，起於累土；千里之行，始於足下」。\n字面意思：一千里的路，是從腳下這一步開始的。\n引申意思：再大的目標都要從眼前這件小事做起。它同時在勸兩件事——不要被目標的大嚇到，也不要只想目標不動腳。" },
  { id: "s015", grade: 3, term: "一日之計在於晨", kind: "諺語", meaning: "一天中最重要的時間是早上，早起能計畫和珍惜一天。", example: "要成功的人都知道一日之計在於晨，早起讀書效率最高。", deep: "典故由來：出自南朝梁元帝蕭繹的《纂要》，原句是「一年之計在於春，一日之計在於晨」，兩句本來就是一組。\n字面意思：一天的安排，重點在早晨。\n引申意思：一天當中頭腦最清楚、最沒有被打斷的時段在早上，計畫和最重要的事要放在那時候做。" },
  { id: "s016", grade: 4, term: "一年之計在於春", kind: "諺語", meaning: "一年中最重要的季節是春天，春季計畫決定全年方向。", example: "新年要定好目標，一年之計在於春，別浪費開局。", deep: "典故由來：和「一日之計在於晨」出自同一句，南朝梁元帝《纂要》：「一年之計在於春，一日之計在於晨。」\n字面意思：一年的安排，重點在春天。\n引申意思：農家春天播種決定秋天的收成，所以開頭的準備決定後面的結果。用在做事上就是「起頭那段時間最關鍵」。" },
  { id: "s017", grade: 5, term: "好事多磨", kind: "諺語", meaning: "美好的事情往往需要經過許多曲折才能實現。", example: "終於考上理想的學校，好事多磨，但堅持就成功了。", deep: "這句話怎麼來的：宋、金時期的詞曲裡就已經在用，《西廂記諸宮調》寫張生與鶯鶯的曲折，就說「真所謂好事多磨」。\n字面意思：好的事情要經過很多磨難。\n引申意思：值得的事情通常不會一路順利。它是用來安慰正在受挫的人，暗示「會成，只是還沒到」。" },
  { id: "s018", grade: 6, term: "熟能生巧", kind: "諺語", meaning: "經過反覆練習和實踐，不擅長的事情也能逐漸變得熟練和巧妙。", example: "我剛開始打網球很差，但熟能生巧，現在打得還不錯。", deep: "典故由來：源頭是歐陽修〈賣油翁〉。賣油的老翁能把油從銅錢的方孔倒進葫蘆而不沾到錢，他說「我亦無他，惟手熟爾」——沒什麼別的，只是手熟罷了。\n字面意思：做熟了，就會生出巧妙。\n引申意思：技巧是練出來的不是天生的。它提醒的是「量」——先練夠次數，巧才會出現。" },
  { id: "s019", grade: 5, term: "明月清風不用錢", kind: "諺語", meaning: "自然界的美好不需花錢就能享受，真正的快樂來自簡單。", example: "不必買貴的禮物，明月清風不用錢，一起散步就很開心。", deep: "典故由來：化用自蘇軾〈前赤壁賦〉「惟江上之清風，與山間之明月……取之無禁，用之不竭」。\n字面意思：天上的月亮和吹來的清風，都不用花錢。\n引申意思：最好的東西往往不必用錢買。它勸人把注意力從買得到的東西，轉到本來就在身邊的東西。" },
  { id: "s020", grade: 6, term: "落花有意流水無情", kind: "諺語", meaning: "單方面的努力或付出若得不到回應，最後只能徒勞無功。", example: "他一直追求那個女生，落花有意流水無情，應該放手了。", deep: "典故由來：出自禪宗語錄《續傳燈錄》：「落花有意隨流水，流水無心戀落花。」\n字面意思：落下的花想跟著水走，水卻沒有留戀花的心思。\n引申意思：一方有情、一方無意，付出得不到回應。多用在感情上，也可以用在一頭熱的合作或示好。" },

  // 諺語 Grade 7-9（15條）
  { id: "s021", grade: 7, term: "乘風破浪", kind: "諺語", meaning: "勇敢克服困難，憑著勢頭奮發進取，達到目標。", example: "創業初期很辛苦，但我們乘風破浪，現在公司發展順利。", deep: "典故由來：出自《宋書．宗愨傳》。宗愨小時候，叔叔問他的志向，他說「願乘長風破萬里浪」。\n字面意思：趁著大風，破開萬里的浪往前走。\n引申意思：不躲開困難，反而借著情勢往前衝。它的重點是「乘風」——把阻力當成推力，不是硬撐。" },
  { id: "s022", grade: 7, term: "志在千里", kind: "諺語", meaning: "有遠大的目標和志向，不為眼前的成就所滿足。", example: "他年紀輕輕就志在千里，立志要改變世界。", deep: "典故由來：出自曹操〈龜雖壽〉：「老驥伏櫪，志在千里；烈士暮年，壯心不已。」\n字面意思：（老馬雖然趴在馬槽邊）心志還在一千里之外。\n引申意思：志向遠大，不因為眼前的處境或年紀而縮小。原詩講的是年紀大了志氣還在，所以用在長者身上最貼切。" },
  { id: "s023", grade: 8, term: "樂極生悲", kind: "諺語", meaning: "過度的快樂和放縱往往會導致後來的悲傷和失落。", example: "度假時樂極生悲，回程班機被颶風吹取消了。", deep: "典故由來：出自《史記．滑稽列傳》淳于髡對齊威王說的「酒極則亂，樂極則悲」。他是用喝酒來勸君王不要沉迷。\n字面意思：快樂到了極點，悲傷就跟著來。\n引申意思：任何情緒或享受過了頭都會反轉。它勸的是節制，不是叫人不要快樂。" },
  { id: "s024", grade: 8, term: "覆水難收", kind: "諺語", meaning: "已經做出的事情就無法挽回，後悔也沒用，要慎重決定。", example: "傷人的話說出口就覆水難收，所以說話要三思。", deep: "典故由來：傳說姜太公未發跡時妻子離開了他，後來他做了大官，妻子想回頭，他把一盆水潑在地上，叫她收回來。\n字面意思：潑出去的水收不回來。\n引申意思：做了的事、說出口的話沒辦法回頭。它的重點在「決定之前要想清楚」，而不是在責備後悔的人。" },
  { id: "s025", grade: 7, term: "卧虎藏龍", kind: "諺語", meaning: "隱藏著許多傑出人才或強大的實力，不可小看。", example: "這家公司看起來不起眼，但卧虎藏龍，有許多優秀人才。", deep: "典故由來：出自北周庾信的詩句「暗石疑藏虎，盤根似臥龍」，本來是形容山石草木的形狀。\n字面意思：趴著的老虎，藏起來的龍。\n引申意思：這個地方藏著厲害的人物，不可以小看。用的時候通常在提醒別人「別看它不起眼」。" },
  { id: "s026", grade: 9, term: "畫龍點睛", kind: "諺語", meaning: "最後的關鍵部分能讓整個事物完美，比喻重要的一步。", example: "演講差不多了，最後畫龍點睛，講個感人的故事就完美。", deep: "典故由來：出自畫家張僧繇的傳說。他在牆上畫了四條龍卻不畫眼睛，說畫了會飛走；旁人不信，他點了兩條，那兩條龍就破壁飛去。\n字面意思：畫龍的時候點上眼睛。\n引申意思：在關鍵的地方加上最重要的一筆，整個作品就活了。它強調的是「那一筆的位置」，不是加了多少東西。" },
  { id: "s027", grade: 8, term: "鳳毛麟角", kind: "諺語", meaning: "稀有珍貴，難得一見，形容人或事物非常罕有。", example: "有道德的商人現在已是鳳毛麟角，難得一見。", deep: "這句話怎麼來的：鳳凰和麒麟都是傳說中的神獸，本來就見不到，何況是牠們身上的一根毛、一隻角。\n字面意思：鳳凰的毛、麒麟的角。\n引申意思：極為稀少珍貴。它形容的是「數量少」，帶著珍惜的語氣，不能拿來說壞事很少見。" },
  { id: "s028", grade: 7, term: "沙裡淘金", kind: "諺語", meaning: "從大量尋常的事物中找出珍貴難得的東西；不怕辛苦找寶藏。", example: "編輯工作就像沙裡淘金，要從海量投稿中挑優秀作品。", deep: "典故由來：出自劉禹錫〈浪淘沙〉：「千淘萬漉雖辛苦，吹盡狂沙始到金。」\n字面意思：在沙子裡淘洗，把金子挑出來。\n引申意思：從大量平凡的東西裡找出真正有價值的少數。它同時強調兩件事——東西真的有，但要花很多工夫才挑得出來。" },
  { id: "s029", grade: 8, term: "光陰似箭", kind: "諺語", meaning: "時光流逝迅速，就像箭一樣快，轉眼就過去了。", example: "轉眼就大學畢業了，光陰似箭，時間過得真快。", deep: "這句話怎麼來的：唐詩裡就用箭來比時間，韋莊寫過「但見時光流似箭」，後來定型成「光陰似箭」。\n字面意思：時間像射出去的箭。\n引申意思：時間過得很快，而且和箭一樣回不了頭。常和「日月如梭」連用，都是在催人珍惜時間。" },
  { id: "s030", grade: 9, term: "功虧一簣", kind: "諺語", meaning: "成功在即卻因最後的放鬆而失敗，差一點就能成功。", example: "他複習了整年準備考試，最後一週放鬆導致功虧一簣。", deep: "典故由來：出自《尚書．旅獒》「為山九仞，功虧一簣」——堆一座九仞高的山，就差最後一畚箕的土沒倒上去。\n字面意思：功勞毀在最後一畚箕土上。\n引申意思：快成功時鬆懈，前面的努力全白費。它責備的是「最後那一下沒撐住」，不是從頭就做不好。" },
  { id: "s031", grade: 7, term: "厚積薄發", kind: "諺語", meaning: "長期累積足夠的實力和知識，然後一舉成功爆發。", example: "他默默努力多年，終於厚積薄發，一舉成名。", deep: "典故由來：出自蘇軾〈稼說送張琥〉「博觀而約取，厚積而薄發」——讀得廣但取得少，累積得厚但拿出來得少。\n字面意思：積得很厚，發出來的卻很少。\n引申意思：長期扎實地累積，等到要用的時候一次見真章。「薄發」不是成果小，而是不隨便拿出來。" },
  { id: "s032", grade: 8, term: "文以載道", kind: "諺語", meaning: "文章和文字可以用來傳載人生的智慧和思想道理。", example: "這位作家文以載道，他的作品充滿人生哲理。", deep: "典故由來：出自宋代周敦頤《通書．文辭》：「文所以載道也。」\n字面意思：文章是用來裝載道理的。\n引申意思：寫文章不只為了好看，要能承載思想。這句話是古人對「內容重於辭藻」的主張，常被拿來討論寫作的目的。" },
  { id: "s033", grade: 9, term: "人以群分", kind: "諺語", meaning: "人會根據志同道合的程度聚在一起，相似的人會聚集。", example: "他交的朋友都是有上進心的，人以群分，朋友質量很重要。", deep: "典故由來：出自《易經．繫辭上》：「方以類聚，物以群分。」後來變成「物以類聚，人以群分」。\n字面意思：人會按照類別分成一群一群。\n引申意思：志趣相近的人自然會聚在一起，所以從一個人的朋友就看得出他大概是什麼樣的人。這句話可褒可貶。" },
  { id: "s034", grade: 7, term: "盡人事聽天命", kind: "諺語", meaning: "已經盡力做好自己的事，剩下的就交由命運決定。", example: "考前準備充分，盡人事聽天命，放心等成績放榜。", deep: "這句話怎麼來的：清代小說《鏡花緣》裡寫成「盡人事以聽天命」，是古人面對考試、疾病這類無法完全掌控的事時的態度。\n字面意思：把人做得到的都做完，剩下的交給天。\n引申意思：先全力以赴，再接受結果。重點在前半段——沒有盡人事，就沒有資格說聽天命。" },
  { id: "s035", grade: 9, term: "飲水思源", kind: "諺語", meaning: "喝著水時要想起水的來源，比喻不要忘記根本和恩情。", example: "現在成功了也要飲水思源，感謝父母的養育。", deep: "典故由來：出自庾信〈徵調曲〉「落其實者思其樹，飲其流者懷其源」——吃果子要想到那棵樹，喝水要想到源頭。\n字面意思：喝水的時候想到水是哪裡來的。\n引申意思：得到好處要記得是誰給的。它講的是感恩與不忘本，常用在對師長、父母、故鄉。" },

  // 諺語 Grade 10-12（5條）
  { id: "s036", grade: 10, term: "力不從心", kind: "諺語", meaning: "心裡想做某事，但能力不足以實現，無法如願。", example: "想幫助他解決問題，但力不從心，只好看著他難受。", deep: "典故由來：出自《後漢書．班超傳》。班超年老想回中原，上書說自己「氣力不能從心」，怕突然有變故應付不了。\n字面意思：力氣跟不上心裡想的。\n引申意思：有意願卻沒有能力做到。它形容的是能力不足，不是不想做，所以不帶責備的意思。" },
  { id: "s037", grade: 11, term: "不合時宜", kind: "諺語", meaning: "言行或做法不符合現在的時代和情境，顯得過時。", example: "他還用舊時代的思維管理公司，已經不合時宜了。", deep: "典故由來：出自《漢書．哀帝紀》：「皆違經背古，不合時宜。」原本是批評某些做法違背經典又不合當時的情況。\n字面意思：不符合當下的時機和需要。\n引申意思：想法或做法跟現在的情況搭不上。它說的是「時機不對」，不是說那件事本身是錯的。" },
  { id: "s038", grade: 10, term: "道可道非常道", kind: "諺語", meaning: "能用言語表達的道理就不是永恆的真理，強調言語的局限。", example: "真正的禪學真理是道可道非常道，難以言傳。", deep: "典故由來：出自《老子》第一章開頭：「道可道，非常道；名可名，非常名。」\n字面意思：可以被說出來的道，就不是永恆不變的道。\n引申意思：最根本的道理沒辦法被語言完全裝下。它提醒人不要把說得出口的定義當成全部的真相。" },
  { id: "s039", grade: 12, term: "舐犢情深", kind: "諺語", meaning: "父母對子女的愛非常深厚，比喻親子間深摯的感情。", example: "他父母舐犢情深，為了孩子什麼都肯做。", deep: "典故由來：出自《後漢書．楊彪傳》。楊彪的兒子被殺後，曹操問他為何消瘦，他說自己「猶懷老牛舐犢之愛」。\n字面意思：老牛用舌頭舔小牛。\n引申意思：父母疼愛子女的深情。它取的是動物本能的畫面，所以帶著一種說不出口、自然而然的味道。" },
  { id: "s040", grade: 11, term: "白駒過隙", kind: "諺語", meaning: "時間流逝極快，就像白色的馬快速穿過縫隙一般。", example: "孩子從出生到上大學，白駒過隙，轉眼十八年過去。", deep: "典故由來：出自《莊子．知北遊》：「人生天地之間，若白駒之過郤（隙），忽然而已。」\n字面意思：白色的駿馬從門縫前面一閃而過。\n引申意思：人的一生短得像那一閃。莊子用它講生命的短暫，語氣是感慨，不只是說時間快。" },

  // 歇後語 Grade 1-6（10條）
  { id: "s041", grade: 1, term: "泥菩薩過江——自身難保", kind: "歇後語", meaning: "自己的問題都沒解決，無法幫助他人；騎虎難下的困境。", example: "他欠銀行一堆錢，泥菩薩過江——自身難保，哪還能借錢給朋友。", deep: "這句話怎麼來的：從前廟裡有泥塑的菩薩，泥巴遇水就化。菩薩本來是要保佑人的，可是自己一下水就散了。\n字面意思：泥做的菩薩過江，連自己都保不住。\n引申意思：自己都自顧不暇，沒有餘力幫別人。常用來婉拒別人的求助，語氣帶著無奈。" },
  { id: "s042", grade: 2, term: "站著說話不腰疼", kind: "俚語", meaning: "沒有親身承擔的人，說起別人的難處總是特別輕鬆。", example: "你又不用熬夜趕工，站著說話不腰疼。", deep: "這句話怎麼來的：從彎腰做活的人身上來的——彎著腰的人腰痠背痛，站在旁邊看的人當然不覺得。\n字面意思：站著的人說話，腰不會痛。\n引申意思：沒有親身經歷的人容易說風涼話。用來反駁那種「這有什麼難的」的評論。" },
  { id: "s043", grade: 3, term: "隔著玻璃看花——朦朧不清", kind: "歇後語", meaning: "被阻隔看不真切，理解不清楚或信息不完整。", example: "二手房的狀況隔著玻璃看花——朦朧不清，一定要親自看。", deep: "這句話怎麼來的：隔著一層玻璃看窗外的花，顏色形狀都在，可是細節全糊掉了。\n字面意思：隔著玻璃看花，看不清楚。\n引申意思：中間隔了一層，理解得不真切。它說的是資訊不完整，不是說對方眼力不好。" },
  { id: "s044", grade: 2, term: "騎著駱駝找馬——貪心不足", kind: "歇後語", meaning: "已經得到了還要更多，永不滿足的貪心態度。", example: "他年薪百萬還在想著出軌賺外快，真是騎著駱駝找馬——貪心不足。", deep: "這句話怎麼來的：騎在駱駝上的人已經有交通工具了，卻還一路張望想找匹馬。\n字面意思：騎著駱駝，還在找馬。\n引申意思：手上有了還想要更好的。這句和「騎驢找馬」很像，差別是「騎驢找馬」偏中性（暫時將就），這句偏貶義。" },
  { id: "s045", grade: 3, term: "竹籃打水——一場空", kind: "歇後語", meaning: "白費力氣毫無成果，最後一無所獲，所有努力都完全白費。", example: "他花半年談這個生意，最後竹籃打水——一場空。", deep: "這句話怎麼來的：竹編的籃子縫隙很大，舀起水來提不到兩步就漏光了。\n字面意思：用竹籃子打水，最後籃裡是空的。\n引申意思：白費力氣、一無所獲。它強調的是「工具或方法根本不對」，不是不夠努力。" },
  { id: "s046", grade: 4, term: "黃鼠狼給雞拜年——別有用心", kind: "歇後語", meaning: "看似友善的態度其實另有目的，暗藏著不良企圖的詭計。", example: "他突然對你特別好，別被騙，那是黃鼠狼給雞拜年——別有用心。", deep: "這句話怎麼來的：黃鼠狼會偷雞，牠特地上門向雞道賀，當然不是真心來拜年的。\n字面意思：黃鼠狼跑去給雞拜年。\n引申意思：表面客氣，背後藏著壞主意。用的時候是在提醒對方「別被那個笑臉騙了」。" },
  { id: "s047", grade: 4, term: "狗咬呂洞賓——不識好人心", kind: "歇後語", meaning: "對善待自己的人反而不理解，做好事反而被埋怨。", example: "我好心提醒他，他卻生氣，狗咬呂洞賓——不識好人心。", deep: "典故由來：民間傳說八仙之一的呂洞賓救了一個叫苟杳的人，對方卻誤會他的好意；「苟杳」聽起來像「狗咬」，後來就傳成了狗咬呂洞賓。\n字面意思：狗去咬呂洞賓。\n引申意思：把好心當成惡意。說這句話的人通常是委屈的一方，帶著抱怨的口氣。" },
  { id: "s048", grade: 5, term: "老鼠尾巴——粗不了", kind: "歇後語", meaning: "先天的條件就這麼一點，再怎麼發展也大不起來。", example: "這家小店再怎麼裝潢，老鼠尾巴——粗不了。", deep: "這句話怎麼來的：老鼠的尾巴天生就是又細又長，養得再肥，尾巴還是那麼細。\n字面意思：老鼠的尾巴，粗不起來。\n引申意思：本錢有限，發展也有限。它說的是先天的限制，語氣帶有看不上眼的意味，不適合當面對人說。" },
  { id: "s049", grade: 6, term: "螞蟻搬家——要下雨了", kind: "歇後語", meaning: "從細微的跡象就可以預先看出大事情要發生。", example: "他今天一直在收拾抽屜，螞蟻搬家——要下雨了，八成要離職。", deep: "這句話怎麼來的：下雨前空氣變潮，螞蟻會把蛋和幼蟲往高處搬，農家看到螞蟻列隊搬家就知道雨要來了。\n字面意思：螞蟻在搬家，代表快下雨了。\n引申意思：小徵兆可以預告大變化。它稱讚的是觀察力，不是說螞蟻很勤勞。" },
  { id: "s050", grade: 5, term: "瞎子進廚房——摸不著頭腦", kind: "歇後語", meaning: "完全不懂情況也搞不清狀況，感到非常困惑和無措困擾。", example: "第一次做菜，瞎子進廚房——摸不著頭腦，全亂套。", deep: "這句話怎麼來的：看不見的人進到陌生的廚房，鍋碗瓢盆全都摸不到位置，連從哪裡下手都不知道。\n字面意思：眼睛看不見的人走進廚房，什麼都摸不著。\n引申意思：完全狀況外，不知道怎麼開始。它形容的是「缺乏資訊」，不是笨。" },

  // 歇後語 Grade 7-9（10條）
  { id: "s051", grade: 7, term: "十五個吊桶打水——七上八下", kind: "歇後語", meaning: "心情不安定忐忑不安，時而充滿希望時而又擔心害怕。", example: "面試結果還沒出來，我心裡十五個吊桶打水——七上八下。", deep: "這句話怎麼來的：井邊十五個吊桶一起打水，繩子有的往上拉、有的往下放，永遠是七個上、八個下。\n字面意思：十五個吊桶打水，七個上八個下。\n引申意思：心裡忐忑不安、上上下下定不下來。它用的是數字的巧合，十五剛好拆成七加八。" },
  { id: "s052", grade: 7, term: "八仙過海——各顯神通", kind: "歇後語", meaning: "各自發揮自己的才能和優勢，在各自擅長的領域各顯其能。", example: "這次專案，八仙過海——各顯神通，每個人都貢獻了獨特的想法。", deep: "典故由來：民間傳說八仙要渡海赴宴，呂洞賓提議不坐船，各自拿出自己的法寶過去——鐵拐李用拐杖、韓湘子用笛子、藍采和用花籃。\n字面意思：八位神仙過海，各自使出自己的本領。\n引申意思：各憑本事，各用各的方法。它是中性偏正面的，重點在「方法不同但都有效」。" },
  { id: "s053", grade: 8, term: "竹筒倒豆子——一乾二淨", kind: "歇後語", meaning: "把知道的話全部一次說出來，一點都沒有保留。", example: "警察一問，他就竹筒倒豆子——一乾二淨全招了。", deep: "這句話怎麼來的：豆子裝在竹筒裡，筒身又直又滑，一倒就全部滑出來，連一顆都不會卡住。\n字面意思：竹筒裡的豆子倒得乾乾淨淨。\n引申意思：毫無保留地全說出來。它形容的是「痛快、一次講完」，不含褒貶。" },
  { id: "s054", grade: 9, term: "隔靴搔癢——不著邊際", kind: "歇後語", meaning: "做法沒有搔到癢處，講了半天都沒講到重點。", example: "他的建議隔靴搔癢——不著邊際，真正的問題一句也沒提到。", deep: "典故由來：出自禪宗語錄，禪師批評只在文字上打轉、沒有真正領悟的人，就像隔著靴子抓癢。\n字面意思：隔著靴子抓腳上的癢處。\n引申意思：沒有對準真正的問題。它批評的不是不努力，而是「用力的位置不對」。" },
  { id: "s055", grade: 7, term: "牛不喝水強按頭——不情願", kind: "歇後語", meaning: "硬逼著別人做他不想做的事，勉強也做不好。", example: "他根本不想學琴，牛不喝水強按頭——不情願，練也是白練。", deep: "這句話怎麼來的：牛不渴的時候，就算把牠的頭按到水裡，牠還是不會喝。\n字面意思：牛不想喝水，硬把牠的頭按下去。\n引申意思：勉強來的事情做不好。它提醒的是「意願」——沒有意願，用力壓也沒有用。", deep: "這句話怎麼來的：牛不渴的時候，就算把牠的頭按到水裡，牠還是不會喝。\n字面意思：牛不想喝水，硬把牠的頭按下去。\n引申意思：勉強來的事情做不好。它提醒的是「意願」——沒有意願，用力壓也沒有用。" },
  { id: "s056", grade: 8, term: "猴子掰玉米——掰一個丟一個", kind: "歇後語", meaning: "一直追新的東西，結果每樣都沒留住，到最後兩手空空。", example: "他學才藝像猴子掰玉米——掰一個丟一個，沒有一樣學得成。", deep: "這句話怎麼來的：民間故事裡的猴子進玉米田，掰下一根就夾在腋下，再看到更大的又去掰，前一根就掉了，走出田時手上只剩一根。\n字面意思：猴子每掰一根玉米，就丟掉手上那一根。\n引申意思：見一個要一個，最後什麼都沒累積。它批評的是「沒有守住已經到手的」，不是批評好奇心。" },
  { id: "s057", grade: 9, term: "臨陣磨槍——不快也光", kind: "歇後語", meaning: "事到臨頭才準備，雖然來不及做好，多少還是有一點用。", example: "考前一晚才翻書，臨陣磨槍——不快也光，總比完全沒看好。", deep: "這句話怎麼來的：上戰場前才把槍拿出來磨，時間不夠磨到鋒利，但至少磨得發亮，看起來有點樣子。\n字面意思：上陣前才磨槍，磨不快也磨得發亮。\n引申意思：臨時抱佛腳雖然效果有限，但聊勝於無。它的語氣是半自嘲，不是鼓勵大家都這樣做。" },
  { id: "s058", grade: 7, term: "狗仗人勢——亂咬人", kind: "歇後語", meaning: "靠著背後有人撐腰就欺負別人，自己其實沒有本事。", example: "他不過是主管的親戚，狗仗人勢——亂咬人罷了。", deep: "這句話怎麼來的：家裡養的狗平常見人就躲，主人一站到旁邊就敢對人狂吠。\n字面意思：狗靠著主人的威勢，見人就咬。\n引申意思：借別人的勢力欺負人。和「狐假虎威」很像，差別是這句更粗、更帶罵人的口氣。" },
  { id: "s059", grade: 9, term: "腳踩西瓜皮——滑到哪算哪", kind: "歇後語", meaning: "做事沒有計畫，走一步算一步，聽任情況把自己帶著走。", example: "他找工作腳踩西瓜皮——滑到哪算哪，完全沒想過方向。", deep: "這句話怎麼來的：西瓜皮丟在地上，人一踩上去就止不住，滑到哪裡自己也控制不了。\n字面意思：踩到西瓜皮，滑到哪裡就算哪裡。\n引申意思：沒有規劃、被情勢推著走。它批評的是「不做決定」，比「隨遇而安」帶更多責備。" },
  { id: "s060", grade: 8, term: "平時不燒香，急時抱佛腳", kind: "諺語", meaning: "平常都不準備，出事了才臨時求助，通常來不及。", example: "整學期都不讀書，平時不燒香急時抱佛腳，當然考不好。", deep: "這句話怎麼來的：宋代已經有「閒時不燒香，急來抱佛腳」的說法，用來笑那些平常不拜、有事才跪的人。\n字面意思：平常不去上香，急了才抱住佛的腳求救。\n引申意思：功夫要下在平時。它責備的是平常的怠惰，不是責備求助這件事。" },

  // 歇後語 Grade 10-12（5條）
  { id: "s061", grade: 10, term: "牆頭草——兩邊倒", kind: "歇後語", meaning: "沒有自己的立場，哪一邊得勢就往哪一邊靠。", example: "開會時他牆頭草——兩邊倒，誰講話大聲就附和誰。", deep: "這句話怎麼來的：長在牆頭上的草沒有遮蔽，風從東邊來就倒向西邊，風從西邊來就倒向東邊。\n字面意思：牆頭上的草，兩邊都倒。\n引申意思：沒有立場、隨勢力搖擺。它罵的是投機，不是罵人懂得變通。" },
  { id: "s062", grade: 11, term: "猴年馬月——遙遙無期", kind: "歇後語", meaning: "不知道要等到什麼時候，形容遙遠得看不到期限。", example: "照這個進度，完工要等到猴年馬月——遙遙無期。", deep: "這句話怎麼來的：十二生肖年年輪、十二地支月月輪，「猴年」加上「馬月」要湊在一起並不常見，於是被拿來當成「不知道哪一天」的代稱。\n字面意思：猴的那一年，馬的那一個月。\n引申意思：期限遙遠或根本沒有期限。用的時候通常帶著不耐煩或不抱希望的口氣。" },
  { id: "s063", grade: 12, term: "盲人騎瞎馬——危險之至", kind: "歇後語", meaning: "雙方都看不見卻繼續往前，處境極度危險。", example: "沒查資料就照著做，盲人騎瞎馬——危險之至。", deep: "典故由來：出自《世說新語》。桓玄等人比賽說「最危險的景象」，有人說「盲人騎瞎馬，夜半臨深池」——瞎子騎著瞎馬，半夜走到深池邊。\n字面意思：看不見的人騎著看不見的馬。\n引申意思：條件全不具備卻照樣往前衝。原句還有「夜半臨深池」，危險程度更上一層。" },
  { id: "s064", grade: 10, term: "三個和尚沒水喝——互相推諉", kind: "歇後語", meaning: "人多了反而互相推卸責任，事情沒人做。", example: "三個人負責同一件事，三個和尚沒水喝——互相推諉，最後沒人交。", deep: "這句話怎麼來的：民間故事——一個和尚挑水喝，兩個和尚抬水喝，三個和尚沒水喝，因為每個人都覺得別人會去。\n字面意思：三個和尚在一起，反而沒有水可以喝。\n引申意思：責任沒有分清楚，人愈多愈沒人做。它指的是分工的問題，不是人多本身不好。" },
  { id: "s065", grade: 11, term: "一個巴掌拍不響——雙方都有責任", kind: "歇後語", meaning: "衝突不會只由一方造成，兩邊多少都有原因。", example: "兩個人吵成這樣，一個巴掌拍不響——雙方都有責任。", deep: "這句話怎麼來的：拍手要兩隻手掌對上才會有聲音，只有一隻手怎麼揮都不響。\n字面意思：一個巴掌拍不出聲音。\n引申意思：爭執需要兩方才成立。要小心用——遇到單方面欺負人的事，這句話會變成幫加害者開脫。" },

  // 俚語 Grade 1-6（5條）
  { id: "s066", grade: 1, term: "呷緊弄破碗", kind: "俚語", meaning: "吃飯太急會造成碗破裂；比喻做事太急躁反而容易出錯。", example: "做功課不要呷緊弄破碗，慢慢來反而更快完成。", deep: "這句話怎麼來的：臺灣民間的閩南語俗諺，講的是吃飯太急，筷子一撞、碗一滑就摔破了。\n字面意思：吃得太急，把碗弄破了。\n引申意思：越急越容易出錯，反而更慢。它勸的是放慢速度把事情做對，不是叫人不要積極。" },
  { id: "s067", grade: 2, term: "一粒老鼠屎壞了一鍋粥", kind: "俚語", meaning: "一個壞人或一個小錯誤就能毀掉整個好事的成果。", example: "隊伍裡有個人不認真，一粒老鼠屎壞了一鍋粥，整隊都被扣分。", deep: "這句話怎麼來的：一整鍋煮好的粥，只要掉進一粒老鼠屎，整鍋就沒人敢吃了。\n字面意思：一粒老鼠屎，壞了一整鍋粥。\n引申意思：一個人或一件小錯就毀掉整體。它點出的是「不成比例」——破壞遠比建設容易。" },
  { id: "s068", grade: 3, term: "拍馬屁", kind: "俚語", meaning: "奉承和討好別人，說些虛偽好聽的話來獲得歡心。", example: "他整天對老師拍馬屁，要是有真本事才更厲害。", deep: "這句話怎麼來的：從前草原上的人以馬為傲，見面時拍拍對方的馬稱讚幾句是禮貌；久了變成不管馬好不好都硬誇，就成了奉承的代名詞。\n字面意思：去拍別人的馬屁股。\n引申意思：說好聽話討好人。它罵的是「不看事實只求討好」，不是所有的稱讚都算拍馬屁。" },
  { id: "s069", grade: 4, term: "放牛吃草", kind: "俚語", meaning: "不管不問，完全任其自由發展，採取放任不管的態度。", example: "父母放牛吃草讓他自己安排時間，他竟然自律地主動讀書。", deep: "這句話怎麼來的：把牛牽到草地上就走開，讓牠自己吃，不用一直看著。\n字面意思：把牛放出去讓牠自己吃草。\n引申意思：完全不管，任由對方自己去。它可褒可貶——說主管是放任不管，說教養則可能是給空間。" },
  { id: "s070", grade: 5, term: "小鼻子小眼睛", kind: "俚語", meaning: "形容人非常小氣計較，對每件小事都斤斤計較不放。", example: "他小鼻子小眼睛的，朋友欠他五塊錢也一直記著。", deep: "這句話怎麼來的：形容一個人臉上五官都縮成小小的，看起來就是斤斤計較、不大方的樣子。\n字面意思：鼻子小、眼睛小。\n引申意思：氣量狹小、什麼都計較。它講的是心胸不是長相，不可以拿來評論別人的外貌。" },

  // 俚語 Grade 7-9（5條）
  { id: "s071", grade: 7, term: "唱雙簧", kind: "俚語", meaning: "兩個人互相配合表演和演戲，共同進行欺騙或詭計。", example: "他們倆唱雙簧騙老師說作業丟了，結果被揭穿。", deep: "這句話怎麼來的：雙簧是一種曲藝——前面一個人只做動作對嘴，後面藏一個人負責出聲，兩人配合得天衣無縫。\n字面意思：兩個人一起演雙簧。\n引申意思：兩人套好招演給別人看。它強調的是「事先串通」，所以帶有欺騙的意味。" },
  { id: "s072", grade: 8, term: "吃不了兜著走", kind: "俚語", meaning: "做了壞事或承諾做的事情就必須承受後果，無法逃脫。", example: "你既然答應了就要做到，吃不了兜著走，要負責任。", deep: "這句話怎麼來的：宴席上吃不完的菜，主人叫你用衣服兜著帶回去——引申成「這件事你收不了尾也得自己扛走」。\n字面意思：吃不完的，就兜在衣服裡帶走。\n引申意思：後果必須自己承擔，逃不掉。它多半是威脅或警告的語氣。" },
  { id: "s073", grade: 7, term: "拿翹", kind: "俚語", meaning: "故意擺架子、拖著不答應，要對方來求自己。", example: "請他幫個忙而已，他還在那裡拿翹，一直不肯點頭。", deep: "這句話怎麼來的：「翹」是把身段翹起來、抬高的樣子，「拿」是端著、擺著，合起來就是把架子端在那裡不放下。\n字面意思：把翹起來的姿態端著。\n引申意思：明明可以答應卻故意拖延刁難，等對方低聲下氣。它罵的是態度，不是罵能力，語氣帶著不耐煩。" },
  { id: "s074", grade: 9, term: "腳踏兩條船", kind: "俚語", meaning: "同時與兩個人有曖昧或婚外情關係，對感情不忠實。", example: "他被發現腳踏兩條船，兩段感情都破裂了。", deep: "這句話怎麼來的：一隻腳踩在這條船上，另一隻腳踩在旁邊那條，兩船一分開人就掉進水裡。\n字面意思：兩隻腳分別踩在兩條船上。\n引申意思：同時腳踏兩邊、對感情或立場不專一。它的畫面同時暗示了結果——兩邊都會落空。" },
  { id: "s075", grade: 8, term: "撇清界線", kind: "俚語", meaning: "主動切斷彼此的關係，表示不再往來或承認關係。", example: "他們吵完架後馬上撇清界線，從此沒有往來。", deep: "這句話怎麼來的：「撇」是用手往旁邊一揮的動作，把自己和對方之間畫出一條線。\n字面意思：把界線撇得清清楚楚。\n引申意思：急著和某人或某事切斷關係。用的時候常帶有「怕被牽連」的意思，不完全是中性的。" },

  // 俚語 Grade 10-12（5條）
  { id: "s076", grade: 10, term: "牛頭馬面", kind: "俚語", meaning: "形容人長相凶惡難看，或指某人為人陰險毒辣的類型。", example: "他雖然牛頭馬面的，但其實是個溫柔的人。", deep: "典故由來：牛頭和馬面是傳說中地府的兩個差役，一個牛頭人身、一個馬面人身，負責押解亡魂。\n字面意思：牛的頭、馬的臉。\n引申意思：面貌凶惡或心腸狠毒的人。它原本指的是鬼差，所以罵人的力道很重，不宜隨便用。" },
  { id: "s077", grade: 11, term: "狐朋狗友", kind: "俚語", meaning: "指不良的朋友或損友，是會帶壞人的不好交往對象。", example: "他跟了一群狐朋狗友後開始逃課，家長非常擔心。", deep: "這句話怎麼來的：狐狸狡猾、狗會跟著人瞎起哄，古人用這兩種動物來比那些一起做壞事的朋友。\n字面意思：像狐狸和狗一樣的朋友。\n引申意思：一起玩樂胡鬧、會把人帶壞的損友。它針對的是「一起做的事」，不是說朋友多就不好。" },
  { id: "s078", grade: 12, term: "死皮賴臉", kind: "俚語", meaning: "厚著臉皮不停乞求或跟著不願離開，毫無廉恥心。", example: "他死皮賴臉地跟著她，令她很反感。", deep: "這句話怎麼來的：「死皮」是臉皮厚到麻木，「賴臉」是把臉賴在那裡不走，兩個都在形容不要臉的程度。\n字面意思：臉皮厚得像死皮一樣，賴著不走。\n引申意思：不顧羞恥地糾纏。它罵的是纏著不放的行為，語氣相當不客氣。" },
  { id: "s079", grade: 10, term: "吹牛皮", kind: "俚語", meaning: "說大話和夸大事實，吹噓自己的能力和成就。", example: "他喜歡吹牛皮，說自己能一個人打十個人。", deep: "這句話怎麼來的：從前殺豬後要在豬皮上吹氣才好剝，需要極大的肺活量；有人說自己吹得動整張牛皮，那當然是誇口。\n字面意思：吹一張牛的皮。\n引申意思：說大話、誇大自己的本事。它的畫面本身就在暗示「根本做不到」。" },
  { id: "s080", grade: 11, term: "硬著頭皮", kind: "俚語", meaning: "明知有困難卻勉強自己去做，被迫不得不為之。", example: "他不想去參加那個活動，但硬著頭皮去了。", deep: "這句話怎麼來的：遇到不敢面對的事，人會下意識縮頭；硬著頭皮就是把縮起來的頭再頂出去。\n字面意思：把頭皮繃硬撐過去。\n引申意思：明知困難還是勉強去做。它帶著「不情願但不得不」的味道，和「勇往直前」不一樣。" },
  // ---- 2026-08-02 擴充：s081-s160 ----
  // 諺語（28）
  { id: "s081", grade: 1, term: "早起的鳥兒有蟲吃", kind: "諺語", meaning: "勤快、搶先行動的人才能得到機會與收穫。", example: "早起的鳥兒有蟲吃，他總是第一個到教室複習功課。", deep: "這句話怎麼來的：這是英文諺語 The early bird catches the worm 翻譯過來的，講清晨最早出來的鳥才吃得到蟲。\n字面意思：早起的鳥才有蟲吃。\n引申意思：先行動的人先拿到機會。要注意它講的是「先」不是「多」——起得早但不去找，一樣沒有蟲。" },
  { id: "s082", grade: 1, term: "積少成多", kind: "諺語", meaning: "一點一滴累積，數量就會變多。", example: "每天存十元，積少成多，一年也能存下不少零用錢。", deep: "典故由來：源頭是《漢書．董仲舒傳》的「積少成多」，以及《荀子》的「不積跬步，無以至千里」這一類說法。\n字面意思：把少的一直累積起來，就變多了。\n引申意思：小量持續會變成大量。它的關鍵不在每次做多少，而在有沒有中斷。" },
  { id: "s083", grade: 1, term: "有志者事竟成", kind: "諺語", meaning: "只要有決心毅力，事情終究會成功。", example: "有志者事竟成，他苦練兩年終於學會游泳。", deep: "典故由來：出自《後漢書．耿弇傳》。耿弇提出的作戰計畫別人都覺得太難，他真的做到了，光武帝就說「有志者事竟成也」。\n字面意思：有志氣的人，事情終究做得成。\n引申意思：決心加上持續就會成功。關鍵在「竟」字——不是馬上成，是最後才成。" },
  { id: "s084", grade: 2, term: "失敗為成功之母", kind: "諺語", meaning: "從失敗中記取教訓，才能走向成功。", example: "別怕做錯，失敗為成功之母，再試一次就好。", deep: "這句話怎麼來的：由英文諺語 Failure is the mother of success 譯來，中文裡也有「失敗者成功之母」的舊說法。\n字面意思：失敗是生出成功的母親。\n引申意思：失敗提供了成功需要的教訓。要注意前提——只有檢討過的失敗才是母親，重複同樣的錯不算。" },
  { id: "s085", grade: 2, term: "種瓜得瓜，種豆得豆", kind: "諺語", meaning: "付出什麼樣的努力，就得到什麼樣的結果。", example: "種瓜得瓜，種豆得豆，平時偷懶考試自然吃虧。", deep: "典故由來：源自佛經中「種瓜得瓜，種李得李」的因果比喻，後來成為民間常語。\n字面意思：種下瓜就長出瓜，種下豆就長出豆。\n引申意思：付出什麼就得到什麼。它同時是安慰也是警告——好的因結好果，壞的因也一樣。" },
  { id: "s086", grade: 2, term: "人外有人，天外有天", kind: "諺語", meaning: "強中更有強中手，不可自滿。", example: "他在校內是冠軍，到了全國賽才知道人外有人，天外有天。", deep: "這句話怎麼來的：明代小說《水滸傳》《西遊記》裡就有「強中更有強中手」的說法，後來衍生出這句對句。\n字面意思：人的外面還有人，天的外面還有天。\n引申意思：永遠有比你更厲害的人。它是用來收斂自滿的，不是要人自卑。" },
  { id: "s087", grade: 3, term: "眼見為憑", kind: "諺語", meaning: "親眼看到的才算數，不輕信傳聞。", example: "網路傳言別急著轉發，眼見為憑，先查證再說。", deep: "這句話怎麼來的：完整的說法是「耳聞不如目見，眼見為憑」，強調親眼看到比聽人轉述可靠。\n字面意思：親眼看見的才能當證據。\n引申意思：不要輕信傳聞。它在現在有了新的限制——照片和影片都能造假，眼見也不一定為憑。" },
  { id: "s088", grade: 3, term: "遠親不如近鄰", kind: "諺語", meaning: "住得近的鄰居，往往比遠方親戚更能及時幫忙。", example: "阿公跌倒是隔壁林太太送醫的，真是遠親不如近鄰。", deep: "典故由來：出自元代雜劇，也見於明代小說，原句是「遠親不如近鄰，近鄰不如對門」。\n字面意思：遠方的親戚比不上附近的鄰居。\n引申意思：救急靠的是離得近的人。它比的是「能不能及時到」，不是說親戚不重要。" },
  { id: "s089", grade: 3, term: "家和萬事興", kind: "諺語", meaning: "家庭和睦，一切事情才會興旺順利。", example: "爸爸常說家和萬事興，一家人有話好好講。", deep: "典故由來：源頭是《論語》的「禮之用，和為貴」與民間的「家和萬事興」對聯，常和「家衰口不停」成對。\n字面意思：家庭和睦，各種事情都會興旺。\n引申意思：內部不吵，力氣才用得到外面。它的重點是「和」是條件，不是結果。" },
  { id: "s090", grade: 3, term: "病從口入，禍從口出", kind: "諺語", meaning: "亂吃東西會生病，亂說話會招來災禍。", example: "說話前先想想，病從口入，禍從口出。", deep: "典故由來：出自晉代傅玄《口銘》：「病從口入，禍從口出。」\n字面意思：病是從嘴巴吃進去的，禍是從嘴巴說出來的。\n引申意思：吃和說都要小心。這句話把「吃」和「說」放在一起，是因為兩件事都經過同一個嘴巴，都容易一時貪快。" },
  { id: "s091", grade: 4, term: "不入虎穴，焉得虎子", kind: "諺語", meaning: "不冒險進入險境，就得不到珍貴的成果。", example: "記者深入災區採訪，正是不入虎穴，焉得虎子。", deep: "典故由來：出自《後漢書．班超傳》。班超帶三十六人出使西域，深夜要突襲匈奴使者時說「不入虎穴，不得虎子」。\n字面意思：不進老虎的洞，拿不到小老虎。\n引申意思：不冒險就得不到大成果。要注意班超是評估過才動手的，這句話講的是「算過的險」，不是亂衝。" },
  { id: "s092", grade: 4, term: "少壯不努力，老大徒傷悲", kind: "諺語", meaning: "年輕時不努力，年老時後悔也來不及。", example: "老師以「少壯不努力，老大徒傷悲」勉勵我們把握現在。", deep: "典故由來：出自漢樂府〈長歌行〉：「少壯不努力，老大徒傷悲。」全詩用早晨的露水和秋天的黃葉來寫時間流逝。\n字面意思：年輕時不努力，年老時只能白白傷心。\n引申意思：時間過了補不回來。「徒」字是關鍵——傷悲也沒有用，所以重點在現在就做。" },
  { id: "s093", grade: 4, term: "讀萬卷書，行萬里路", kind: "諺語", meaning: "既要飽讀詩書，也要實地見聞，增廣見識。", example: "暑假全家環島，媽媽說這是讀萬卷書，行萬里路。", deep: "典故由來：出自明代畫家董其昌《畫禪室隨筆》：「讀萬卷書，行萬里路，胸中脫去塵濁。」是在講怎麼養出好眼光。\n字面意思：讀一萬卷書，走一萬里路。\n引申意思：書本知識和親身經驗兩邊都要。它反對只讀不走，也反對只走不讀。" },
  { id: "s094", grade: 4, term: "前人種樹，後人乘涼", kind: "諺語", meaning: "前人辛勞打下基礎，後人得以享受成果。", example: "圖書館是校友捐建的，前人種樹，後人乘涼。", deep: "這句話怎麼來的：清代小說《醉醒石》裡已有「前人種樹，後人乘涼」的說法，畫面是村口那棵讓後代乘涼的老樹。\n字面意思：前面的人種樹，後面的人在樹下乘涼。\n引申意思：享受的人和付出的人不是同一批。它可以用來感恩，也可以用來提醒自己該替後人種樹。" },
  { id: "s095", grade: 5, term: "一寸光陰一寸金，寸金難買寸光陰", kind: "諺語", meaning: "時間比黃金更寶貴，逝去便無法買回。", example: "考前衝刺要分秒必爭，一寸光陰一寸金，寸金難買寸光陰。", deep: "典故由來：前半句出自唐末王貞白〈白鹿洞〉「讀書不覺已春深，一寸光陰一寸金」，後半句是後人補上的。\n字面意思：一寸的光陰值一寸的金子，但一寸的金子買不回一寸光陰。\n引申意思：時間比黃金更貴。重點在後半句——金子花完能再賺，時間過了就沒了。" },
  { id: "s096", grade: 5, term: "三個臭皮匠，勝過一個諸葛亮", kind: "諺語", meaning: "眾人合力集思廣益，勝過一人獨自聰明。", example: "小組討論常有妙點子，三個臭皮匠，勝過一個諸葛亮。", deep: "這句話怎麼來的：一般認為「皮匠」是「裨將」（副將）的訛音——三個副將湊起來的主意，也抵得上一個諸葛亮。\n字面意思：三個補鞋的師傅，勝過一個諸葛亮。\n引申意思：眾人集思廣益勝過一人獨斷。要注意它的前提是「大家真的在想」，不是人多就一定好。" },
  { id: "s097", grade: 5, term: "冰凍三尺，非一日之寒", kind: "諺語", meaning: "事情演變至此，是長期累積的結果。", example: "他倆的心結冰凍三尺，非一日之寒，得慢慢化解。", deep: "典故由來：出自漢代王充《論衡》：「河冰結合，非一日之寒。」後來演變成「冰凍三尺，非一日之寒」。\n字面意思：結出三尺厚的冰，不是一天的寒冷造成的。\n引申意思：現在的結果是長期累積來的。它多半用在壞的結果上，提醒問題早就在了。" },
  { id: "s098", grade: 5, term: "樹大招風", kind: "諺語", meaning: "名聲地位太高，容易招人嫉妒攻擊。", example: "公司做大了難免樹大招風，行事更要謹慎。", deep: "這句話怎麼來的：明代小說《金瓶梅》裡就有「樹大招風」的說法，畫面是林子裡最高的那棵樹先被颱風吹斷。\n字面意思：樹長得高大，就會招來大風。\n引申意思：名聲地位高就容易被盯上。它是提醒要低調，不是叫人不要成功。" },
  { id: "s099", grade: 6, term: "良藥苦口利於病", kind: "諺語", meaning: "有效的藥往往苦口，有益的規勸往往刺耳。", example: "教練的批評雖然難聽，但良藥苦口利於病。", deep: "典故由來：出自《孔子家語》：「良藥苦於口而利於病，忠言逆於耳而利於行。」和「忠言逆耳利於行」本來是一組。\n字面意思：有效的藥吃起來苦，但對病有幫助。\n引申意思：對你好的東西不一定順口。它用「苦」和「利」的對比，說明難受和有用可以並存。" },
  { id: "s100", grade: 6, term: "忠言逆耳利於行", kind: "諺語", meaning: "誠懇的勸告雖不中聽，卻對行事有幫助。", example: "他能接受忠言逆耳利於行，虛心改進缺點。", deep: "典故由來：和「良藥苦口利於病」出自同一句《孔子家語》：「忠言逆於耳而利於行。」\n字面意思：誠懇的勸告聽起來刺耳，但對做事有幫助。\n引申意思：中聽的話不一定有用。要注意它成立的前提是那句話真的是「忠言」，難聽的話不等於忠言。" },
  { id: "s101", grade: 6, term: "青出於藍，更勝於藍", kind: "諺語", meaning: "學生勝過老師，後人超越前人。", example: "徒弟的手藝青出於藍，更勝於藍，師傅與有榮焉。", deep: "典故由來：出自《荀子．勸學》：「青，取之於藍而青於藍。」藍是一種可以染布的草，提煉出來的青色比原本的草更深。\n字面意思：青色從藍草提煉出來，卻比藍草更青。\n引申意思：學生超過老師、後人超過前人。荀子用它講的是「學習可以改變人」，重點在勸學。" },
  { id: "s102", grade: 7, term: "玉不琢，不成器", kind: "諺語", meaning: "人不經過磨練教育，難以成材。", example: "嚴師出高徒，玉不琢，不成器。", deep: "典故由來：出自《禮記．學記》：「玉不琢，不成器；人不學，不知道。」\n字面意思：玉石不經過雕琢，做不成器物。\n引申意思：人不經過磨練和學習，成不了材。它把「玉」和「人」並列，暗示每個人本來都是有料的，差在有沒有琢。" },
  { id: "s103", grade: 7, term: "滿招損，謙受益", kind: "諺語", meaning: "自滿招致損失，謙虛獲得益處。", example: "得獎後他更加低調，深知滿招損，謙受益。", deep: "典故由來：出自《尚書．大禹謨》：「滿招損，謙受益，時乃天道。」意思是這是自然的規律。\n字面意思：自滿招來損失，謙虛得到好處。\n引申意思：態度決定你還能不能學到東西。《尚書》把它稱作「天道」，是說這不是道德勸說，而是本來就會發生的事。" },
  { id: "s104", grade: 8, term: "水能載舟，亦能覆舟", kind: "諺語", meaning: "同一股力量能成就你，也能毀掉你；多喻民心向背。", example: "民意如流水，水能載舟，亦能覆舟。", deep: "典故由來：出自《荀子．王制》：「君者，舟也；庶人者，水也。水則載舟，水則覆舟。」唐太宗和魏徵也常引用這句話。\n字面意思：水可以把船浮起來，也可以把船翻掉。\n引申意思：同一股力量既能成就你也能毀掉你。原句講的是民心，所以它主要用在權力和群眾的關係上。" },
  { id: "s105", grade: 8, term: "千里之堤，潰於蟻穴", kind: "諺語", meaning: "小疏忽不處理，會釀成大禍。", example: "小弊案不查，千里之堤，潰於蟻穴。", deep: "典故由來：出自《韓非子．喻老》：「千丈之堤，以螻蟻之穴潰。」韓非用它說明小事不處理會壞大事。\n字面意思：一千里長的堤防，因為螞蟻挖的小洞而崩潰。\n引申意思：小疏忽會釀成大災難。它的力道來自對比——一邊是巨大的堤，一邊是看不見的蟻穴。" },
  { id: "s106", grade: 9, term: "人無遠慮，必有近憂", kind: "諺語", meaning: "沒有長遠打算，眼前很快就會出現麻煩。", example: "月光族要記住：人無遠慮，必有近憂。", deep: "典故由來：出自《論語．衛靈公》：「人無遠慮，必有近憂。」\n字面意思：人如果沒有長遠的考慮，眼前一定會有麻煩。\n引申意思：不提前規劃，問題就會追上來。它說的是因果——近憂不是運氣不好，是遠慮沒做。" },
  { id: "s107", grade: 9, term: "工欲善其事，必先利其器", kind: "諺語", meaning: "要把事情做好，先把工具準備好。", example: "工欲善其事，必先利其器，登山前先檢查裝備。", deep: "典故由來：出自《論語．衛靈公》。子貢問怎麼行仁，孔子說「工欲善其事，必先利其器」，接著講要結交賢者。\n字面意思：工匠想把活做好，一定先把工具磨利。\n引申意思：先準備好條件再動手。孔子的原意其實是講「交什麼樣的朋友」，工具只是比喻。" },
  { id: "s108", grade: 10, term: "學而不思則罔，思而不學則殆", kind: "諺語", meaning: "只讀書不思考會迷惘，只空想不讀書會危殆。", example: "唸書要邊讀邊想，學而不思則罔，思而不學則殆。", deep: "典故由來：出自《論語．為政》：「學而不思則罔，思而不學則殆。」\n字面意思：只學不想會迷惘，只想不學會危險。\n引申意思：吸收和思考要一起做。「罔」是一團模糊，「殆」是站不住腳，兩種毛病的後果並不一樣。" },
  // 台灣俗諺（俚語，25）
  { id: "s109", grade: 1, term: "愛拚才會贏", kind: "俚語", meaning: "台語俗諺：肯打拚努力，才會成功。", example: "阿爸常哼「愛拚才會贏」，鼓勵我們不要怕辛苦。", deep: "這句話怎麼來的：臺灣的閩南語俗諺，因為一九八八年葉啟田的同名歌曲傳唱全臺，成了臺灣人最熟悉的一句勵志話。\n字面意思：要肯拚，才會贏。\n引申意思：成功來自努力。歌詞裡還有「三分天注定，七分靠打拚」，兩句合起來才是完整的意思——承認有運氣，但主要靠自己。" },
  { id: "s110", grade: 2, term: "大隻雞慢啼", kind: "俚語", meaning: "台語俗諺：大器晚成，有些人較晚才展現才能。", example: "他小學成績平平，高中突飛猛進，真是大隻雞慢啼。", deep: "這句話怎麼來的：臺灣的閩南語俗諺。體型大的雞比較晚才會啼，但一啼就宏亮。\n字面意思：大隻的雞比較晚啼叫。\n引申意思：有些人成熟得晚，但潛力大。常用來安慰發展比較慢的孩子，語氣是鼓勵不是責備。" },
  { id: "s111", grade: 2, term: "歹竹出好筍", kind: "俚語", meaning: "台語俗諺：平凡的環境也能培養出優秀的人才。", example: "他出身貧困卻考上醫學系，鄰居都說歹竹出好筍。", deep: "這句話怎麼來的：臺灣的閩南語俗諺，取材自竹林——看起來又細又歪的老竹叢，底下卻長出又肥又嫩的好筍。\n字面意思：不好的竹子，長出好的竹筍。\n引申意思：出身平凡也能出好人才。要注意它有一點貶低長輩的意思，通常不會當著對方父母的面說。" },
  { id: "s112", grade: 3, term: "一兼二顧，摸蜊仔兼洗褲", kind: "俚語", meaning: "台語俗諺：一次行動同時達成兩個目的。", example: "騎車送貨順路運動，一兼二顧，摸蜊仔兼洗褲。", deep: "這句話怎麼來的：臺灣的閩南語俗諺。從前在溪邊摸蜆仔（小蛤蜊）要下水，褲子順便就洗乾淨了。\n字面意思：一趟出門辦兩件事，摸蜆仔的同時把褲子也洗了。\n引申意思：一舉兩得。它的畫面很生活化，強調的是「順便」而不是刻意安排。" },
  { id: "s113", grade: 3, term: "好酒沉甕底", kind: "俚語", meaning: "台語俗諺：好的東西往往留在最後才出現。", example: "壓軸表演最精采，果然好酒沉甕底。", deep: "這句話怎麼來的：臺灣的閩南語俗諺。釀酒時最醇厚的部分沉在酒甕的底層，要倒到最後才喝得到。\n字面意思：好酒沉在酒甕的底部。\n引申意思：最好的留在最後。常用在比賽或表演的壓軸，也用來安慰還沒輪到的人。" },
  { id: "s114", grade: 3, term: "近廟欺神", kind: "俚語", meaning: "台語俗諺：對身邊熟悉的人事物反而不知珍惜敬重。", example: "住在故宮旁卻從沒進去參觀，真是近廟欺神。", deep: "這句話怎麼來的：臺灣的閩南語俗諺。住在廟旁邊的人天天看到神像，反而不覺得神聖，拜得比遠道而來的人隨便。\n字面意思：住得離廟太近，反而輕慢神明。\n引申意思：太熟悉就不知道珍惜。它常用在家人、老朋友身上——最親近的人反而最容易被忽略。" },
  { id: "s115", grade: 4, term: "龜笑鱉無尾", kind: "俚語", meaning: "台語俗諺：自己也有同樣缺點，卻嘲笑別人。", example: "他字也寫得潦草還笑我，龜笑鱉無尾。", deep: "這句話怎麼來的：臺灣的閩南語俗諺。烏龜嘲笑鱉沒有尾巴，可是烏龜的尾巴也短得看不見。\n字面意思：烏龜笑鱉沒有尾巴。\n引申意思：自己有同樣的毛病卻笑別人。和「五十步笑百步」很像，差別是這句連程度差都沒有，兩邊一模一樣。" },
  { id: "s116", grade: 4, term: "輸人毋輸陣", kind: "俚語", meaning: "台語俗諺：個人可以輸，氣勢和場面不能輸。", example: "啦啦隊比賽大家卯足全力，輸人毋輸陣。", deep: "這句話怎麼來的：臺灣的閩南語俗諺，源自迎神賽會、陣頭比拚的場面——人數比不過，陣式和聲勢不能塌下來。\n字面意思：人可以輸，陣勢不能輸。\n引申意思：實力不如人時，至少把態度和氣勢做足。它講的是不認輸的精神，不是叫人硬撐面子。" },
  { id: "s117", grade: 4, term: "呷人一口，報人一斗", kind: "俚語", meaning: "台語俗諺：受人一點恩惠，要加倍回報。", example: "當年受他幫助，如今呷人一口，報人一斗，理當相挺。", deep: "這句話怎麼來的：臺灣的閩南語俗諺。「斗」是量米的容器，一斗遠遠多過一口。\n字面意思：吃了人家一口，要回報人家一斗。\n引申意思：受人小惠要加倍報答。它用「一口」對「一斗」的懸殊比例，把感恩的分量講得非常重。" },
  { id: "s118", grade: 5, term: "細漢偷挽匏，大漢偷牽牛", kind: "俚語", meaning: "台語俗諺：小時偷小東西不糾正，長大會犯大錯。", example: "小錯要及時管教，免得細漢偷挽匏，大漢偷牽牛。", deep: "這句話怎麼來的：臺灣的閩南語俗諺。「挽匏」是摘匏瓜，小時候摘了鄰居的匏瓜沒被糾正，長大就敢去牽人家的牛。\n字面意思：小時候偷摘匏瓜，長大就偷牽牛。\n引申意思：小錯不管，會長成大錯。它勸的是「當下就糾正」，重點在時間而不是責罰。" },
  { id: "s119", grade: 5, term: "三日無餾，爬上樹", kind: "俚語", meaning: "台語俗諺：學過的東西幾天不複習就生疏忘光。", example: "英文單字三日無餾，爬上樹，要天天複習。", deep: "這句話怎麼來的：臺灣的閩南語俗諺。「餾」是把冷掉的粿或飯再蒸一次；三天不蒸，粿就硬得像爬上樹一樣拿不下來。\n字面意思：三天不回蒸，就爬上樹了。\n引申意思：學過的東西不複習很快就忘。它用食物變質來比記憶，畫面比「忘記」具體得多。" },
  { id: "s120", grade: 5, term: "好天著存雨來糧", kind: "俚語", meaning: "台語俗諺：順境時要為逆境預作準備。", example: "景氣好時多存錢，好天著存雨來糧。", deep: "這句話怎麼來的：臺灣的閩南語俗諺。農家在好天氣時要把糧食曬乾存起來，因為雨季一來就沒得曬也沒得收。\n字面意思：好天氣的時候，要存下雨天要吃的糧食。\n引申意思：順境時為逆境做準備。和「未雨綢繆」意思相同，這句更貼近農家的實際生活。" },
  { id: "s121", grade: 6, term: "樹頭徛予在，毋驚樹尾做風颱", kind: "俚語", meaning: "台語俗諺：根基站得穩，就不怕外來的風雨考驗。", example: "基本功練扎實，樹頭徛予在，毋驚樹尾做風颱。", deep: "這句話怎麼來的：臺灣的閩南語俗諺。颱風來時，樹尾搖得再厲害都沒關係，只要樹頭（根部）站得穩，樹就不會倒。\n字面意思：樹頭站得穩，就不怕樹梢遇到颱風。\n引申意思：根基扎實就經得起考驗。它也常被用在做人上——行得正就不怕別人講。" },
  { id: "s122", grade: 6, term: "一暝全頭路，天光無半步", kind: "俚語", meaning: "台語俗諺：夜裡想了一堆計畫，天亮卻一樣也沒做。", example: "光說不練就是一暝全頭路，天光無半步。", deep: "這句話怎麼來的：臺灣的閩南語俗諺。「頭路」是工作、辦法。晚上躺著想了一整夜的計畫，天一亮全部沒動。\n字面意思：一整夜都是辦法，天亮了半步也沒走。\n引申意思：光想不做等於沒做。它笑的是「想得很勤」的人，比笑懶惰更精準。" },
  { id: "s123", grade: 6, term: "甘願做牛，免驚無犁通拖", kind: "俚語", meaning: "台語俗諺：肯吃苦做事，就不怕沒有工作機會。", example: "他什麼粗活都肯學，甘願做牛，免驚無犁通拖。", deep: "這句話怎麼來的：臺灣的閩南語俗諺。從前的牛只要肯拖，田裡永遠有犁等著牠。\n字面意思：只要甘願做牛，不必怕沒有犁可以拖。\n引申意思：肯吃苦就不怕沒工作。它的語氣是安慰，也是提醒——工作不會沒有，怕的是不肯做。" },
  { id: "s124", grade: 7, term: "做牛著拖，做人著磨", kind: "俚語", meaning: "台語俗諺：做人本來就要經歷磨練，吃苦是本分。", example: "阿嬤說做牛著拖，做人著磨，年輕多吃苦不是壞事。", deep: "這句話怎麼來的：臺灣的閩南語俗諺，和「甘願做牛，免驚無犁通拖」是同一組畫面的另一面。\n字面意思：當牛就要拉犁，做人就要受磨。\n引申意思：吃苦是人生的常態。它把「磨」當成本分而不是倒霉，語氣是認命也是堅韌。" },
  { id: "s125", grade: 7, term: "未食五日節粽，破裘毋甘放", kind: "俚語", meaning: "台語俗諺：端午節前天氣多變，冬衣還不能收起來。", example: "五月天忽冷忽熱，未食五日節粽，破裘毋甘放。", deep: "這句話怎麼來的：臺灣的閩南語俗諺。「破裘」是舊棉襖。臺灣端午節前春夏交替，冷熱反覆，收了冬衣往往又要拿出來。\n字面意思：還沒吃到端午節的粽子，舊棉襖捨不得收。\n引申意思：時機沒到不要急著下結論。它是一句生活氣象諺語，同時也被拿來講做事的節奏。" },
  { id: "s126", grade: 7, term: "嚴官府出厚賊", kind: "俚語", meaning: "台語俗諺：一味嚴刑峻罰，未必能遏止犯罪，反而更多。", example: "只罰不教，嚴官府出厚賊，問題依然存在。", deep: "這句話怎麼來的：臺灣的閩南語俗諺。「厚」是多的意思。官府管得越嚴苛，反而逼出更多鋌而走險的人。\n字面意思：嚴厲的官府，出的賊反而多。\n引申意思：只靠嚴刑不能根治問題。它點出的是治理的難處——壓力太大會把人逼到另一邊。" },
  { id: "s127", grade: 8, term: "相罵無好話，相拍無揀位", kind: "俚語", meaning: "台語俗諺：吵架時口不擇言，打架時下手不知輕重。", example: "衝突要冷靜，相罵無好話，相拍無揀位，別造成遺憾。", deep: "這句話怎麼來的：臺灣的閩南語俗諺。「相拍」是打架，「揀位」是挑地方。吵架的時候什麼難聽的話都講得出來，動手的時候也不會挑地方打。\n字面意思：吵架沒有好話，打架不挑部位。\n引申意思：情緒上來時會失去分寸。它是在勸人別把事情鬧到那一步，因為到那一步就收不住了。" },
  { id: "s128", grade: 8, term: "仙人拍鼓有時錯，跤步踏差啥人無", kind: "俚語", meaning: "台語俗諺：連神仙都會出錯，人犯錯在所難免，要寬容。", example: "他已道歉就原諒吧，仙人拍鼓有時錯，跤步踏差啥人無。", deep: "這句話怎麼來的：臺灣的閩南語俗諺。「拍鼓」是打鼓，「跤步踏差」是腳步踏錯。連神仙打鼓都會有失誤的一拍。\n字面意思：仙人打鼓也會打錯，腳步踏錯誰沒有過。\n引申意思：犯錯是難免的，要互相體諒。它是用來替別人（或自己）開脫的話，語氣寬厚。" },
  { id: "s129", grade: 8, term: "燒瓷的食缺，織蓆的睏椅", kind: "俚語", meaning: "台語俗諺：製造好物的人自己反而用不到好東西。", example: "名廚回家常吃泡麵，燒瓷的食缺，織蓆的睏椅。", deep: "這句話怎麼來的：臺灣的閩南語俗諺。燒陶的人自己用有缺口的碗，編草蓆的人自己睡在椅子上——好的都拿去賣了。\n字面意思：燒瓷的人吃缺角的碗，織蓆的人睡在椅子上。\n引申意思：做東西的人自己享受不到。它道出的是勞動者的處境，語氣帶著心酸而不是抱怨。" },
  { id: "s130", grade: 9, term: "拿香跟拜", kind: "俚語", meaning: "台語俗諺：沒有主見，別人做什麼就跟著做什麼。", example: "投資要有判斷，不要看別人買什麼就拿香跟拜。", deep: "這句話怎麼來的：臺灣的閩南語俗諺。廟會時不懂儀式的人就跟在別人後面，別人拿香他也拿香，別人拜他也拜。\n字面意思：拿著香跟在後面拜。\n引申意思：沒有主見，別人做什麼就跟著做。它批評的是「不問為什麼」，不是批評跟隨本身。" },
  { id: "s131", grade: 9, term: "呷碗內，看碗外", kind: "俚語", meaning: "台語俗諺：吃著自己的，還貪圖別人的；吃裡扒外。", example: "領公司薪水卻幫對手做事，根本是呷碗內，看碗外。", deep: "這句話怎麼來的：臺灣的閩南語俗諺。人坐在桌邊吃自己碗裡的飯，眼睛卻一直往別人的碗裡瞄。\n字面意思：吃著碗裡的，眼睛看著碗外的。\n引申意思：得了這個還惦記那個，不專一也不知足。用在感情、工作上都很常見。" },
  { id: "s132", grade: 9, term: "會曉偷食，袂曉拭喙", kind: "俚語", meaning: "台語俗諺：做了虧心事卻不會掩飾，留下把柄。", example: "他刪了紀錄卻忘了關代辦，會曉偷食，袂曉拭喙。", deep: "這句話怎麼來的：臺灣的閩南語俗諺。「拭喙」是擦嘴。偷吃了東西卻忘記把嘴角擦乾淨，一看就被抓包。\n字面意思：會偷吃，不會擦嘴。\n引申意思：做了虧心事又不會掩飾。它笑的重點在「笨拙」，語氣帶著看好戲的意味。" },
  { id: "s133", grade: 10, term: "戲棚跤徛久就是你的", kind: "俚語", meaning: "台語俗諺：肯堅持等待、蹲點耕耘的人終會得到機會。", example: "跑龍套十年終於當上主角，戲棚跤徛久就是你的。", deep: "這句話怎麼來的：臺灣的閩南語俗諺。廟前演野台戲，位置最好的人是最早來、站到最後都不走的那個。\n字面意思：戲棚下站得久，位置就是你的。\n引申意思：肯堅持等下去的人最後會拿到機會。它強調的是「留下來」，不是強調搶。" },
  // 歇後語（27）
  { id: "s134", grade: 2, term: "啞巴吃黃連——有苦說不出", kind: "歇後語", meaning: "心裡有苦處，卻無法對人訴說。", example: "被誤會又不能解釋，他真是啞巴吃黃連——有苦說不出。", deep: "這句話怎麼來的：黃連是極苦的中藥。啞巴吃了說不出話，苦全部往肚子裡吞。\n字面意思：不能說話的人吃黃連。\n引申意思：有苦說不出來。它的重點是「說不出」而不是「不想說」，帶著同情。" },
  { id: "s135", grade: 2, term: "肉包子打狗——有去無回", kind: "歇後語", meaning: "東西送出去就再也要不回來。", example: "借錢給他就像肉包子打狗——有去無回。", deep: "這句話怎麼來的：拿肉包子去打狗，狗會把包子吃了，包子當然回不來。\n字面意思：用肉包子打狗，包子有去無回。\n引申意思：東西送出去就要不回來了。多半用在借錢不還這類事情上，語氣是無奈加調侃。" },
  { id: "s136", grade: 2, term: "熱鍋上的螞蟻——團團轉", kind: "歇後語", meaning: "焦急慌張，走來走去不知如何是好。", example: "找不到門票，他急得像熱鍋上的螞蟻——團團轉。", deep: "這句話怎麼來的：鍋子燒熱之後，鍋面上的螞蟻無處可站，只能不停繞圈。\n字面意思：熱鍋上的螞蟻不停打轉。\n引申意思：急得團團轉卻毫無辦法。它形容的是那種「動個不停但沒有進展」的焦躁。" },
  { id: "s137", grade: 3, term: "貓哭耗子——假慈悲", kind: "歇後語", meaning: "假裝同情憐憫，其實心懷鬼胎。", example: "平時欺負人，現在來慰問？貓哭耗子——假慈悲。", deep: "這句話怎麼來的：貓是老鼠的天敵，看到老鼠死了卻掉眼淚，當然是裝的。\n字面意思：貓為老鼠的死哭泣。\n引申意思：假裝同情。它比一般的「假好心」更重，因為哭的正是加害者。" },
  { id: "s138", grade: 3, term: "千里送鵝毛——禮輕情意重", kind: "歇後語", meaning: "禮物雖輕，情意卻深厚。", example: "這張手寫卡片是千里送鵝毛——禮輕情意重。", deep: "典故由來：唐代有人替回紇進貢天鵝，途中天鵝飛走只剩一根羽毛，他仍把鵝毛獻上並說「禮輕情意重，千里送鵝毛」。\n字面意思：從一千里外送來一根鵝毛。\n引申意思：禮物本身不值錢，心意才是重點。它是送禮方或收禮方用來化解尷尬的話。" },
  { id: "s139", grade: 3, term: "芝麻開花——節節高", kind: "歇後語", meaning: "情況一節比一節好，不斷進步。", example: "小店生意芝麻開花——節節高，準備開分店了。", deep: "這句話怎麼來的：芝麻的花是一節一節往上開的，越往上開得越高。\n字面意思：芝麻開花，一節比一節高。\n引申意思：情況一天比一天好。它是純正面的祝福語，常寫在春聯或賀詞裡。" },
  { id: "s140", grade: 3, term: "兔子尾巴——長不了", kind: "歇後語", meaning: "形容事物維持不了多久。", example: "靠炒作的名氣是兔子尾巴——長不了。", deep: "這句話怎麼來的：兔子的尾巴天生短短一撮，怎麼長都長不了。\n字面意思：兔子的尾巴長不長。\n引申意思：這件事撐不了多久。它用來預言某個局面或某個人的得意快結束了，帶著看衰的口氣。" },
  { id: "s141", grade: 4, term: "王婆賣瓜——自賣自誇", kind: "歇後語", meaning: "自己誇耀自己的東西好。", example: "他猛稱讚自家產品，王婆賣瓜——自賣自誇。", deep: "典故由來：宋代有個賣瓜的西域人姓王（一說是王坡），他在市集上自己誇自己的瓜甜，宋神宗聽了說「王婆賣瓜，自賣自誇」。\n字面意思：王婆賣瓜，自己誇自己的瓜好。\n引申意思：自我吹捧。它的語氣是調侃而不是嚴厲指責，有時說自己也可以用。" },
  { id: "s142", grade: 4, term: "姜太公釣魚——願者上鉤", kind: "歇後語", meaning: "心甘情願地上當或參與，怨不得別人。", example: "這種高價課程，姜太公釣魚——願者上鉤。", deep: "典故由來：姜太公在渭水釣魚，用的是直鉤而且不掛餌，還離水三寸，說「願者上鉤」——他要釣的其實是懂他的人，後來周文王果然來請他。\n字面意思：姜太公釣魚，願意的自己上鉤。\n引申意思：不強求，願意的自己會來。它也可以用在被騙的人身上——你自己願意的，怪不了別人。" },
  { id: "s143", grade: 4, term: "啞巴吃湯圓——心裡有數", kind: "歇後語", meaning: "嘴上不說，心裡清楚得很。", example: "誰出多少力，大家啞巴吃湯圓——心裡有數。", deep: "這句話怎麼來的：湯圓有沒有包餡、餡是什麼，吃的人最清楚；啞巴說不出來，但心裡數得一清二楚。\n字面意思：不能說話的人吃湯圓，心裡有數。\n引申意思：嘴上不說，心裡明白得很。它和「啞巴吃黃連」用同一個角色，但情緒完全不同——那句是苦，這句是懂。" },
  { id: "s144", grade: 4, term: "猴子撈月——一場空", kind: "歇後語", meaning: "白忙一場，什麼也得不到。", example: "跟風搶購虛擬幣，最後猴子撈月——一場空。", deep: "典故由來：出自佛經故事，也見於民間傳說。一群猴子看到井裡的月亮以為掉下來了，一隻接一隻倒吊著去撈，撈到的只有水。\n字面意思：猴子去井裡撈月亮，撈到一場空。\n引申意思：追求的是根本不存在的東西。它比「白費力氣」更進一層——不只是沒成功，而是目標本身就是幻影。" },
  { id: "s145", grade: 5, term: "外甥打燈籠——照舊（舅）", kind: "歇後語", meaning: "諧音雙關：一切照老樣子，沒有改變。", example: "說要改革，結果外甥打燈籠——照舊。", deep: "這句話怎麼來的：靠的是諧音。外甥替舅舅打燈籠照路，「照舅」聽起來就是「照舊」。\n字面意思：外甥打著燈籠照舅舅。\n引申意思：一切維持原樣沒有改變。這是歇後語裡的諧音類，答案在同音字上，不在字面意思上。" },
  { id: "s146", grade: 5, term: "孔夫子搬家——盡是書（輸）", kind: "歇後語", meaning: "諧音雙關：一直輸，沒贏過。", example: "這支隊伍本季孔夫子搬家——盡是書（輸）。", deep: "這句話怎麼來的：也是諧音。孔夫子家裡最多的就是書，「書」和「輸」同音。\n字面意思：孔夫子搬家，箱子裡全是書。\n引申意思：一直輸，沒有贏過。這句常出現在打牌或比賽的場合，是帶笑的挖苦。" },
  { id: "s147", grade: 5, term: "門縫裡看人——把人看扁了", kind: "歇後語", meaning: "小看、輕視別人。", example: "說我不行？你這是門縫裡看人——把人看扁了。", deep: "這句話怎麼來的：從門縫往外看，人被壓成細細一條，看起來就扁了。\n字面意思：從門縫裡看人，人是扁的。\n引申意思：小看、輕視別人。它妙在雙關——視覺上真的變扁，心理上也是把人看低了。" },
  { id: "s148", grade: 5, term: "小蔥拌豆腐——一清二白", kind: "歇後語", meaning: "清清楚楚，毫無瓜葛污點。", example: "帳目攤開檢查，小蔥拌豆腐——一清二白。", deep: "這句話怎麼來的：這是一道家常涼菜，青色的蔥花配白色的豆腐，端上桌就是一青（清）一白。\n字面意思：小蔥拌豆腐，一青二白。\n引申意思：用「青」和「清」的諧音，說事情或人品清白分明。它強調的是「攤開來給人看」，不只是沒做壞事。" },
  { id: "s149", grade: 6, term: "秀才遇到兵——有理說不清", kind: "歇後語", meaning: "對不講道理的人，再有道理也講不通。", example: "跟蠻橫的人爭辯，秀才遇到兵——有理說不清。", deep: "這句話怎麼來的：秀才讀的是道理，兵靠的是力氣。兩邊講的不是同一套規則，所以怎麼說都說不通。\n字面意思：讀書人遇到當兵的，道理講不清楚。\n引申意思：對不講理的人講道理是白費力氣。它並不是在罵當兵的，而是在說「規則不同就無法溝通」。" },
  { id: "s150", grade: 6, term: "和尚打傘——無法（髮）無天", kind: "歇後語", meaning: "諧音雙關：目無法紀，胡作非為。", example: "飆車族深夜橫行，簡直和尚打傘——無法無天。", deep: "這句話怎麼來的：靠的是諧音。和尚沒有頭髮（無髮），打了傘就看不到天（無天），「無髮無天」聽起來就是「無法無天」。\n字面意思：和尚撐傘，沒有頭髮也看不見天。\n引申意思：目無法紀、胡作非為。這是雙關型歇後語，兩個諧音疊在一起才成立。" },
  { id: "s151", grade: 6, term: "泥牛入海——無消息", kind: "歇後語", meaning: "一去不回，音訊全無。", example: "履歷投出去像泥牛入海——無消息。", deep: "典故由來：出自禪宗語錄。有僧人說自己見到「兩個泥牛鬥入海，直至如今無消息」，形容一去不返。\n字面意思：泥做的牛走進海裡，再也沒有消息。\n引申意思：一去不回、音訊全無。泥牛下水會化掉，所以它暗示的不只是沒回來，而是已經沒有了。" },
  { id: "s152", grade: 6, term: "飛蛾撲火——自取滅亡", kind: "歇後語", meaning: "自己往危險裡衝，自尋死路。", example: "明知是詐騙還把錢匯過去，飛蛾撲火——自取滅亡。", deep: "典故由來：出自《梁書．到溉傳》：「如飛蛾之赴火，豈焚身之可吝。」原本帶著讚嘆奮不顧身的味道。\n字面意思：飛蛾撲向火，燒死自己。\n引申意思：自己往危險裡衝。現在多半是責備，但要記得它原本也可以形容不顧一切的執著。" },
  { id: "s153", grade: 7, term: "周瑜打黃蓋——一個願打，一個願挨", kind: "歇後語", meaning: "雙方你情我願，旁人管不著。", example: "加價搶演唱會票，周瑜打黃蓋——一個願打，一個願挨。", deep: "典故由來：出自《三國演義》的赤壁之戰。黃蓋為了詐降騙曹操，主動請周瑜當眾把自己打得皮開肉綻，這是兩人講好的「苦肉計」。\n字面意思：周瑜打黃蓋，一個願意打，一個願意挨。\n引申意思：雙方你情我願，旁人管不著。它的前提是「事先講好」，不是單方面挨打。" },
  { id: "s154", grade: 7, term: "韓信點兵——多多益善", kind: "歇後語", meaning: "越多越好。", example: "備援物資韓信點兵——多多益善。", deep: "典故由來：出自《史記．淮陰侯列傳》。劉邦問韓信自己能帶多少兵，韓信說十萬；問韓信自己呢，韓信答「臣多多而益善耳」。\n字面意思：韓信點兵，越多越好。\n引申意思：數量越多越好。原典其實還有下一句——劉邦問那你怎麼被我抓住，韓信說陛下不善將兵而善將將。" },
  { id: "s155", grade: 7, term: "豬八戒照鏡子——裡外不是人", kind: "歇後語", meaning: "兩面都得罪，兩頭不討好。", example: "夾在婆媳之間，他豬八戒照鏡子——裡外不是人。", deep: "這句話怎麼來的：豬八戒本來是天蓬元帥，被貶下凡成了豬的模樣。他照鏡子，鏡裡鏡外都是豬臉，怎麼看都不是人。\n字面意思：豬八戒照鏡子，裡面外面都不是人。\n引申意思：兩邊都得罪、兩頭不討好。它用「不是人」的雙關，同時講外貌和處境。" },
  { id: "s156", grade: 8, term: "大水沖倒龍王廟——自家人不認自家人", kind: "歇後語", meaning: "自己人之間起了衝突誤會。", example: "兩個部門搶功勞，大水沖倒龍王廟——自家人不認自家人。", deep: "這句話怎麼來的：龍王是管水的神，大水卻把龍王自己的廟沖倒了，等於自家的水淹了自家的門。\n字面意思：大水沖倒龍王廟，自家人不認得自家人。\n引申意思：自己人之間起了衝突誤會。它常在誤會解開時說，語氣是化解而不是責怪。" },
  { id: "s157", grade: 8, term: "司馬昭之心——路人皆知", kind: "歇後語", meaning: "野心陰謀十分明顯，人人都看得出來。", example: "他處處布局搶位子，司馬昭之心——路人皆知。", deep: "典故由來：出自《三國志》。魏帝曹髦說「司馬昭之心，路人所知也」，指司馬昭想篡位的野心連街上的路人都看得出來。\n字面意思：司馬昭的心思，路上的人都知道。\n引申意思：野心明顯到不必再說。它的重點在「連不相干的人都看得出來」，代表對方根本沒有掩飾。" },
  { id: "s158", grade: 8, term: "電線桿上綁雞毛——好大的撢（膽）子", kind: "歇後語", meaning: "諧音雙關：膽子真大。", example: "敢偽造公文？電線桿上綁雞毛——好大的膽子。", deep: "這句話怎麼來的：靠的是諧音。雞毛可以做撢子，綁在高高的電線桿上就是一支很大的「撢子」，聽起來就是「膽子」。\n字面意思：電線桿上綁雞毛，成了好大的撢子。\n引申意思：膽子真大。這句多半用在嘲諷的場合，說對方做的事太過分。" },
  { id: "s159", grade: 9, term: "擀麵杖吹火——一竅不通", kind: "歇後語", meaning: "比喻對某事完全不懂。", example: "說到程式設計，我是擀麵杖吹火——一竅不通。", deep: "這句話怎麼來的：擀麵杖是實心的木棒，中間沒有孔，拿來吹火當然一點也吹不動。「竅」既指孔洞，也指竅門。\n字面意思：用實心的擀麵杖吹火，一個孔也不通。\n引申意思：對某件事完全外行。它妙在「竅」的雙關——沒有孔，也沒有門道。" },
  { id: "s160", grade: 9, term: "周處除三害——自新之路", kind: "歇後語", meaning: "改過向善，重新做人。", example: "他出獄後創業助人，走上周處除三害——自新之路。", deep: "典故由來：出自《世說新語》。周處年輕時橫行鄉里，被鄉人和南山虎、長橋蛟並稱三害；他殺虎斬蛟回來，才知道自己也是一害，於是發憤改過。\n字面意思：周處除掉三害，走上改過自新的路。\n引申意思：知錯能改，重新做人。故事的關鍵是他先聽到別人怎麼說他，肯認自己就是第三害。" },
  // ---- 2026-08-02 三輪擴充:s161-s240 ----
  // 諺語(30)
  { id: "s161", grade: 1, term: "吃得苦中苦，方為人上人", kind: "諺語", meaning: "能忍受艱苦磨練的人，才能出人頭地。", example: "阿公常說吃得苦中苦，方為人上人，勉勵我們別怕辛苦。", deep: "這句話怎麼來的：民間流傳的勵志語，明清小說裡已經在用，常和「不受苦中苦，難為人上人」互相對照。\n字面意思：吃得下苦中最苦的，才能成為人上之人。\n引申意思：忍得住磨練才能出頭。要注意它預設了「吃苦一定有回報」，但吃苦本身並不保證成功，方向對不對也很重要。" },
  { id: "s162", grade: 1, term: "萬丈高樓平地起", kind: "諺語", meaning: "再大的成就也要從基礎開始。", example: "先把注音學好，萬丈高樓平地起。", deep: "這句話怎麼來的：源自民間的建築常識，也常寫成「萬丈高樓從地起」，形容再高的樓也是從平地一磚一瓦砌上去的。\n字面意思：一萬丈高的樓，也是從平地開始蓋的。\n引申意思：成就要從基礎開始累積。它和「千里之行始於足下」意思相近，這句更強調「基礎要打穩」。" },
  { id: "s163", grade: 2, term: "好的開始是成功的一半", kind: "諺語", meaning: "開頭做得好，成功就有了一半把握。", example: "第一週就養成寫作業的習慣，好的開始是成功的一半。", deep: "典故由來：源自西方諺語 Well begun is half done，一般追到亞里斯多德的說法，中文譯為「好的開始是成功的一半」。\n字面意思：好的開頭，等於成功了一半。\n引申意思：開頭做得好，後面會順很多。它的另一面是——開頭做壞了，後面要花加倍的力氣去補。" },
  { id: "s164", grade: 2, term: "今日事，今日畢", kind: "諺語", meaning: "今天該做的事今天就做完，不要拖到明天。", example: "作業別留到睡前才寫，今日事今日畢。", deep: "這句話怎麼來的：明代《明日歌》唱「明日復明日，明日何其多」，民間把它濃縮成「今日事，今日畢」這句口訣。\n字面意思：今天的事，今天做完。\n引申意思：不拖延。它真正防的不是一天的落後，而是拖延會累積——今天推給明天，明天又有明天的事。" },
  { id: "s165", grade: 2, term: "一回生，二回熟", kind: "諺語", meaning: "第一次陌生，第二次就熟練了。", example: "上台別緊張，一回生，二回熟。", deep: "這句話怎麼來的：民間口語，「生」是生疏、「熟」是熟練，講的是任何手上的活第二次做就順了。\n字面意思：第一次生疏，第二次就熟了。\n引申意思：不熟只是因為還沒做過。它常用來鼓勵第一次上手的人，重點在「先做過一次」。" },
  { id: "s166", grade: 3, term: "師父領進門，修行在個人", kind: "諺語", meaning: "老師只能引導，成就要靠自己努力。", example: "補習只是輔助，師父領進門，修行在個人。", deep: "這句話怎麼來的：從前學手藝要拜師，師父教的是入門的規矩和方法，能到什麼程度就看徒弟自己下多少工夫。\n字面意思：師父把你領進門，修行要靠你自己。\n引申意思：老師只能引導，成就靠自己。它同時說了兩件事——沒有師父進不了門，有了師父也不會自動變強。" },
  { id: "s167", grade: 3, term: "台上一分鐘，台下十年功", kind: "諺語", meaning: "精彩的演出背後是長年的苦練。", example: "特技演員台上一分鐘，台下十年功。", deep: "這句話怎麼來的：從戲曲和雜技行業來的行話，講的是台上短短一分鐘的精彩，背後是台下十年的苦練。\n字面意思：台上表演一分鐘，台下要練十年功夫。\n引申意思：看得見的成果背後有看不見的累積。它提醒的是別只羨慕結果，因為過程外人看不到。" },
  { id: "s168", grade: 3, term: "眾人拾柴火焰高", kind: "諺語", meaning: "人多力量大，共同努力成效更好。", example: "義賣募款眾人拾柴火焰高，很快達標。", deep: "這句話怎麼來的：燒柴取暖或煮飯時，每個人都丟一根柴進去，火自然就旺了。\n字面意思：大家一起撿柴，火燒得比較旺。\n引申意思：人多一起出力，成效更好。它的前提是「每個人都真的丟了一根柴」，光是人多沒有用。" },
  { id: "s169", grade: 3, term: "遠水救不了近火", kind: "諺語", meaning: "緩慢的辦法解決不了眼前的急難。", example: "調貨要一週，遠水救不了近火，先跟鄰店借吧。", deep: "典故由來：出自《韓非子．說林上》：「失火而取水於海，海水雖多，火必不滅矣，遠水不救近火也。」\n字面意思：遠處的水救不了近處的火。\n引申意思：來不及的辦法等於沒有辦法。韓非用它講外交——找太遠的盟友，急難時趕不上。" },
  { id: "s170", grade: 4, term: "不經一事，不長一智", kind: "諺語", meaning: "沒有經歷過就不會增長見識。", example: "被騙過一次才學會查證，不經一事，不長一智。", deep: "這句話怎麼來的：民間口語，常和「吃一塹，長一智」連著說，都是講經驗和見識的關係。\n字面意思：沒有經歷過一件事，就長不出那一分見識。\n引申意思：見識來自親身經歷。它也解釋了為什麼有些道理聽了沒用——沒經歷過就是聽不進去。" },
  { id: "s171", grade: 4, term: "吃一塹，長一智", kind: "諺語", meaning: "受一次挫折，長一分見識。", example: "投資失利後他學會分散風險，吃一塹，長一智。", deep: "典故由來：出自明代王陽明《與薛尚謙書》：「經一蹶者長一智。」「塹」是壕溝，跌進去一次就學會一次。\n字面意思：掉進一次坑，長一分智慧。\n引申意思：挫折換來經驗。重點在「長一智」——跌了卻沒學到，那一跤就白跌了。" },
  { id: "s172", grade: 4, term: "當局者迷，旁觀者清", kind: "諺語", meaning: "當事人容易迷惑，旁觀的人反而看得清楚。", example: "你先聽聽別人怎麼看，當局者迷，旁觀者清。", deep: "典故由來：出自《舊唐書．元行沖傳》：「當局稱迷，傍觀必審。」原本是在講下棋的人和看棋的人。\n字面意思：下棋的人迷糊，旁邊看的人清楚。\n引申意思：當事人容易看不清，旁人反而看得明白。它的原因是當事人有情緒和利害，旁人沒有。" },
  { id: "s173", grade: 4, term: "禮多人不怪", kind: "諺語", meaning: "多行禮數不會惹人厭。", example: "進門先問好，禮多人不怪。", deep: "這句話怎麼來的：民間人情往來的常語，「禮」既指禮物，也指禮數、規矩。\n字面意思：禮數做多了，不會有人怪你。\n引申意思：多一分客氣比較保險。它是實用的處世建議，但也有反面——過度的禮反而讓人有壓力。" },
  { id: "s174", grade: 4, term: "和氣生財", kind: "諺語", meaning: "待人和氣才能招來生意與福氣。", example: "老闆娘總是笑臉迎人，和氣生財。", deep: "這句話怎麼來的：商家門口常掛的話，做生意講究人來人往，臉色好客人才願意再上門。\n字面意思：和氣可以生出財富。\n引申意思：態度好才有機會。它把「和氣」當成賺錢的方法，語氣是務實的，不是純粹的道德勸說。" },
  { id: "s175", grade: 5, term: "路是人走出來的", kind: "諺語", meaning: "方法和機會靠人開創。", example: "沒有前例就自己開先例，路是人走出來的。", deep: "典故由來：化用自魯迅〈故鄉〉的名句「其實地上本沒有路，走的人多了，也便成了路」。\n字面意思：路是人一步一步走出來的。\n引申意思：沒有現成的辦法，就自己走出一條。它的力量在於承認一開始真的沒有路。" },
  { id: "s176", grade: 5, term: "船到橋頭自然直", kind: "諺語", meaning: "事情到了關頭自有辦法解決，不必過度擔憂。", example: "先盡力準備，其他的船到橋頭自然直。", deep: "這句話怎麼來的：從行船來的。船順著水流走，看起來要撞上橋，到了橋洞前水流會把船帶正，自然就直了。\n字面意思：船開到橋頭，自然就會擺正。\n引申意思：事情到了關頭自有解法，不必先擔心。它勸的是別提前焦慮，不是叫人什麼都不準備。" },
  { id: "s177", grade: 5, term: "人算不如天算", kind: "諺語", meaning: "人的謀劃敵不過情勢的變化。", example: "行程排好卻遇颱風，人算不如天算。", deep: "這句話怎麼來的：民間常語，明清小說裡多見，用來感嘆計畫趕不上變化。\n字面意思：人的計算比不上上天的計算。\n引申意思：再周密的謀劃也可能被情勢推翻。它是說完之後用來釋懷的話，通常出現在事情已經無法挽回的時候。" },
  { id: "s178", grade: 5, term: "謀事在人，成事在天", kind: "諺語", meaning: "盡力籌劃是人的本分，成敗還受環境影響。", example: "把能做的做好，謀事在人，成事在天。", deep: "典故由來：出自《三國演義》。諸葛亮火燒司馬懿於上方谷，眼看要成功卻下起大雨，孔明嘆道「謀事在人，成事在天」。\n字面意思：計畫是人做的，能不能成要看天。\n引申意思：盡力是本分，結果不全在自己。它和「盡人事聽天命」意思相同，這句因為《三國演義》而更廣為人知。" },
  { id: "s179", grade: 5, term: "強將手下無弱兵", kind: "諺語", meaning: "能幹的領導者帶出來的部屬也不差。", example: "冠軍教頭的子弟兵個個出色，強將手下無弱兵。", deep: "典故由來：出自蘇軾〈題連公壁〉：「強將手下無弱兵，真可信。」\n字面意思：能幹的將領手下沒有弱的兵。\n引申意思：帶領的人夠強，底下的人也不會差。它把功勞算在領導者身上，所以常用來稱讚主管或教練。" },
  { id: "s180", grade: 5, term: "嚴師出高徒", kind: "諺語", meaning: "要求嚴格的老師能教出優秀的學生。", example: "他的老師出了名的嚴，嚴師出高徒。", deep: "這句話怎麼來的：民間對師徒關係的說法，常和「慈母多敗兒」對照著講。\n字面意思：嚴格的老師教得出高明的徒弟。\n引申意思：要求高才練得出真本事。要注意「嚴」指的是標準嚴，不是態度兇——這兩件事現在常被混為一談。" },
  { id: "s181", grade: 6, term: "家醜不可外揚", kind: "諺語", meaning: "家裡不光彩的事情不要說給外人聽。", example: "兄弟吵架關起門來解決就好，家醜不可外揚。", deep: "這句話怎麼來的：宋代禪宗語錄裡就有「家醜不外揚」的說法，後來成為民間處理家務事的原則。\n字面意思：家裡難看的事，不要傳到外面去。\n引申意思：內部的問題內部處理。這句話有它的問題——遇到家暴、虐待這類事，「不外揚」反而會讓受害的人求助無門。" },
  { id: "s182", grade: 6, term: "一樣米養百樣人", kind: "諺語", meaning: "同樣的環境養出各種不同性格的人。", example: "同班同學個性天差地遠，一樣米養百樣人。", deep: "這句話怎麼來的：民間常語，也說「一樣米飼百樣人」。同一片田的米養大了一百個人，個性卻各不相同。\n字面意思：同樣的米，養出一百種不同的人。\n引申意思：人的性格千差萬別。它多半用在遇到難以理解的人時，語氣是感嘆也是接受。" },
  { id: "s183", grade: 6, term: "雷聲大，雨點小", kind: "諺語", meaning: "聲勢弄得很大，實際做出來的事情卻很少。", example: "喊了半年要改革，結果雷聲大雨點小，什麼也沒改。", deep: "這句話怎麼來的：夏天的雷陣雨有時打雷打得驚天動地，真正落下來的雨卻只有幾滴就停了。\n字面意思：雷打得很響，雨卻下得很小。\n引申意思：宣布得很大聲，執行得很少。它批評的是「說到做不到」，不是批評聲勢本身。" },
  { id: "s184", grade: 6, term: "貨比三家不吃虧", kind: "諺語", meaning: "多比較再購買才不會吃虧。", example: "買手機前他貨比三家不吃虧，省了兩千元。", deep: "這句話怎麼來的：從市集買賣來的常語，「三家」是虛數，指多問幾家、多比幾次。\n字面意思：貨要比過三家才不會吃虧。\n引申意思：多比較再決定。它防的不只是價格，還有品質和條件——只比價格一樣會吃虧。" },
  { id: "s185", grade: 7, term: "醉翁之意不在酒", kind: "諺語", meaning: "表面做一件事，真正目的在別處。", example: "他頻頻來請教功課，醉翁之意不在酒，是想約妹妹打球。", deep: "典故由來：出自歐陽脩〈醉翁亭記〉：「醉翁之意不在酒，在乎山水之間也。」\n字面意思：喝醉的老翁真正在意的不是酒。\n引申意思：表面做這件事，真正目的在別處。原文的「別處」是山水，是很美的；現在用它多半帶著懷疑的意味。" },
  { id: "s186", grade: 7, term: "近水樓臺先得月", kind: "諺語", meaning: "接近有利環境的人先獲得好處。", example: "住學校旁的他天天泡圖書館，近水樓臺先得月。", deep: "典故由來：宋代范仲淹在杭州提拔身邊的人，外地官員蘇麟寫詩暗示自己被漏掉：「近水樓臺先得月，向陽花木易為春。」\n字面意思：靠水邊的樓臺，最先照到月亮的倒影。\n引申意思：位置佔得近的人先得好處。原句是委婉的抱怨，所以這句話帶著一點「不太公平」的味道。" },
  { id: "s187", grade: 8, term: "初生之犢不畏虎", kind: "諺語", meaning: "年輕人沒有顧忌，敢做敢衝。", example: "高一新生敢挑戰學長，初生之犢不畏虎。", deep: "典故由來：出自《莊子．知北遊》的「猶犢之無母」與後世「初生之犢不畏虎」的俗語，形容剛出生的小牛沒見過老虎，所以不怕。\n字面意思：剛出生的小牛不怕老虎。\n引申意思：年輕人沒有顧忌，敢衝敢闖。它同時是稱讚和提醒——不怕是因為不知道，勇氣裡有無知的成分。" },
  { id: "s188", grade: 8, term: "薑是老的辣", kind: "諺語", meaning: "年長者經驗豐富，手段更高明。", example: "老師傅一出手就解決問題，薑是老的辣。", deep: "這句話怎麼來的：老薑放得久，辛辣味更濃更沉，比嫩薑辣得多。\n字面意思：老的薑比較辣。\n引申意思：年長的人經驗老到、手段高明。它常和「初生之犢不畏虎」對著用，一邊是勇氣，一邊是火候。" },
  { id: "s189", grade: 9, term: "士別三日，刮目相看", kind: "諺語", meaning: "人會進步，過些時候要用新眼光看待。", example: "半年不見他英文突飛猛進，士別三日，刮目相看。", deep: "典故由來：出自《三國志》。呂蒙原本不讀書，受孫權勸告後苦讀，魯肅再見到他大為驚訝，呂蒙說「士別三日，即更刮目相待」。\n字面意思：讀書人分開三天，就要擦亮眼睛重新看待。\n引申意思：人會進步，不能用舊印象看人。「刮目」是把眼睛擦一擦，暗示舊眼光是一層灰。" },
  { id: "s190", grade: 9, term: "一山不容二虎", kind: "諺語", meaning: "同一個地方容不下兩個同樣強勢的人。", example: "兩個組長都想主導，一山不容二虎，最後只好拆成兩組。", deep: "這句話怎麼來的：老虎是獨居的猛獸，一頭老虎要占一整片山當自己的地盤，兩頭碰上就會相鬥。\n字面意思：一座山養不了兩隻老虎。\n引申意思：兩個強者難以共處。它描述的是現象，不是說一定要有人離開——換個說法就是「地盤要先分清楚」。" },
  // 台灣俗諺(俚語,25)
  { id: "s191", grade: 1, term: "食果子拜樹頭", kind: "俚語", meaning: "台語俗諺:吃果子要感謝果樹，比喻懂得感恩。", example: "領獎時他感謝啟蒙教練，食果子拜樹頭。", deep: "這句話怎麼來的：臺灣的閩南語俗諺，完整說法是「食果子拜樹頭，食米飯拜田頭」。\n字面意思：吃果子的時候要拜那棵樹的根。\n引申意思：得到好處要記得源頭是誰。和「飲水思源」意思相同，但畫面更土親、更常用在生活口語。" },
  { id: "s192", grade: 2, term: "說曹操，曹操到", kind: "俚語", meaning: "正在講到某個人，那個人就出現了。", example: "我們才剛提到他，他就走進來，真是說曹操，曹操到。", deep: "典故由來：源自三國故事。漢獻帝被困時有人建議召曹操來救駕，話還沒說完曹操的兵馬就到了，後來被《三國演義》的情節帶動成為俗語。\n字面意思：話才說到曹操，曹操就到了。\n引申意思：說人人到，巧到讓人愣一下。用的時候通常帶著一點被抓包的尷尬，所以不會用在說人壞話被聽到的場合以外的正式場合。" },
  { id: "s193", grade: 2, term: "細漢毋通看無", kind: "俚語", meaning: "台語俗諺:不要小看年紀小或勢力小的人。", example: "學弟球速驚人，細漢毋通看無。", deep: "這句話怎麼來的：臺灣的閩南語俗諺。「細漢」是小、年紀輕，「看無」是看不起。\n字面意思：不要因為對方小就看不起他。\n引申意思：別小看年紀輕或勢力小的人。它常接在後面的意思是——今天小的，明天不一定小。" },
  { id: "s194", grade: 3, term: "人兩腳，錢四腳", kind: "俚語", meaning: "台語俗諺:錢難追，人追錢追不上，勸人腳踏實地。", example: "別想一夜致富，人兩腳，錢四腳。", deep: "這句話怎麼來的：臺灣的閩南語俗諺。人只有兩隻腳，錢有四隻腳，人追錢當然追不上。\n字面意思：人有兩隻腳，錢有四隻腳。\n引申意思：想靠追錢致富追不到。它勸的是把力氣放在把事情做好上，錢自然會來，不要本末倒置。" },
  { id: "s195", grade: 3, term: "第一憨，種甘蔗予會社磅", kind: "俚語", meaning: "台語俗諺:譏諷吃虧還任人擺布的傻事。", example: "簽這種不平等契約，是第一憨，種甘蔗予會社磅。", deep: "這句話怎麼來的：日治時期臺灣蔗農把甘蔗賣給製糖會社，會社的磅秤由自己控制，農民只能任其秤重，吃了虧也無處講。\n字面意思：第一傻，就是種甘蔗讓會社去過磅。\n引申意思：明知會被占便宜還任人擺布。這句話背後是一段真實的歷史，語氣是自嘲也是不平。" },
  { id: "s196", grade: 3, term: "有樣看樣，無樣家己想", kind: "俚語", meaning: "台語俗諺:有榜樣就學，沒有就自己動腦。", example: "創業沒人帶，有樣看樣，無樣家己想。", deep: "這句話怎麼來的：臺灣的閩南語俗諺。「家己」是自己。從前學手藝就是看師傅怎麼做，看不到就自己摸索。\n字面意思：有樣子就照樣子做，沒有樣子就自己想。\n引申意思：能模仿就模仿，沒得模仿就自己動腦。它肯定的是「不要停在那裡等人教」。" },
  { id: "s197", grade: 4, term: "緊事寬辦", kind: "俚語", meaning: "台語俗諺:越急的事越要沉著處理。", example: "越到截止日越要緊事寬辦，才不會出錯。", deep: "這句話怎麼來的：臺灣的閩南語俗諺。「寬」是慢、從容。越急的事越容易出錯，反而要沉住氣。\n字面意思：急的事情要慢慢辦。\n引申意思：越急越要穩。它和「呷緊弄破碗」是同一個道理，這句更像做事的方法，那句更像結果的警告。" },
  { id: "s198", grade: 4, term: "呷飯皇帝大", kind: "俚語", meaning: "台語俗諺:吃飯時最大，什麼事都先擱下。", example: "先讓工人吃飽再談公事，呷飯皇帝大。", deep: "這句話怎麼來的：臺灣的閩南語俗諺。從前農家做工辛苦，吃飯是唯一能停下來的時間，連皇帝也不能打斷。\n字面意思：吃飯的時候，比皇帝還大。\n引申意思：吃飯的時候什麼事都先擱下。它其實是在保護休息的權利，語氣半開玩笑，道理很認真。" },
  { id: "s199", grade: 4, term: "歹戲拖棚", kind: "俚語", meaning: "台語俗諺:難看的戲偏偏拖得長，事情糟又拖延。", example: "這場糾紛歹戲拖棚，吵了半年沒結果。", deep: "這句話怎麼來的：臺灣的閩南語俗諺。從前野台戲一演好幾天，戲不好看又拖著不結束，台下的人只好乾坐。\n字面意思：難看的戲偏偏拖很久才下棚。\n引申意思：事情又糟又拖，讓人不耐煩。它常用在政治或八卦上，抱怨的重點是「早該結束了」。" },
  { id: "s200", grade: 4, term: "生食都無夠，閣有通曝乾", kind: "俚語", meaning: "台語俗諺:現吃都不夠了，哪還有得晒乾存起來。", example: "薪水月月見底，生食都無夠，閣有通曝乾？", deep: "這句話怎麼來的：臺灣的閩南語俗諺。「曝乾」是曬乾保存。收成少到現吃都不夠，當然沒有多的可以曬起來。\n字面意思：新鮮的都不夠吃了，哪還有得曬乾。\n引申意思：連眼前都應付不了，談不上多餘的打算。它是用來回絕別人額外要求的話。" },
  { id: "s201", grade: 5, term: "頂司管下司，鋤頭管畚箕", kind: "俚語", meaning: "台語俗諺:層層節制，一物剋一物。", example: "公司層級分明，頂司管下司，鋤頭管畚箕。", deep: "這句話怎麼來的：臺灣的閩南語俗諺。「頂司」是上級、「下司」是下級。鋤頭挖了土，土要靠畚箕裝走，一物管一物。\n字面意思：上級管下級，鋤頭管畚箕。\n引申意思：層層節制，各有各的剋星。它是描述現實的話，語氣帶著無奈的認命。" },
  { id: "s202", grade: 5, term: "做著歹田望後冬", kind: "俚語", meaning: "台語俗諺:這次收成不好，寄望下一季，永保希望。", example: "今年業績差，做著歹田望後冬，明年再拚。", deep: "這句話怎麼來的：臺灣的閩南語俗諺。「後冬」是下一期的收成。田不好收成差，農民只能盼下一季。\n字面意思：種到不好的田，就盼下一季。\n引申意思：這次不順就寄望下一次。它是農民面對天候的態度——不能改變的事，就把希望往前推一格。" },
  { id: "s203", grade: 5, term: "一個錢，拍二十四個結", kind: "俚語", meaning: "台語俗諺:形容人極度節儉、捨不得花錢。", example: "阿伯一個錢拍二十四個結，省出三間房。", deep: "這句話怎麼來的：臺灣的閩南語俗諺。從前的錢用繩子串著，包錢的布打二十四個結，等於捨不得解開來用。\n字面意思：一塊錢，打了二十四個結。\n引申意思：極度節儉、捨不得花錢。它是誇張的說法，帶著調侃，不完全是責備。" },
  { id: "s204", grade: 5, term: "軟土深掘", kind: "俚語", meaning: "台語俗諺:欺負好說話的人，得寸進尺。", example: "他越客氣對方越過分，真是軟土深掘。", deep: "這句話怎麼來的：臺灣的閩南語俗諺。土質軟的地方，鋤頭一挖就下去很深，越軟挖得越深。\n字面意思：土軟的地方就挖得深。\n引申意思：欺負好說話的人會得寸進尺。它同時提醒被欺負的一方——一直退讓，對方只會挖得更深。" },
  { id: "s205", grade: 6, term: "臺灣錢，淹跤目", kind: "俚語", meaning: "台語俗諺:形容早年台灣經濟繁榮、賺錢容易。", example: "八〇年代臺灣錢淹跤目，工廠訂單接不完。", deep: "這句話怎麼來的：臺灣的閩南語俗諺。「跤目」是腳踝。形容早年臺灣錢多到淹過腳踝，是一九八〇年代經濟起飛時最常聽到的話。\n字面意思：臺灣的錢，淹到腳踝那麼高。\n引申意思：形容當時賺錢容易。現在說這句多半帶著懷念，因為那個時代已經過去了。" },
  { id: "s206", grade: 6, term: "緊紡無好紗，緊嫁無好大家", kind: "俚語", meaning: "台語俗諺:倉促行事難有好結果。", example: "求快犧牲品質，緊紡無好紗，緊嫁無好大家。", deep: "這句話怎麼來的：臺灣的閩南語俗諺。「大家」是婆婆。紡得急紗就不勻，嫁得急就來不及打聽對方家裡的狀況。\n字面意思：紡得急沒有好紗，嫁得急遇不到好婆婆。\n引申意思：倉促行事難有好結果。它把工藝和婚姻擺在一起，說的是同一件事——時間不夠就沒法挑。" },
  { id: "s207", grade: 6, term: "無魚，蝦嘛好", kind: "俚語", meaning: "台語俗諺:退而求其次，有總比沒有好。", example: "搶不到演唱會門票，看轉播無魚蝦嘛好。", deep: "這句話怎麼來的：臺灣的閩南語俗諺。漁夫出海沒撈到魚，撈到蝦也算有收穫，總比空手回家好。\n字面意思：沒有魚，蝦也可以。\n引申意思：退而求其次。它的語氣是務實的接受，不是委屈——重點在「有總比沒有好」。" },
  { id: "s208", grade: 6, term: "驚驚袂著等", kind: "俚語", meaning: "台語俗諺:畏縮膽怯就得不到獎賞，要勇於嘗試。", example: "想告白就去，驚驚袂著等。", deep: "這句話怎麼來的：臺灣的閩南語俗諺。「著等」是輪得到、分得到。一直怕東怕西的人，好處永遠輪不到他。\n字面意思：一直害怕，就分不到。\n引申意思：畏縮就沒有機會。它是鼓勵人踏出去的話，語氣直接而且有點衝。" },
  { id: "s209", grade: 7, term: "醜醜馬嘛有一步踢", kind: "俚語", meaning: "台語俗諺:再平凡的人也有一技之長。", example: "別小看他，醜醜馬嘛有一步踢。", deep: "這句話怎麼來的：臺灣的閩南語俗諺。「醜醜馬」是難看的馬，「一步踢」是一招踢法。再難看的馬也有牠拿手的一招。\n字面意思：難看的馬也有一招好踢法。\n引申意思：再平凡的人也有一技之長。它是替不被看好的人說話的，語氣是肯定。" },
  { id: "s210", grade: 7, term: "紅媠，烏大範", kind: "俚語", meaning: "台語俗諺:紅色亮麗、黑色大方，各有各的美。", example: "選制服顏色時奶奶說紅媠烏大範，都好看。", deep: "這句話怎麼來的：臺灣的閩南語俗諺。「媠」是漂亮，「大範」是大方有氣度。講的是紅色亮眼、黑色沉穩，各有各的好。\n字面意思：紅色漂亮，黑色大方。\n引申意思：不同的風格各有各的美。它原本是講衣服顏色，後來用來說人各有各的長處。" },
  { id: "s211", grade: 7, term: "一個蘿蔔一個坑", kind: "俚語", meaning: "每個位置都剛好有一個人，沒有多餘的人手可以調動。", example: "我們組一個蘿蔔一個坑，請一天假就沒人補。", deep: "這句話怎麼來的：種蘿蔔要先挖坑，一個坑埋一顆種子，多一顆沒地方放，少一顆坑就空著。\n字面意思：一個蘿蔔配一個坑。\n引申意思：人力剛好用滿，沒有彈性。也可以用在「每個人各有位置」的正面意思，要看上下文。" },
  { id: "s212", grade: 8, term: "掠龜走鱉", kind: "俚語", meaning: "台語俗諺:顧了這頭丟了那頭，兩頭落空。", example: "同時追兩個案子結果掠龜走鱉，都沒成。", deep: "這句話怎麼來的：臺灣的閩南語俗諺。「掠」是抓。抓烏龜的時候鱉跑了，回頭去追鱉烏龜又爬走，兩隻都沒抓到。\n字面意思：抓烏龜，鱉跑掉了。\n引申意思：顧此失彼，兩頭落空。它形容的是同時想抓兩件事的下場，不是運氣不好。" },
  { id: "s213", grade: 8, term: "乞食趕廟公", kind: "俚語", meaning: "台語俗諺:反客為主，受人恩惠反而喧賓奪主。", example: "借住還嫌東嫌西，乞食趕廟公。", deep: "這句話怎麼來的：臺灣的閩南語俗諺。乞丐本來是來廟裡討飯的，住久了反過來把廟公趕走。\n字面意思：乞丐把廟公趕出去。\n引申意思：反客為主、恩將仇報。它比「喧賓奪主」更重，因為多了「受過恩惠」這一層。" },
  { id: "s214", grade: 9, term: "無事不登三寶殿", kind: "俚語", meaning: "沒有事情不會特地上門，一來就是有求於人。", example: "他難得打電話來，無事不登三寶殿，八成是要借錢。", deep: "這句話怎麼來的：「三寶殿」是佛寺裡供佛、法、僧三寶的正殿，平常不隨便進去，要進去多半是有事相求。\n字面意思：沒有事情不會走進三寶殿。\n引申意思：突然上門一定有目的。說的人多半半開玩笑，帶著「你想幹嘛」的味道。" },
  { id: "s215", grade: 9, term: "戲好看，鑼鼓聲了就散", kind: "俚語", meaning: "台語俗諺:熱鬧終有曲終人散時。", example: "慶功宴再熱鬧，戲好看，鑼鼓聲了就散。", deep: "這句話怎麼來的：臺灣的閩南語俗諺。野台戲再精彩，鑼鼓一停觀眾就走光，廟埕轉眼變得空蕩蕩。\n字面意思：戲再好看，鑼鼓聲停了人就散了。\n引申意思：熱鬧總有結束的一刻。它和「天下無不散的筵席」意思相近，這句多了一份戲棚下的蒼涼。" },
  // 歇後語(25)
  { id: "s216", grade: 2, term: "小和尚念經──有口無心", kind: "歇後語", meaning: "嘴上說著，心裡並不在意。", example: "他道歉像小和尚念經──有口無心。", deep: "這句話怎麼來的：小和尚跟著念經，經文一句一句背得出來，心思卻不在上面。\n字面意思：小和尚念經，有嘴巴沒有心。\n引申意思：嘴上說著，心裡並不在意。它常用來說敷衍的答應，重點在「有做這個動作但沒有那個心」。" },
  { id: "s217", grade: 2, term: "貓咬尿泡──空歡喜", kind: "歇後語", meaning: "白高興一場。", example: "中獎簡訊是詐騙，貓咬尿泡──空歡喜。", deep: "這句話怎麼來的：「尿泡」是豬的膀胱，吹起來像個大球。貓以為咬到了什麼好東西，一咬破裡面什麼都沒有。\n字面意思：貓咬破尿泡，什麼也沒有。\n引申意思：白高興一場。它強調的是「先歡喜再落空」的落差，不只是沒得到。" },
  { id: "s218", grade: 3, term: "啞巴見媽媽──沒說的", kind: "歇後語", meaning: "好得沒話說。", example: "這家滷肉飯的味道，啞巴見媽媽──沒說的。", deep: "這句話怎麼來的：啞巴見到媽媽，心裡有千言萬語卻說不出來——「沒說的」在這裡雙關，變成「好得沒話說」。\n字面意思：啞巴看見媽媽，沒有話說。\n引申意思：好得沒話可挑剔。它是正面的稱讚，容易被誤會成負面，用的時候要看上下文。" },
  { id: "s219", grade: 3, term: "豬鼻子插蔥──裝象", kind: "歇後語", meaning: "諧音雙關:假裝了不起。", example: "租名車擺闊，豬鼻子插蔥──裝象。", deep: "這句話怎麼來的：靠的是諧音。豬鼻子插上兩根蔥，遠看像大象的鼻子和牙，「裝象」聽起來就是「裝相」——裝模作樣。\n字面意思：豬的鼻子插了蔥，裝成大象。\n引申意思：假裝了不起。它的畫面很滑稽，所以嘲諷的力道也重。" },
  { id: "s220", grade: 3, term: "老鼠過街──人人喊打", kind: "歇後語", meaning: "作惡者人人痛恨。", example: "詐騙集團如老鼠過街──人人喊打。", deep: "典故由來：出自明代的俗語「老鼠過街，人人喊打」，形容偷吃糧食的老鼠人人痛恨。\n字面意思：老鼠走過街，每個人都喊打。\n引申意思：做壞事的人人人都討厭。它形容的是眾人一致的反感，重點在「不必動員大家就一起反對」。" },
  { id: "s221", grade: 4, term: "谷底彈簧──觸底反彈", kind: "歇後語", meaning: "跌到最低點後開始好轉。", example: "球隊戰績谷底彈簧──觸底反彈，五連勝。", deep: "這句話怎麼來的：彈簧被壓到最底，再壓不下去就會往上彈回來。\n字面意思：彈簧壓到谷底，就往上彈。\n引申意思：情況壞到極點就會開始好轉。它常出現在股市和景氣的討論裡，但要注意——彈簧會彈，不代表所有事都會。" },
  { id: "s222", grade: 4, term: "鴨子聽雷──有聽沒有懂", kind: "歇後語", meaning: "完全聽不懂。", example: "第一次聽微積分，我鴨子聽雷──有聽沒有懂。", deep: "這句話怎麼來的：臺灣常說的歇後語。打雷聲音很大，鴨子聽得見卻不懂那是什麼。\n字面意思：鴨子聽打雷，有聽到但不懂。\n引申意思：完全聽不懂。它形容的是「聲音進得去、意思進不來」，比單純說「不懂」更生動。" },
  { id: "s223", grade: 4, term: "斷了線的風箏──身不由己", kind: "歇後語", meaning: "失去依靠，無法自主。", example: "被浪潮推著走，像斷了線的風箏──身不由己。", deep: "這句話怎麼來的：風箏靠著那條線才飛得住，線一斷就只能隨風亂飄，落在哪裡自己作不了主。\n字面意思：斷了線的風箏，身子由不得自己。\n引申意思：失去依靠、無法自主。它同時暗示了那條線的重要——沒有牽制不是自由，是失控。" },
  { id: "s224", grade: 4, term: "電風扇吹雞毛──亂了套", kind: "歇後語", meaning: "秩序大亂。", example: "臨時換場地，流程電風扇吹雞毛──亂了套。", deep: "這句話怎麼來的：一把雞毛放在電風扇前面吹，整屋子都是毛，怎麼收都收不起來。\n字面意思：電風扇吹雞毛，全亂了。\n引申意思：秩序大亂、收拾不了。它強調的是「亂得很難復原」，不只是暫時的混亂。" },
  { id: "s225", grade: 5, term: "劉備借荊州──有借無還", kind: "歇後語", meaning: "借了就不歸還。", example: "他借書向來劉備借荊州──有借無還。", deep: "典故由來：出自《三國演義》。劉備向東吳「借」荊州當落腳處，赤壁之後一直不還，孫權派人討了好幾次都要不回來。\n字面意思：劉備借了荊州，借了不還。\n引申意思：借了就不歸還。它多半用在借東西不還的人身上，語氣是無奈的調侃。" },
  { id: "s226", grade: 5, term: "徐庶進曹營──一言不發", kind: "歇後語", meaning: "始終沉默不表態。", example: "整場會議他徐庶進曹營──一言不發。", deep: "典故由來：出自《三國演義》。徐庶的母親被曹操騙去，徐庶不得已進了曹營，但立誓終身不為曹操獻一計。\n字面意思：徐庶進了曹營，一句話也不說。\n引申意思：始終沉默不表態。它背後是被迫的處境，所以帶著同情而不是責備。" },
  { id: "s227", grade: 5, term: "張飛穿針──大眼瞪小眼", kind: "歇後語", meaning: "彼此對望，無計可施。", example: "停電後全家張飛穿針──大眼瞪小眼。", deep: "這句話怎麼來的：張飛是猛將，眼睛又大，要他拿針線做細活，針眼那麼小，只能瞪著針發呆。\n字面意思：張飛穿針，大眼睛瞪著小針眼。\n引申意思：兩邊互相看著卻毫無辦法。它妙在「大眼」「小眼」的對比，本來是講一個人，後來多用在兩個人身上。" },
  { id: "s228", grade: 5, term: "諸葛亮借東風──神機妙算", kind: "歇後語", meaning: "謀劃精準高明。", example: "他提前備貨躲過缺料潮，諸葛亮借東風──神機妙算。", deep: "典故由來：出自《三國演義》赤壁之戰。周瑜的火攻缺東風，諸葛亮築壇「借」來東風——其實他是靠對天候的判斷推算出來的。\n字面意思：諸葛亮借東風，算得神準。\n引申意思：謀劃精準高明。故事的重點在於那不是法術，是他讀懂了節氣。" },
  { id: "s229", grade: 6, term: "關公面前耍大刀──不自量力", kind: "歇後語", meaning: "在行家面前賣弄本領。", example: "跟國手比球速？關公面前耍大刀──不自量力。", deep: "這句話怎麼來的：關公是使大刀的高手，在他面前耍大刀，等於把自己的斤兩攤給行家看。\n字面意思：在關公面前耍大刀。\n引申意思：在行家面前賣弄。它和「班門弄斧」是同一個意思，一個用刀，一個用木工。" },
  { id: "s230", grade: 6, term: "包公斷案──鐵面無私", kind: "歇後語", meaning: "執法公正，不講情面。", example: "風紀股長包公斷案──鐵面無私。", deep: "典故由來：包拯是北宋的名臣，傳說他審案不看情面，連皇親國戚都照辦，戲曲裡把他的臉畫成黑色，所以叫「鐵面」。\n字面意思：包公審案，鐵一樣的臉不講私情。\n引申意思：執法公正不徇私。「鐵面」原本是說他臉黑，後來變成「不講情面」的代名詞。" },
  { id: "s231", grade: 6, term: "半路殺出個程咬金──出人意料", kind: "歇後語", meaning: "突然出現意想不到的人或事。", example: "眼看要成交，半路殺出個程咬金──出人意料。", deep: "典故由來：出自《隋唐演義》。程咬金常在半路上突然殺出來打劫，讓人措手不及。\n字面意思：半路上突然殺出一個程咬金。\n引申意思：突然出現意想不到的人或事。它形容的是「打亂原本安排」的那種意外。" },
  { id: "s232", grade: 6, term: "孫悟空七十二變──神通廣大", kind: "歇後語", meaning: "本領高強，變化多端。", example: "這位特效師孫悟空七十二變──神通廣大。", deep: "典故由來：出自《西遊記》。孫悟空跟菩提祖師學了七十二般變化，能變成任何東西。\n字面意思：孫悟空會七十二種變化，本領高強。\n引申意思：本事大、辦法多。要注意《西遊記》裡他變得再多，還是逃不出如來的手掌心。" },
  { id: "s233", grade: 7, term: "豬八戒吃人參果──全不知滋味", kind: "歇後語", meaning: "囫圇享用，不懂品味。", example: "名茶牛飲而盡，豬八戒吃人參果──全不知滋味。", deep: "典故由來：出自《西遊記》。人參果三千年才結一次，豬八戒一口整顆吞下去，連味道都沒嘗到就沒了。\n字面意思：豬八戒吃人參果，完全不知道是什麼味道。\n引申意思：囫圇吞下，沒有真的領會。它常用在讀書和看東西上——看完了，但什麼也沒留下。" },
  { id: "s234", grade: 7, term: "王小二過年──一年不如一年", kind: "歇後語", meaning: "情況一年比一年差。", example: "老街生意王小二過年──一年不如一年。", deep: "這句話怎麼來的：王小二是舊時說書裡的窮人代表，家境一年比一年差，過年時特別看得出來。\n字面意思：王小二過年，一年比一年差。\n引申意思：情況逐年惡化。它用「過年」當比較的基準點，因為過年是一年裡最能看出家底的時候。" },
  { id: "s235", grade: 7, term: "麻雀雖小──五臟俱全", kind: "歇後語", meaning: "規模雖小，該有的都有。", example: "這間套房麻雀雖小──五臟俱全。", deep: "這句話怎麼來的：麻雀是很小的鳥，但心肝脾肺腎一樣都不缺。\n字面意思：麻雀雖然小，五臟都齊全。\n引申意思：規模雖小，該有的都有。它是正面的形容，常用在小公司、小店面上。" },
  { id: "s236", grade: 8, term: "螃蟹過馬路──橫行霸道", kind: "歇後語", meaning: "仗勢橫行，不講道理。", example: "惡少在夜市螃蟹過馬路──橫行霸道。", deep: "這句話怎麼來的：螃蟹天生橫著走，走到馬路上就像不管交通規則一樣橫衝直撞。\n字面意思：螃蟹過馬路，橫著走。\n引申意思：仗勢橫行、不講道理。「橫行」既是螃蟹真的橫著走，也是霸道的意思，是雙關。" },
  { id: "s237", grade: 8, term: "禿子頭上的蝨子──明擺著", kind: "歇後語", meaning: "事情明顯，一目了然。", example: "誰在搗鬼？禿子頭上的蝨子──明擺著。", deep: "這句話怎麼來的：頭上沒有頭髮，蝨子無處可藏，一眼就看得見。\n字面意思：禿頭上的蝨子，明明白白擺在那裡。\n引申意思：事情明顯得不用再說。它的語氣帶點粗俗的痛快，多用在戳破裝傻的人。" },
  { id: "s238", grade: 8, term: "太歲頭上動土──膽子不小", kind: "歇後語", meaning: "敢冒犯有權勢的人。", example: "敢檢舉黑心大戶，真是太歲頭上動土──膽子不小。", deep: "這句話怎麼來的：太歲是民間信仰中掌管一年運勢的神，傳說太歲所在的方位不能動土，動了會招災。\n字面意思：在太歲的頭上挖土。\n引申意思：敢冒犯惹不起的人。它多半是別人替你捏一把冷汗時說的話。" },
  { id: "s239", grade: 9, term: "周瑜謀荊州──賠了夫人又折兵", kind: "歇後語", meaning: "想占便宜反而雙重損失。", example: "挖角不成還洩了底牌，賠了夫人又折兵。", deep: "典故由來：出自《三國演義》。周瑜想用「把孫權的妹妹嫁給劉備」的計策騙回荊州，結果劉備真的娶了人又平安回去，周瑜還被伏兵打敗。\n字面意思：周瑜謀取荊州，賠掉夫人又損兵。\n引申意思：想占便宜反而雙重損失。它的重點在「兩頭都輸」，比單純的失敗更慘。" },
  { id: "s240", grade: 9, term: "姜子牙釣魚──離水三寸", kind: "歇後語", meaning: "不合常規，別有用意。", example: "他開的條件姜子牙釣魚──離水三寸，等識貨的人。", deep: "典故由來：姜太公在渭水釣魚，用直鉤、不掛餌，鉤子還離水面三寸，等的其實是懂他的人。\n字面意思：姜子牙釣魚，鉤子離水三寸。\n引申意思：做法不合常規，其實另有用意。它提醒的是——看起來荒謬的做法，可能目標根本不是你以為的那個。" },
  // ---- s241-s320 ----
  // 諺語(30)
  { id: "s241", grade: 1, term: "在家靠父母，出外靠朋友", kind: "諺語", meaning: "在外闖蕩需要朋友互相扶持。", example: "第一次北上工作，深深體會在家靠父母，出外靠朋友。", deep: "這句話怎麼來的：民間常語。在家有父母照應，出了門就得靠朋友互相幫忙。\n字面意思：在家靠父母，出門靠朋友。\n引申意思：離家在外要有人互相扶持。它也提醒了朋友的分量——出門在外，朋友頂的是父母的位置。" },
  { id: "s242", grade: 1, term: "笑一笑，十年少", kind: "諺語", meaning: "保持愉快心情使人年輕健康。", example: "爺爺天天說笑話，笑一笑，十年少。", deep: "這句話怎麼來的：民間的養生順口溜，完整說法是「笑一笑，十年少；愁一愁，白了頭」，兩句對著講。\n字面意思：笑一笑就年輕十歲。\n引申意思：心情愉快對身體有益。它是誇張的說法，重點在對比——笑和愁對人的影響差很多。" },
  { id: "s243", grade: 2, term: "日行一善", kind: "諺語", meaning: "每天做一件好事。", example: "班上推行日行一善，大家搶著服務。", deep: "典故由來：源自佛家和民間善書的勸善觀念，也和《了凡四訓》記善事的做法有關。\n字面意思：每一天做一件好事。\n引申意思：行善不必等大事，靠每天一點累積。它的關鍵是「日」——重點在頻率而不在大小。" },
  { id: "s244", grade: 2, term: "誠實為上策", kind: "諺語", meaning: "誠實是最好的做法。", example: "打破杯子就承認，誠實為上策。", deep: "典故由來：譯自英文諺語 Honesty is the best policy，一般追到十六世紀的英國。\n字面意思：誠實是最好的策略。\n引申意思：長遠來看誠實最划算。它特別用「策略」而不是「美德」——連從利害算，誠實也還是最好的選擇。" },
  { id: "s245", grade: 2, term: "滿瓶水不響，半瓶水響叮噹", kind: "諺語", meaning: "有真才實學的人謙虛，一知半解的人愛炫耀。", example: "他懂最多卻最安靜，滿瓶水不響，半瓶水響叮噹。", deep: "這句話怎麼來的：裝滿水的瓶子搖起來沒有聲音，只裝一半的搖起來嘩啦作響。\n字面意思：滿瓶的水不出聲，半瓶的水叮噹響。\n引申意思：懂得多的人反而安靜，懂得少的人愛炫耀。它常被縮成「半瓶水」三個字來說人。" },
  { id: "s246", grade: 3, term: "人要衣裝，佛要金裝", kind: "諺語", meaning: "適當的打扮能提升形象。", example: "面試前買套正式服裝，人要衣裝，佛要金裝。", deep: "這句話怎麼來的：民間常語。神像要貼上金箔才顯得莊嚴，人也要有合宜的打扮才顯得體面。\n字面意思：人要靠衣服打扮，佛要靠金箔裝飾。\n引申意思：適當的外在能加分。它承認外表有用，但說的是「裝」——加上去的，不是本體。" },
  { id: "s247", grade: 3, term: "健康是最大的財富", kind: "諺語", meaning: "健康比金錢更寶貴。", example: "爸爸開始運動後常說健康是最大的財富。", deep: "這句話怎麼來的：西方諺語 Health is wealth 的中譯，也和中國「留得青山在」的想法相通。\n字面意思：健康就是最大的財富。\n引申意思：沒有健康，其他的東西都用不上。它把健康放進「財富」的框架，是為了讓人用算的方式看懂它的分量。" },
  { id: "s248", grade: 3, term: "早睡早起身體好", kind: "諺語", meaning: "規律作息有益健康。", example: "想長高就要早睡早起身體好。", deep: "這句話怎麼來的：民間的作息口訣，源頭可追到《黃帝內經》講的「日出而作，日入而息」。\n字面意思：早點睡、早點起，身體會好。\n引申意思：規律的作息比什麼補品都有用。重點其實在「規律」——固定時間睡覺比睡得早更關鍵。" },
  { id: "s249", grade: 3, term: "飯後百步走，活到九十九", kind: "諺語", meaning: "飯後散步有益長壽健康。", example: "爺爺奉行飯後百步走，活到九十九。", deep: "這句話怎麼來的：民間的養生順口溜，「九十九」是為了押韻，指長壽。\n字面意思：飯後走一百步，可以活到九十九歲。\n引申意思：飯後散步有益健康。要注意「百步走」是慢慢散步，不是飯後馬上劇烈運動。" },
  { id: "s250", grade: 4, term: "一言既出，駟馬難追", kind: "諺語", meaning: "話說出口就要守信，無法收回。", example: "答應的事要做到，一言既出，駟馬難追。", deep: "典故由來：出自《論語．顏淵》「駟不及舌」與《鄧析子》的「一言而非，駟馬不能追」。「駟馬」是四匹馬拉的車，古代最快的交通工具。\n字面意思：話一說出口，四匹馬拉的車也追不回來。\n引申意思：說出的話收不回，要守信。它用最快的車追不上，來形容話傳得多快。" },
  { id: "s251", grade: 4, term: "君子一言，快馬一鞭", kind: "諺語", meaning: "說話算話，乾脆守信。", example: "他答應贊助就立刻匯款，君子一言，快馬一鞭。", deep: "這句話怎麼來的：民間常語。君子說一句就算數，就像快馬只要抽一鞭就往前衝，不必囉嗦。\n字面意思：君子說一句話，快馬只要一鞭。\n引申意思：說話算話、乾脆爽快。它強調的是「不必再三催促」，重點在乾脆而不只是守信。" },
  { id: "s252", grade: 4, term: "人非聖賢，孰能無過", kind: "諺語", meaning: "人都會犯錯，貴在能改。", example: "別太苛責他，人非聖賢，孰能無過。", deep: "典故由來：出自《左傳．宣公二年》：「人誰無過？過而能改，善莫大焉。」\n字面意思：人不是聖賢，誰能不犯錯。\n引申意思：犯錯是難免的。要注意這句話常被拿來當藉口，但原文的重點在下一句——「過而能改」才是真正要說的。" },
  { id: "s253", grade: 4, term: "知錯能改，善莫大焉", kind: "諺語", meaning: "知道錯誤而能改正，是最大的善。", example: "他公開道歉並補救，知錯能改，善莫大焉。", deep: "典故由來：和「人非聖賢，孰能無過」出自《左傳》同一句：「過而能改，善莫大焉。」\n字面意思：知道錯了能改，沒有比這更大的善了。\n引申意思：改過本身就是最大的善行。它把「改」的地位抬得很高，因為承認錯誤比不犯錯更難。" },
  { id: "s254", grade: 4, term: "得饒人處且饒人", kind: "諺語", meaning: "能寬容的時候就寬容別人。", example: "他已認錯，得饒人處且饒人吧。", deep: "典故由來：出自宋代的《曾公遺錄》與元曲，常和「得放手時須放手」連用。\n字面意思：可以饒人的時候就饒了人吧。\n引申意思：有餘地時就寬容。它的前提是「你占上風」——處在弱勢時談的不是饒人，是自保。" },
  { id: "s255", grade: 5, term: "退一步海闊天空", kind: "諺語", meaning: "讓步能使局面豁然開朗。", example: "爭到底兩敗俱傷，退一步海闊天空。", deep: "這句話怎麼來的：民間常語，常和「忍一時風平浪靜」成對，兩句都是勸人不要硬碰硬。\n字面意思：退一步，眼前就變成大海和天空那麼寬。\n引申意思：讓步反而讓局面變開闊。它的畫面是空間——往後退才看得到全景。" },
  { id: "s256", grade: 5, term: "忍一時風平浪靜", kind: "諺語", meaning: "暫時忍耐能平息衝突。", example: "他深呼吸不回嘴，忍一時風平浪靜。", deep: "這句話怎麼來的：民間常語，和「退一步海闊天空」成對。海上的風浪來得快去得也快，忍過那一陣就平了。\n字面意思：忍過這一時，風就停了浪就平了。\n引申意思：暫時忍耐能避開衝突。要注意它講的是「一時」——長期的忍耐是另一回事。" },
  { id: "s257", grade: 5, term: "冤家宜解不宜結", kind: "諺語", meaning: "仇怨應該化解，不要結下。", example: "同行何必互告？冤家宜解不宜結。", deep: "這句話怎麼來的：民間常語。「解」是解開，「結」是打結，用繩子的比喻講恩怨。\n字面意思：仇怨應該解開，不應該打結。\n引申意思：能化解就不要結仇。它用「結」這個字很妙——結愈打愈緊，時間拖久了更難解。" },
  { id: "s258", grade: 5, term: "各人自掃門前雪", kind: "諺語", meaning: "只管自己的事，不管別人（多含批評自私之意）。", example: "社區事務沒人理，大家各人自掃門前雪。", deep: "這句話怎麼來的：完整說法是「各人自掃門前雪，莫管他人瓦上霜」，宋代已見類似說法。\n字面意思：每個人掃自己門前的雪就好。\n引申意思：只管自己不管別人。它可以是批評自私，也可以是勸人不要多管閒事，看說話的人站在哪一邊。" },
  { id: "s259", grade: 5, term: "獨木不成林", kind: "諺語", meaning: "單獨一人成不了大事。", example: "再強的球星也要隊友，獨木不成林。", deep: "典故由來：源自漢代崔駰〈達旨〉「高樹靡陰，獨木不林」，講一棵樹成不了森林。\n字面意思：一棵樹形成不了樹林。\n引申意思：一個人的力量有限。它和「眾人拾柴火焰高」是一體兩面，一句講缺點，一句講好處。" },
  { id: "s260", grade: 5, term: "人多好辦事", kind: "諺語", meaning: "人手多，事情容易辦成。", example: "全班分工佈置會場，人多好辦事。", deep: "這句話怎麼來的：民間常語，和「人多手雜」「三個和尚沒水喝」正好相反，說的是人多的好處。\n字面意思：人多，事情就好辦。\n引申意思：人手足夠事情容易完成。要注意它成立的條件是分工清楚——分工不清時，人多反而更慢。" },
  { id: "s261", grade: 6, term: "先小人後君子", kind: "諺語", meaning: "先把條件講清楚，之後好維持交情。", example: "合夥前先簽約，先小人後君子。", deep: "這句話怎麼來的：民間做生意的常語。「小人」在這裡不是罵人，是指把利害算得很細的樣子。\n字面意思：先當小人把話講明，之後才好當君子。\n引申意思：先把條件講清楚，之後交情才維持得住。它的智慧在於——不好意思講清楚，後面才真的會傷感情。" },
  { id: "s262", grade: 6, term: "親兄弟明算帳", kind: "諺語", meaning: "再親近的人金錢也要算清楚。", example: "合買房子也要親兄弟明算帳。", deep: "這句話怎麼來的：民間常語，和「先小人後君子」是同一個道理，特別用在最親近的關係上。\n字面意思：就算是親兄弟，帳也要算清楚。\n引申意思：關係越近，金錢越要分明。它反的是「都是自己人不用算」——正是那句話最容易毀掉關係。" },
  { id: "s263", grade: 6, term: "便宜沒好貨", kind: "諺語", meaning: "價格過低的東西品質通常不佳。", example: "夜市三百元的「名牌」錶，便宜沒好貨。", deep: "這句話怎麼來的：民間買賣的常語，和「一分錢一分貨」成對，一句從壞的說，一句從好的說。\n字面意思：便宜的東西沒有好貨。\n引申意思：價格太低品質通常也差。它不是絕對的規則——買到便宜好貨也有，只是機率低。" },
  { id: "s264", grade: 6, term: "一分錢一分貨", kind: "諺語", meaning: "價格與品質相當。", example: "這雙鞋貴但耐穿，一分錢一分貨。", deep: "這句話怎麼來的：民間買賣的常語，和「便宜沒好貨」是同一件事的正面說法。\n字面意思：花多少錢，得到多少品質。\n引申意思：價格和品質大致相當。它也用來說服自己多花錢是值得的，所以買東西時要留意是不是被這句話說動的。" },
  { id: "s265", grade: 7, term: "羊毛出在羊身上", kind: "諺語", meaning: "表面的好處其實還是由自己付出。", example: "滿額贈其實羊毛出在羊身上。", deep: "這句話怎麼來的：民間常語。剪羊毛做成衣服再賣給養羊的人，那些毛本來就是羊自己長的。\n字面意思：羊毛是從羊身上剪下來的。\n引申意思：給你的好處其實是你自己出的錢。它最常用在促銷和折扣上——免費的東西早就算進價格裡了。" },
  { id: "s266", grade: 7, term: "天下沒有白吃的午餐", kind: "諺語", meaning: "任何好處都要付出代價。", example: "高報酬必有高風險，天下沒有白吃的午餐。", deep: "典故由來：譯自英文諺語 There ain't no such thing as a free lunch，源自美國酒吧「買酒免費附午餐」的招數——午餐的錢早就加在酒價裡了。\n字面意思：天底下沒有不用錢的午餐。\n引申意思：任何好處都有代價。這句話後來被經濟學家傅利曼引用而廣為人知。" },
  { id: "s267", grade: 7, term: "偷雞不著蝕把米", kind: "諺語", meaning: "想占便宜反而受損失。", example: "逃票被罰五十倍，偷雞不著蝕把米。", deep: "這句話怎麼來的：民間常語。想偷雞的人帶一把米去引誘，雞沒偷到，米也撒光了。\n字面意思：雞沒偷到，反而賠了一把米。\n引申意思：想占便宜反而蝕本。它的重點是「連本錢都搭進去」，比單純的沒成功更慘。" },
  { id: "s268", grade: 8, term: "螳螂捕蟬，黃雀在後", kind: "諺語", meaning: "只顧眼前利益，不知禍患將至。", example: "他忙著併購對手，卻不知螳螂捕蟬，黃雀在後。", deep: "典故由來：出自《說苑．正諫》。吳王要伐楚，少年用花園裡的景象勸他：蟬只顧鳴叫，螳螂在後面要抓牠，黃雀又在螳螂後面，而少年的彈弓正對著黃雀。\n字面意思：螳螂要抓蟬，黃雀在螳螂後面。\n引申意思：只看眼前利益，不知道自己也是別人的獵物。原典還有第四層——拿彈弓的人腳下正踩著陷阱。" },
  { id: "s269", grade: 8, term: "鷸蚌相爭，漁翁得利", kind: "諺語", meaning: "雙方相爭，第三者得利。", example: "兩強互槓，第三品牌鷸蚌相爭，漁翁得利。", deep: "典故由來：出自《戰國策．燕策》。蘇代勸趙王不要打燕國，講了鷸鳥啄蚌、蚌夾住鷸嘴，兩邊誰也不放，結果漁夫把兩隻一起抓走的故事。\n字面意思：鷸和蚌互相夾住，漁夫得到好處。\n引申意思：雙方相持不下，第三者坐收利益。它原本是一則外交上的勸告，不只是講吵架。" },
  { id: "s270", grade: 9, term: "成也蕭何，敗也蕭何", kind: "諺語", meaning: "成敗都由同一人或同一因素造成。", example: "靠流量爆紅也因流量翻車，成也蕭何，敗也蕭何。", deep: "典故由來：出自《史記》。韓信是蕭何推薦給劉邦才能出頭的，後來也是蕭何設計把韓信誘進宮中被殺。\n字面意思：成功是因為蕭何，失敗也是因為蕭何。\n引申意思：成敗出於同一個人或同一個原因。它的深意在於——讓你成功的那個特質，往往也是害你失敗的那一個。" },
  // 台灣俗諺(俚語,25)
  { id: "s271", grade: 1, term: "囡仔人有耳無喙", kind: "俚語", meaning: "台語俗諺:小孩子只聽不插嘴（長輩告誡語）。", example: "大人談正事，阿嬤說囡仔人有耳無喙。", deep: "這句話怎麼來的：臺灣的閩南語俗諺，是大人講正事時制止小孩插話的固定用語。\n字面意思：小孩子有耳朵，沒有嘴巴。\n引申意思：該聽的時候聽，不該說的時候不要說。現在也被拿來反省——只叫孩子閉嘴，孩子就不會表達意見了。" },
  { id: "s272", grade: 2, term: "囡仔人跳過溝，三碗飯落腹肚", kind: "俚語", meaning: "台語俗諺:小孩活動量大、食量驚人。", example: "弟弟跑一下午吃三碗飯，囡仔人跳過溝，三碗飯落腹肚。", deep: "這句話怎麼來的：臺灣的閩南語俗諺。小孩子跑跳一下就餓，一頓能吃掉三碗飯。\n字面意思：小孩跳過一條溝，三碗飯就下肚了。\n引申意思：形容小孩活動量大、消耗快。它是大人看著孩子吃飯時半驚訝半疼惜的話。" },
  { id: "s273", grade: 2, term: "細粒子，好豆油", kind: "俚語", meaning: "台語俗諺:個子小卻精明能幹（如小瓶醬油更醇）。", example: "她個子嬌小卻扛下全場，細粒子，好豆油。", deep: "這句話怎麼來的：臺灣的閩南語俗諺。從前好的醬油是用小瓶裝的，愈濃愈醇的裝得愈少。\n字面意思：小瓶子裝的，是好醬油。\n引申意思：個子小或年紀輕，能力卻很強。它是稱讚的話，專門用來反駁「看起來不起眼」的偏見。" },
  { id: "s274", grade: 3, term: "做雞著筅，做人著反", kind: "俚語", meaning: "台語俗諺:雞要扒土找食，人要勤奮翻身。", example: "阿公說做雞著筅，做人著反，不能懶散。", deep: "這句話怎麼來的：臺灣的閩南語俗諺。「筅」是雞用腳扒土，「反」是翻動、翻身。雞要扒土才找得到蟲。\n字面意思：當雞就要扒土，做人就要翻動。\n引申意思：要主動去找，不能等東西送上門。它把勤奮講成本能，語氣是理所當然而不是勸告。" },
  { id: "s275", grade: 3, term: "一皮天下無難事", kind: "俚語", meaning: "俗諺:臉皮厚就什麼都不怕（含戲謔）。", example: "他到處推銷不怕拒絕，一皮天下無難事。", deep: "這句話怎麼來的：民間戲謔語，把「世上無難事」改成「一皮天下無難事」，「皮」指臉皮厚。\n字面意思：臉皮夠厚，天下就沒有難事。\n引申意思：不怕丟臉就什麼都敢做。它是半開玩笑的話，用來自嘲或調侃別人，不是正經的處世建議。" },
  { id: "s276", grade: 3, term: "南風轉北，落雨袂停", kind: "俚語", meaning: "台語氣象俗諺:風向轉變預示天氣變化。", example: "阿公看天說南風轉北，落雨袂停，要帶傘。", deep: "這句話怎麼來的：臺灣的閩南語氣象俗諺。夏天吹南風時如果轉成北風，代表鋒面或颱風接近，雨會下個不停。\n字面意思：南風轉成北風，雨就下不停。\n引申意思：從徵兆判斷接下來的變化。這是農漁民長期觀察天候累積的經驗，屬於臺灣的氣象諺語。" },
  { id: "s277", grade: 4, term: "六月芥菜──假有心", kind: "俚語", meaning: "台語歇後式俗諺:六月的芥菜不結心，譏人假情假意。", example: "他那句慰問是六月芥菜──假有心。", deep: "這句話怎麼來的：臺灣的閩南語俗諺。芥菜要天冷才會結出中間的菜心，六月太熱不會結心——「無心」聽起來像「假有心」。\n字面意思：六月的芥菜不結心。\n引申意思：假裝有心、虛情假意。它靠的是「心」的雙關：菜心和心意。" },
  { id: "s278", grade: 4, term: "拚生拚死，毋值拄好時", kind: "俚語", meaning: "台語俗諺:拚命努力，也要碰上好時機。", example: "創業拚生拚死，毋值拄好時，也要看景氣。", deep: "這句話怎麼來的：臺灣的閩南語俗諺。「拄好時」是剛好碰上好時機。再拚命，也比不上時機對了。\n字面意思：拚生拚死，比不上剛好遇到好時機。\n引申意思：時機的分量有時大過努力。它不是叫人不要努力，而是提醒別把成敗全算在努力上。" },
  { id: "s279", grade: 4, term: "三分天注定，七分靠打拚", kind: "俚語", meaning: "台語俗諺:命運小部分天定，大部分靠努力。", example: "他常唱三分天注定，七分靠打拚勉勵自己。", deep: "這句話怎麼來的：臺灣的閩南語俗諺，因為葉啟田〈愛拚才會贏〉的歌詞而家喻戶曉。\n字面意思：三分是天注定的，七分靠自己打拚。\n引申意思：承認有運氣，但主要靠自己。它厲害的地方在於用比例說話——不否認命運，但把大部分交還給自己。" },
  { id: "s280", grade: 4, term: "少年袂曉想，食老毋成樣", kind: "俚語", meaning: "台語俗諺:年輕不懂打算，年老就狼狽。", example: "月光族要警惕:少年袂曉想，食老毋成樣。", deep: "這句話怎麼來的：臺灣的閩南語俗諺。「袂曉想」是不會打算，「毋成樣」是不成樣子。\n字面意思：年輕時不會打算，老了就不成樣子。\n引申意思：年輕時的規劃決定老年的處境。它比「少壯不努力」多了一層——講的不只是努力，是會不會替自己打算。" },
  { id: "s281", grade: 5, term: "會呼雞袂歕火", kind: "俚語", meaning: "台語俗諺:形容累到只剩喚雞的力氣，連吹火都沒力。", example: "搬完家具，我會呼雞袂歕火，癱在沙發上。", deep: "這句話怎麼來的：臺灣的閩南語俗諺。「呼雞」是用嘴發出咕咕聲喚雞，「歕火」是吹柴火，吹火比喚雞費力得多。\n字面意思：只剩喚雞的力氣，連吹火都吹不動。\n引申意思：累到極點。它用兩個日常動作的費力程度來分級，比直接說「好累」精確得多。" },
  { id: "s282", grade: 5, term: "人情留一線，日後好相看", kind: "俚語", meaning: "台語俗諺:做事留餘地，日後好相處。", example: "談判別趕盡殺絕，人情留一線，日後好相看。", deep: "這句話怎麼來的：臺灣的閩南語俗諺。「相看」是見面。做事別做絕，以後見面才不尷尬。\n字面意思：人情留一條線，以後好見面。\n引申意思：做事要留餘地。它的理由很實際——世界很小，遲早會再遇到。" },
  { id: "s283", grade: 5, term: "好嘴大富貴", kind: "俚語", meaning: "台語俗諺:嘴甜有禮帶來好人緣好運氣。", example: "他見人就問好，好嘴大富貴，客源不斷。", deep: "這句話怎麼來的：臺灣的閩南語俗諺。「好嘴」是嘴甜、會說話。願意開口打招呼、說好話的人，路走得比較順。\n字面意思：嘴巴甜，帶來大富貴。\n引申意思：態度和氣、肯開口，機會就多。它講的是主動打招呼，不是叫人說假話。" },
  { id: "s284", grade: 5, term: "一日剃頭，三日緣投", kind: "俚語", meaning: "台語俗諺:理完髮精神好幾天，打理儀容使人有精神。", example: "面試前去理髮，一日剃頭，三日緣投。", deep: "這句話怎麼來的：臺灣的閩南語俗諺。「緣投」是英俊。剛剪完頭髮那幾天特別精神。\n字面意思：剃一次頭，帥三天。\n引申意思：把儀容整理好會讓人有精神。它也常被拿來調侃剪了頭髮的人，語氣輕鬆。" },
  { id: "s285", grade: 6, term: "千金買厝，萬金買厝邊", kind: "俚語", meaning: "台語俗諺:好鄰居比房子本身更珍貴。", example: "選這社區是因為鄰居好，千金買厝，萬金買厝邊。", deep: "這句話怎麼來的：臺灣的閩南語俗諺。「厝邊」是鄰居。房子花千金就買得到，好鄰居花萬金也不一定遇得到。\n字面意思：千金買房子，萬金買鄰居。\n引申意思：好鄰居比房子本身更難得。它和「遠親不如近鄰」相通，這句多了「買不到」的意思。" },
  { id: "s286", grade: 6, term: "尪某同心，烏土變黃金", kind: "俚語", meaning: "台語俗諺:夫妻同心，泥土也能變黃金。", example: "夫妻擺攤二十年買下店面，尪某同心，烏土變黃金。", deep: "這句話怎麼來的：臺灣的閩南語俗諺。「尪某」是夫妻。兩個人同心協力，貧瘠的黑土也能種出好收成。\n字面意思：夫妻同心，黑土也會變成黃金。\n引申意思：同心協力就能改變處境。它用土的顏色變化來寫努力的成果，畫面很農家。" },
  { id: "s287", grade: 6, term: "序大無好樣，序細討和尚", kind: "俚語", meaning: "台語俗諺:長輩沒做好榜樣，晚輩就有樣學樣變壞。", example: "在孩子面前別滑手機滑整天，序大無好樣，序細討和尚。", deep: "這句話怎麼來的：臺灣的閩南語俗諺。「序大」是長輩，「序細」是晚輩，「討和尚」指做出不成體統的事。\n字面意思：長輩沒有做好榜樣，晚輩就跟著走偏。\n引申意思：身教勝過言教。它把責任先放在長輩身上，語氣是責備大人而不是罵孩子。" },
  { id: "s288", grade: 7, term: "嚴父出孝子，慈母多敗兒", kind: "俚語", meaning: "俗諺:管教嚴格才能成材，過度溺愛反害了孩子。", example: "他感謝父親當年嚴格，嚴父出孝子。", deep: "這句話怎麼來的：民間對家教的說法，「敗兒」是被寵壞的孩子，常和「棒下出孝子」一起被引用。\n字面意思：嚴格的父親教出孝順的兒子，慈愛過頭的母親養出敗家的孩子。\n引申意思：管教要有分寸。要注意這句話帶有舊時代的性別分工，現在讀它要看重點——重點是「界線」而不是「誰扮黑臉」。" },
  { id: "s289", grade: 7, term: "枵鬼假細膩", kind: "俚語", meaning: "台語俗諺:明明很想要卻假裝客氣。", example: "說不餓卻一直看蛋糕，枵鬼假細膩。", deep: "這句話怎麼來的：臺灣的閩南語俗諺。「枵」是飢餓，「細膩」是客氣。肚子明明很餓卻還在推辭。\n字面意思：餓鬼假裝客氣。\n引申意思：心裡很想要卻裝作不在意。它戳破的是虛偽的客套，語氣帶著看穿的調侃。" },
  { id: "s290", grade: 7, term: "緊行無好步", kind: "俚語", meaning: "台語俗諺:走得太急就沒有穩妥的步伐。", example: "決策別倉促，緊行無好步。", deep: "這句話怎麼來的：臺灣的閩南語俗諺。走得太快，腳步就踩不穩，容易絆倒。\n字面意思：走得急，就沒有好步伐。\n引申意思：太急的做法不會穩當。它和「緊事寬辦」「呷緊弄破碗」是同一組道理，這句最貼近走路的實感。" },
  { id: "s291", grade: 8, term: "青暝的毋驚銃", kind: "俚語", meaning: "台語俗諺:盲者不怕槍，無知者無所畏懼。", example: "新手敢梭哈全押，青暝的毋驚銃。", deep: "這句話怎麼來的：臺灣的閩南語俗諺。「青暝」是眼睛看不見，「銃」是槍。看不見槍的人自然不會怕槍。\n字面意思：看不見的人不怕槍。\n引申意思：不知道危險的人才無所畏懼。它說的是「無知的勇」，不是真正的勇敢。" },
  { id: "s292", grade: 8, term: "貪字貧字殼", kind: "俚語", meaning: "台語俗諺:「貪」字是「貧」字的外殼，貪心導致貧窮。", example: "想一夜翻本結果輸光，貪字貧字殼。", deep: "這句話怎麼來的：臺灣的閩南語俗諺，靠的是拆字——「貧」字外面那一層，正好是「貪」字的樣子。\n字面意思：「貪」是「貧」的外殼。\n引申意思：貪心的結果就是貧窮。它用漢字的字形來講道理，是拆字型俗諺的代表。" },
  { id: "s293", grade: 8, term: "時到時擔當，無米才煮番薯湯", kind: "俚語", meaning: "台語俗諺:事到臨頭再想辦法，總有應變之道。", example: "先別焦慮，時到時擔當，無米才煮番薯湯。", deep: "這句話怎麼來的：臺灣的閩南語俗諺。「時到時擔當」是到時候再承擔，沒有米就用番薯煮湯，總有辦法過去。\n字面意思：到時候再說，沒有米就煮番薯湯。\n引申意思：事到臨頭自有應變的辦法。它的語氣是豁達，但也常被拿來當不準備的藉口。" },
  { id: "s294", grade: 9, term: "未食著肉，先食著湯", kind: "俚語", meaning: "台語俗諺:還沒得到主要好處，先嘗到附帶利益。", example: "案子還沒簽，先賺到名聲，未食著肉，先食著湯。", deep: "這句話怎麼來的：臺灣的閩南語俗諺。辦桌時肉還沒上，先喝到湯——湯是附帶的，肉才是主菜。\n字面意思：還沒吃到肉，先喝到湯。\n引申意思：主要的好處還沒拿到，先得到附帶的。它有時是安慰，有時是提醒——別把湯當成肉。" },
  { id: "s295", grade: 9, term: "毋驚虎生三個喙，只驚人懷雙樣心", kind: "俚語", meaning: "台語俗諺:不怕猛虎，只怕人心不一、口是心非。", example: "合作最怕背叛，毋驚虎生三個喙，只驚人懷雙樣心。", deep: "這句話怎麼來的：臺灣的閩南語俗諺。「三個喙」是三張嘴，形容老虎再兇也只是明面上的威脅。\n字面意思：不怕老虎長三張嘴，只怕人懷著兩種心。\n引申意思：明處的危險不可怕，暗處的人心才可怕。它把猛獸和人心對比，結論是人心更難防。" },
  // 歇後語(25)
  { id: "s296", grade: 2, term: "螞蟻搬泰山──下定決心", kind: "歇後語", meaning: "決心極大，不畏艱難。", example: "他要自學考上第一志願，螞蟻搬泰山──下定決心。", deep: "這句話怎麼來的：泰山是最重的象徵，螞蟻是最小的動物，小螞蟻要搬動泰山，靠的只有決心。\n字面意思：螞蟻要搬走泰山。\n引申意思：決心極大，不畏艱難。它是正面的形容，重點在「敢想」而不是「一定成」。" },
  { id: "s297", grade: 2, term: "石沉大海──沒消息", kind: "歇後語", meaning: "毫無回音。", example: "投了十封履歷石沉大海──沒消息。", deep: "這句話怎麼來的：石頭丟進海裡，連個泡都不冒，更別說回音。\n字面意思：石頭沉入大海，沒有消息。\n引申意思：送出去的東西完全沒有回應。它常用在投履歷、送企劃、傳訊息之後等不到回覆。" },
  { id: "s298", grade: 3, term: "貓抓玻璃──白費工", kind: "歇後語", meaning: "徒勞無功。", example: "勸不聽的人，說再多貓抓玻璃──白費工。", deep: "這句話怎麼來的：貓想抓玻璃另一邊的東西，爪子在玻璃上抓半天，除了聲音什麼也抓不到。\n字面意思：貓抓玻璃，白費力氣。\n引申意思：徒勞無功。它比「白費力氣」多了一層——中間有一道看得見卻穿不過的阻礙。" },
  { id: "s299", grade: 3, term: "洩了氣的皮球──軟了", kind: "歇後語", meaning: "失去信心鬥志。", example: "被拒絕兩次他就洩了氣的皮球──軟了。", deep: "這句話怎麼來的：皮球要打飽氣才彈得起來，氣一洩就癱在地上不動。\n字面意思：洩了氣的皮球，軟趴趴的。\n引申意思：失去鬥志、提不起勁。它形容的是那種「本來有勁、後來沒了」的狀態，不是天生沒力氣。" },
  { id: "s300", grade: 3, term: "雨後春筍──一個勁往上冒", kind: "歇後語", meaning: "新事物大量湧現。", example: "手搖店雨後春筍──一個勁往上冒。", deep: "典故由來：出自宋代張耒〈食筍〉的意象，形容春雨過後竹筍一夜之間冒出一大片。\n字面意思：下過雨的春天，竹筍一根根冒出來。\n引申意思：新事物大量出現。它可以是正面的（新店、新想法），也可以是負面的（一窩蜂），要看上下文。" },
  { id: "s301", grade: 4, term: "芝麻掉進針眼裡──巧極了", kind: "歇後語", meaning: "非常湊巧。", example: "在京都遇到鄰居，芝麻掉進針眼裡──巧極了。", deep: "這句話怎麼來的：芝麻小得像粒沙，針眼小得幾乎看不見，芝麻剛好掉進針眼，機率低到不可思議。\n字面意思：芝麻剛好掉進針的孔裡。\n引申意思：非常湊巧。它用兩個「最小」相遇來形容巧合，比「好巧」生動得多。" },
  { id: "s302", grade: 4, term: "冬天的甘蔗──甜到心裡", kind: "歇後語", meaning: "非常甜蜜開心。", example: "收到錄取通知，冬天的甘蔗──甜到心裡。", deep: "這句話怎麼來的：甘蔗要天冷才甜，冬天的甘蔗糖分最高，一口咬下甜到心裡。\n字面意思：冬天的甘蔗，甜到心裡去。\n引申意思：非常甜蜜開心。它是純正面的形容，常用來說感情或好消息。" },
  { id: "s303", grade: 4, term: "山中無老虎──猴子稱大王", kind: "歇後語", meaning: "強者不在，次等的人便逞威風。", example: "隊長受傷缺陣，山中無老虎──猴子稱大王。", deep: "典故由來：出自明代小說《西遊記》的相關俗語，也見於更早的民間說法。\n字面意思：山裡沒有老虎，猴子就當起大王。\n引申意思：強者不在，次一等的就逞威風。它嘲諷的是那隻猴子，同時也點出——牠當得成大王，是因為老虎不在。" },
  { id: "s304", grade: 4, term: "隔岸觀火──袖手旁觀", kind: "歇後語", meaning: "見人危難而不救助。", example: "同學被欺負別隔岸觀火──袖手旁觀。", deep: "典故由來：出自唐代乾康的詩句與《五燈會元》「隔岸觀火」的說法，意思是站在河的另一邊看火燒。\n字面意思：隔著河看對岸失火。\n引申意思：見人有難卻不伸手。它強調的是「明明看得到」——不是不知道，是知道了不動。" },
  { id: "s305", grade: 5, term: "獨眼龍看書──一目了然", kind: "歇後語", meaning: "諧音雙關:一看就明白。", example: "這張圖表獨眼龍看書──一目了然。", deep: "這句話怎麼來的：獨眼龍只有一隻眼睛，看書當然是「一目」，「一目了然」剛好是現成的成語。\n字面意思：只有一隻眼睛的人看書，一隻眼就看完了。\n引申意思：一看就明白。這是諧義雙關型歇後語，妙在「一目」既是實際的一隻眼，也是成語裡的說法。" },
  { id: "s306", grade: 5, term: "騎驢看唱本──走著瞧", kind: "歇後語", meaning: "且看事情如何發展（帶較勁意味）。", example: "比賽還沒完，騎驢看唱本──走著瞧。", deep: "這句話怎麼來的：騎在驢背上看唱本（戲曲的劇本），驢子慢慢走，人慢慢看，走到哪看到哪。\n字面意思：騎著驢看唱本，走著看。\n引申意思：且看事情怎麼發展。它常帶著較勁的口氣，等於「我們走著瞧」。" },
  { id: "s307", grade: 5, term: "打開天窗──說亮話", kind: "歇後語", meaning: "坦率直說，不遮掩。", example: "咱們打開天窗──說亮話，這案子問題在預算。", deep: "這句話怎麼來的：從前的屋子在屋頂開天窗採光，天窗一打開，屋裡整個亮起來。\n字面意思：打開天窗，話就講得亮。\n引申意思：坦率直說不遮掩。它的畫面是「先讓光進來」——把事情攤在明處再談。" },
  { id: "s308", grade: 5, term: "快刀斬亂麻──乾脆俐落", kind: "歇後語", meaning: "果斷處理複雜問題。", example: "新主管快刀斬亂麻──乾脆俐落，砍掉冗餘流程。", deep: "典故由來：出自《北齊書．文宣帝紀》。高洋的父親要幾個兒子理亂麻，別人都在慢慢解，高洋抽刀一斬，說「亂者須斬」。\n字面意思：用快刀砍斷纏成一團的麻。\n引申意思：果斷處理複雜的問題。要注意它的前提是「這團麻不需要保留」——不是所有複雜的事都能斬。" },
  { id: "s309", grade: 6, term: "程咬金的斧頭──就這三下子", kind: "歇後語", meaning: "本領有限，招數不多。", example: "他的招式程咬金的斧頭──就這三下子。", deep: "典故由來：出自《隋唐演義》。程咬金夢中學了六十四招斧法，醒來只記得前三招，靠這三下子照樣闖出名號。\n字面意思：程咬金的斧頭，就那三下。\n引申意思：本領有限、招數不多。它帶著調侃，但故事本身也說明——三招練熟也能用。" },
  { id: "s310", grade: 6, term: "梁山泊的軍師──無(吳)用", kind: "歇後語", meaning: "諧音雙關:沒有用處。", example: "光出主意不動手，梁山泊的軍師──無用。", deep: "這句話怎麼來的：靠的是諧音。《水滸傳》裡梁山泊的軍師叫吳用，「吳用」聽起來就是「無用」。\n字面意思：梁山泊的軍師是吳用。\n引申意思：沒有用處。有趣的是吳用在書中足智多謀，這句歇後語完全靠名字的巧合，和他的本事無關。" },
  { id: "s311", grade: 6, term: "潑出去的水──收不回", kind: "歇後語", meaning: "已成事實，無法挽回。", example: "話說出口就是潑出去的水──收不回。", deep: "典故由來：和「覆水難收」同一個典故，傳說姜太公把一盆水潑在地上，叫要回頭的妻子收起來。\n字面意思：潑出去的水收不回來。\n引申意思：已成的事實無法挽回。它和「覆水難收」是同一句的白話版，畫面更直接。" },
  { id: "s312", grade: 6, term: "趕鴨子上架──強人所難", kind: "歇後語", meaning: "勉強別人做辦不到的事。", example: "叫我即興唱歌是趕鴨子上架──強人所難。", deep: "這句話怎麼來的：鴨子腳短又不會攀爬，硬要牠上架子，牠只會原地打轉。\n字面意思：趕鴨子上架。\n引申意思：勉強別人做辦不到的事。它的重點在「架」——不是鴨子懶，是牠本來就上不去。" },
  { id: "s313", grade: 7, term: "楚河漢界──一清二楚", kind: "歇後語", meaning: "界線分明。", example: "帳目分開記，楚河漢界──一清二楚。", deep: "典故由來：楚河漢界是象棋棋盤中間那條界線，源自楚漢相爭時劉邦和項羽以鴻溝為界的約定。\n字面意思：楚河漢界，分得一清二楚。\n引申意思：界線分明。它常用在講權責、地盤或人際距離上。" },
  { id: "s314", grade: 7, term: "黃牛過河──各顧各", kind: "歇後語", meaning: "只顧自己，互不相助。", example: "小組作業大家黃牛過河──各顧各，慘不忍睹。", deep: "這句話怎麼來的：一群黃牛過河，水一深每頭牛就顧著自己游，誰也顧不上誰。\n字面意思：黃牛過河，各顧各的。\n引申意思：情況緊急時各自逃命，互不相助。它描述的是處境使然，不完全是在罵人自私。" },
  { id: "s315", grade: 7, term: "啞巴打官司──有理說不出", kind: "歇後語", meaning: "有道理卻無法申辯。", example: "沒留存證據，啞巴打官司──有理說不出。", deep: "這句話怎麼來的：打官司靠的是辯詞，啞巴說不出話，再有道理也講不出來。\n字面意思：啞巴打官司，有道理說不出來。\n引申意思：有理卻無法申辯。它和「啞巴吃黃連」是同一個角色的不同處境——那句是苦，這句是冤。" },
  { id: "s316", grade: 8, term: "鐵公雞──一毛不拔", kind: "歇後語", meaning: "極度吝嗇。", example: "找他募款？鐵公雞──一毛不拔。", deep: "這句話怎麼來的：鐵鑄的公雞身上一根毛都拔不下來，用來形容一毛不拔。「一毛不拔」出自《孟子》講楊朱的話。\n字面意思：鐵做的公雞，一根毛也拔不下來。\n引申意思：極度吝嗇。它比單說「小氣」重得多，因為連一根都不肯。" },
  { id: "s317", grade: 8, term: "屬算盤的──撥一撥動一動", kind: "歇後語", meaning: "被動，不推不動。", example: "他做事屬算盤的──撥一撥動一動。", deep: "這句話怎麼來的：算盤珠子不會自己動，手撥一顆才動一顆。\n字面意思：像算盤一樣，撥一下才動一下。\n引申意思：被動、不催不動。它形容的是缺乏主動性，語氣是無奈的抱怨。" },
  { id: "s318", grade: 8, term: "戲台底下掉眼淚──替古人擔憂", kind: "歇後語", meaning: "為不相干的事白操心。", example: "劇情是虛構的，別戲台底下掉眼淚──替古人擔憂。", deep: "這句話怎麼來的：看戲看到哭，哭的是戲裡幾百年前的人，跟自己一點關係也沒有。\n字面意思：在戲台下為戲裡的古人掉眼淚。\n引申意思：為不相干的事白操心。它的妙處在於——那個人是真的難過，只是難過得沒有著力點。" },
  { id: "s319", grade: 9, term: "諸葛亮當軍師──名副其實", kind: "歇後語", meaning: "名聲與才能相符。", example: "請她當顧問是諸葛亮當軍師──名副其實。", deep: "這句話怎麼來的：軍師的職責是出謀劃策，諸葛亮正是史上最有名的謀士，所以他當軍師是名實相符。\n字面意思：諸葛亮當軍師，名聲和才能剛好相配。\n引申意思：名聲與實力相符。它是正面的稱讚，用在「這個頭銜他當得起」的場合。" },
  { id: "s320", grade: 9, term: "曹操吃雞肋──食之無味，棄之可惜", kind: "歇後語", meaning: "沒多大價值，丟掉又捨不得。", example: "這個舊專案曹操吃雞肋──食之無味，棄之可惜。", deep: "典故由來：出自《三國志》。曹操攻漢中時進退兩難，夜裡看到雞肋就說出口令「雞肋」；楊修一聽就知道要退兵，說雞肋「食之無所得，棄之如可惜」。\n字面意思：曹操吃雞肋，吃了沒味道，丟了又可惜。\n引申意思：價值不高卻捨不得放棄。它的重點是「留著也沒用，但就是丟不下」的那種為難。" },
  { id: "s321", grade: 1, term: "馬馬虎虎", kind: "俚語", meaning: "形容做事隨便、不認真仔細，也可指程度普通。", example: "寫功課不能馬馬虎虎，寫完要記得檢查一遍。", deep: "典故由來：傳說宋代有個畫家畫了一隻四不像的動物，兒子問是馬還是虎，他隨口說「馬馬虎虎」，後來兩個兒子都因為分不清馬和虎而出事。\n字面意思：既像馬又像虎，分不清楚。\n引申意思：做事隨便、不認真。它也可以當「還可以、普普通通」用，語氣輕得多。" },
  { id: "s322", grade: 1, term: "人小志氣高", kind: "諺語", meaning: "年紀或個子雖小，志向卻很遠大，值得稱讚。", example: "他才小學一年級就立志當醫生，真是人小志氣高。", deep: "這句話怎麼來的：民間常語，也說「人小志不小」，是用來稱讚年紀小卻有大志向的孩子。\n字面意思：人雖然小，志氣卻很高。\n引申意思：志向和年紀、身材無關。它是鼓勵的話，重點在「不要用外表判斷一個人能走多遠」。" },
  { id: "s323", grade: 1, term: "十五的月亮——圓圓滿滿", kind: "歇後語", meaning: "農曆十五的月亮最圓，比喻事情圓滿、家人團圓。", example: "全家人聚在一起吃團圓飯，真像十五的月亮——圓圓滿滿。", deep: "這句話怎麼來的：農曆每個月十五，月亮最圓最亮，所以「十五的月亮」就成了圓滿的代名詞。\n字面意思：農曆十五的月亮，又圓又滿。\n引申意思：事情圓滿、家人團圓。它是吉祥話，中秋節前後特別常用。" },
  { id: "s324", grade: 1, term: "放鴿子", kind: "俚語", meaning: "比喻和人約好了卻故意不出現，讓對方白等。", example: "他昨天放我鴿子，害我在公園等了半個小時。", deep: "這句話怎麼來的：一般認為和賽鴿有關——放出去的鴿子沒有飛回來，主人白等一場。\n字面意思：把鴿子放出去。\n引申意思：約好了卻沒出現，讓人白等。它的重點在「對方在等」，所以比單純的遲到嚴重。" },
  { id: "s325", grade: 1, term: "助人為快樂之本", kind: "諺語", meaning: "幫助別人是快樂的根源，鼓勵人多行善事。", example: "老師常說助人為快樂之本，所以我很喜歡當小幫手。", deep: "這句話怎麼來的：現代常見的勸善標語，源頭可追到西方 It is more blessed to give than to receive 的觀念與中國「為善最樂」的說法。\n字面意思：幫助別人是快樂的根本。\n引申意思：行善會讓自己開心。它有意思的地方在於——理由不是「應該」，而是「你會比較快樂」。" },
  { id: "s326", grade: 2, term: "一勤天下無難事", kind: "諺語", meaning: "只要勤勞肯做，天下就沒有辦不成的事。", example: "爸爸靠著早起晚睡把小店做起來，真是一勤天下無難事。", deep: "典故由來：出自清代錢泳《履園叢話》：「一勤天下無難事。」\n字面意思：只要肯勤勞，天下就沒有難事。\n引申意思：勤勞能克服困難。它和「世上無難事，只怕有心人」意思相近，這句把重點放在「勤」上。" },
  { id: "s327", grade: 2, term: "八月十五的月餅——人人有份", kind: "歇後語", meaning: "中秋節分月餅每個人都有，比喻好處大家共享，誰也不缺。", example: "班上得到的獎品，就像八月十五的月餅——人人有份。", deep: "這句話怎麼來的：中秋節分月餅，一人一塊，誰也不會少，是最公平的分配畫面。\n字面意思：八月十五的月餅，每個人都有一份。\n引申意思：好處大家都有份。它有時是好意（雨露均霑），有時是諷刺（連不該有的人也拿到了）。" },
  { id: "s328", grade: 2, term: "潑冷水", kind: "俚語", meaning: "比喻在別人興頭上說洩氣話，打擊對方的熱情。", example: "他才說要參加比賽，你就潑冷水，太不夠意思了。", deep: "這句話怎麼來的：燒得正旺的火被潑上一盆冷水，立刻就滅了，用來比喻打擊別人的熱情。\n字面意思：在熱的東西上潑冷水。\n引申意思：在別人興頭上說洩氣話。要注意——有時候那盆冷水是必要的提醒，用這個詞的人通常不覺得。" },
  { id: "s329", grade: 3, term: "碰釘子", kind: "俚語", meaning: "比喻做事遭到拒絕或受到挫折。", example: "他去借球被拒絕，碰了個釘子，垂頭喪氣地回來。", deep: "這句話怎麼來的：釘子突出在木板上，人沒看到一頭撞上去，又痛又意外。\n字面意思：撞上了釘子。\n引申意思：做事被拒絕或受挫。它的畫面裡有「沒預料到」的成分——碰釘子多半是自己以為會順利。" },
  { id: "s330", grade: 3, term: "打鐵趁熱", kind: "諺語", meaning: "打鐵要趁鐵燒紅時，比喻做事要把握最好的時機，一鼓作氣。", example: "老師剛教完，我們打鐵趁熱馬上練習，印象最深刻。", deep: "這句話怎麼來的：鐵匠打鐵要在鐵燒紅發軟的時候下錘，涼了就打不動了。\n字面意思：打鐵要趁鐵還熱的時候。\n引申意思：要把握最好的時機，一鼓作氣。它同時暗示了「熱度會消退」——不只是機會會過，人的勁頭也會。" },
  { id: "s331", grade: 4, term: "打破砂鍋——問到底", kind: "歇後語", meaning: "「璺」（裂紋）到底諧音「問到底」，形容追根究柢，非弄清楚不可。", example: "他對什麼都好奇，凡事像打破砂鍋——問到底。", deep: "這句話怎麼來的：靠的是諧音。砂鍋一破，裂紋（「璺」，音同「問」）會一路裂到底，「璺到底」聽起來就是「問到底」。\n字面意思：砂鍋打破，裂紋一路到底。\n引申意思：追根究柢不弄清楚不罷休。它是諧音型歇後語，答案藏在「璺」和「問」的同音上。" },
  { id: "s332", grade: 4, term: "無風不起浪", kind: "諺語", meaning: "沒有風就不會起浪，比喻事情的發生總有原因，傳聞多半有來由。", example: "無風不起浪，這件事會傳開，恐怕不是完全沒根據。", deep: "典故由來：出自宋玉〈風賦〉的意象與民間說法，用自然現象講因果。\n字面意思：沒有風就不會起浪。\n引申意思：事情發生總有原因，傳聞多半有來由。要小心用——它常被拿來替沒有根據的謠言背書，「有風」不代表傳的內容是真的。" },
  { id: "s333", grade: 5, term: "馬後炮", kind: "俚語", meaning: "象棋術語借來比喻事情過後才提意見或補救，已經無濟於事。", example: "比賽輸了你才說早知道要換人，這不是放馬後炮嗎？", deep: "這句話怎麼來的：象棋的「馬後炮」是炮在馬的後面將軍，但棋局已定才擺出來就沒有用了。\n字面意思：馬走過去之後才放的炮。\n引申意思：事後才提意見，已經來不及。它的重點在時機——同樣的話早一點說是建議，晚了就是馬後炮。" },
  { id: "s334", grade: 5, term: "三天打魚，兩天曬網", kind: "諺語", meaning: "比喻做事沒有恆心，時常中斷，斷斷續續難有成果。", example: "學琴要每天練，三天打魚，兩天曬網是學不好的。", deep: "典故由來：出自《紅樓夢》。薛蟠上學「三天打魚，兩天曬網」，讀書斷斷續續。\n字面意思：打三天魚，曬兩天網。\n引申意思：做事沒有恆心，時常中斷。它妙在曬網本來是必要的保養，但兩天曬網、三天打魚的比例就變成偷懶了。" },
  { id: "s335", grade: 6, term: "半路出家", kind: "俚語", meaning: "原指成年後才出家，比喻中途改行，不是本行出身。", example: "他本來是廚師，半路出家學攝影，卻拍出了名氣。", deep: "這句話怎麼來的：從前出家多半從小開始，成年後才剃度的叫「半路出家」，基本功不如自幼修行的人。\n字面意思：走到一半才去出家。\n引申意思：中途改行，不是本行出身。它不一定是貶義——現在也常用來自謙。" },
  { id: "s336", grade: 6, term: "留一手", kind: "俚語", meaning: "比喻不把本領全部拿出來或教給別人，保留一部分。", example: "師傅教徒弟總愛留一手，關鍵的火候只有他自己知道。", deep: "這句話怎麼來的：從前師傅教徒弟怕「教會徒弟餓死師傅」，最後一招通常留著不教。\n字面意思：留下一招不拿出來。\n引申意思：不把本領全部拿出來或教出去。它背後是舊時代的行業生態，現在用它多半帶著批評。" },
  { id: "s337", grade: 6, term: "解鈴還須繫鈴人", kind: "諺語", meaning: "鈴是誰繫上的就該由誰解下，比喻問題該由造成的人去解決。", example: "他們兩人的誤會，解鈴還須繫鈴人，還是得阿明自己去道歉。", deep: "典故由來：出自《指月錄》。法眼禪師問眾人「老虎脖子上的金鈴，誰解得下來」，沒人答得出，法燈說「繫者解得」。\n字面意思：鈴是誰繫上去的，就該由誰解下來。\n引申意思：問題該由造成的人去解決。它同時暗示了一件事——別人插手往往解不開，因為只有繫的人知道怎麼打的結。" },
  { id: "s338", grade: 6, term: "孫猴子的臉——說變就變", kind: "歇後語", meaning: "孫悟空會七十二變，比喻人的臉色、態度或事情變化非常快。", example: "山上的天氣像孫猴子的臉——說變就變，記得帶雨衣。", deep: "典故由來：出自《西遊記》。孫悟空會七十二變，臉說變就變，一下是老人一下是蟲子。\n字面意思：孫猴子的臉，說變就變。\n引申意思：態度或情況變化極快。它多半用在人翻臉的時候，語氣是抱怨對方前後不一。" },
  { id: "s339", grade: 7, term: "磨刀不誤砍柴工", kind: "諺語", meaning: "先把刀磨利，砍柴反而更快，比喻事前準備充分，能提高效率不算耽誤。", example: "先把讀書計畫排好再開始，磨刀不誤砍柴工。", deep: "這句話怎麼來的：樵夫的經驗——花時間磨刀看似耽誤，但刀利了砍柴快好幾倍，總時間反而更短。\n字面意思：磨刀的時間不會耽誤砍柴。\n引申意思：事前準備不算浪費時間。它反的是「先做再說」的直覺，因為準備的效果要算總帳才看得出來。" },
  { id: "s340", grade: 7, term: "換湯不換藥", kind: "俚語", meaning: "湯換了藥沒換，比喻只改變形式，內容和本質依舊。", example: "新規定只是把名稱改了，內容換湯不換藥。", deep: "這句話怎麼來的：中藥店抓藥，藥引子（湯）換了，主藥沒換，病治的還是同一個方子。\n字面意思：湯換了，藥沒換。\n引申意思：只改形式，本質沒變。它常用在改革和政策上，批評的重點是「看起來不一樣了，其實一樣」。" },
  { id: "s341", grade: 7, term: "水仙不開花——裝蒜", kind: "歇後語", meaning: "水仙不開花時樣子像蒜，比喻明明知道卻假裝不知道、裝糊塗。", example: "明明是你拿走的，還在那裡水仙不開花——裝蒜。", deep: "這句話怎麼來的：水仙還沒開花時，長長的葉子和蒜苗幾乎一模一樣，分不出來。「裝蒜」就成了裝糊塗的意思。\n字面意思：水仙不開花，看起來就像蒜。\n引申意思：明明知道卻假裝不知道。它妙在「裝蒜」既是外形上真的像蒜，也是現成的口語。" },
  { id: "s342", grade: 8, term: "路遙知馬力，日久見人心", kind: "諺語", meaning: "路途遠才知道馬的耐力，相處久才看得出人心的真假。", example: "他默默幫了我們這麼多年，路遙知馬力，日久見人心。", deep: "典故由來：出自元曲《爭報恩》：「路遙知馬力，日久見人心。」\n字面意思：路走遠了才知道馬有沒有力氣，日子久了才看得出人心。\n引申意思：真假要靠時間檢驗。它用「遠」和「久」兩個時間詞，說明短時間看不出來的東西需要什麼。" },
  { id: "s343", grade: 8, term: "世上無難事，只怕有心人", kind: "諺語", meaning: "只要有決心、肯下功夫，再難的事也能辦成。", example: "世上無難事，只怕有心人，他自學三年終於考上了。", deep: "典故由來：出自元代王實甫《西廂記》及明清小說的常語，也寫作「天下無難事，只怕有心人」。\n字面意思：世上沒有難事，怕的是遇到有心的人。\n引申意思：肯下決心就辦得成。「有心」是關鍵——它指的不只是想要，而是願意一直放在心上。" },
  { id: "s344", grade: 8, term: "打腫臉充胖子", kind: "俚語", meaning: "比喻明明沒有實力，硬撐場面裝作了不起。", example: "收入不多卻硬要買名牌，何必打腫臉充胖子？", deep: "這句話怎麼來的：把臉打腫看起來就圓潤了，像個胖子，但那是打出來的，不是養出來的。\n字面意思：把臉打腫，裝成胖子。\n引申意思：沒有實力硬撐場面。它殘酷的地方在於——那個腫是自己打的，而且會痛。" },
  { id: "s345", grade: 8, term: "掛羊頭賣狗肉", kind: "俚語", meaning: "招牌上掛羊頭，實際賣狗肉，比喻表裡不一，用好名目做欺騙的事。", example: "號稱有機蔬菜卻來路不明，根本是掛羊頭賣狗肉。", deep: "典故由來：出自《晏子春秋》。齊靈公喜歡女子穿男裝卻又下令禁止，晏子說這就像「懸牛首於門，而賣馬肉於內」，後來演變成掛羊頭賣狗肉。\n字面意思：門口掛的是羊頭，裡面賣的是狗肉。\n引申意思：招牌和實貨不符。它罵的是刻意的欺騙，不是單純的品質不好。" },
  { id: "s346", grade: 8, term: "秋後的螞蚱——蹦躂不了幾天", kind: "歇後語", meaning: "入秋天冷螞蚱將死，比喻壞人或敗勢已定的事撐不了多久。", example: "詐騙集團再囂張，也是秋後的螞蚱——蹦躂不了幾天。", deep: "這句話怎麼來的：螞蚱（蝗蟲）夏天蹦得最起勁，一入秋天冷就活不了幾天了。\n字面意思：秋天以後的螞蚱，蹦不了幾天。\n引申意思：敗勢已定，撐不了多久。它是說給還在囂張的一方聽的，語氣是冷冷的預告。" },
  { id: "s347", grade: 9, term: "十年樹木，百年樹人", kind: "諺語", meaning: "培植樹木要十年，培育人才要百年，比喻教育是長遠大計。", example: "十年樹木，百年樹人，辦教育急不得。", deep: "典故由來：出自《管子．權修》：「一年之計，莫如樹穀；十年之計，莫如樹木；終身之計，莫如樹人。」\n字面意思：種樹要十年，育人要一百年。\n引申意思：教育是最長遠的投資。「樹」在這裡是動詞，是「種植、培育」的意思。" },
  { id: "s348", grade: 9, term: "學如逆水行舟，不進則退", kind: "諺語", meaning: "學習像逆著水流行船，不努力前進就會後退。", example: "放假也要溫習，學如逆水行舟，不進則退。", deep: "典故由來：出自清代《訓學齋規》一類的勸學書，常和「心似平原走馬，易放難收」對照。\n字面意思：學習像逆著水流行船，不往前就會被沖回去。\n引申意思：停下來就等於退步。它的重點在「逆水」——維持原地也需要花力氣。" },
  { id: "s349", grade: 9, term: "真金不怕火煉", kind: "諺語", meaning: "真正的黃金不怕烈火鍛煉，比喻真才實學或清白經得起考驗。", example: "儘管流言四起，他仍坦然面對，真金不怕火煉。", deep: "這句話怎麼來的：黃金的熔點高又不易氧化，反覆鍛燒也不會變質，摻了雜質的假金一燒就露餡。\n字面意思：真的黃金不怕火燒。\n引申意思：真本事經得起考驗。它安慰的是被質疑的人，但前提是——你得真的是金子。" },
  { id: "s350", grade: 9, term: "紙包不住火", kind: "諺語", meaning: "紙終究包不住火，比喻真相或壞事隱瞞不了，遲早會暴露。", example: "犯了錯就趕快承認，紙包不住火，拖越久越糟。", deep: "這句話怎麼來的：紙一碰到火就燒起來，怎麼包也包不住。\n字面意思：紙包不住火。\n引申意思：真相隱瞞不了，遲早會爆開。它的畫面裡有時間感——不是馬上，是「遲早」。" },
  { id: "s351", grade: 9, term: "上樑不正下樑歪", kind: "諺語", meaning: "上面的樑歪了，下面的樑也會跟著歪，比喻在上位者行為不正，下面的人就會跟著學壞。", example: "主管帶頭虛報帳目，上樑不正下樑歪，部門風氣才會敗壞。", deep: "這句話怎麼來的：蓋房子時上面的樑要先擺正，上樑歪了，下面的樑照著擺就跟著歪。\n字面意思：上面的樑歪了，下面的樑也跟著歪。\n引申意思：上位者行為不正，下面的人就學壞。它把責任放在上面，因為下樑是照著上樑擺的。" },
  { id: "s352", grade: 9, term: "穿小鞋", kind: "俚語", meaning: "比喻暗中刁難、報復別人，給人吃暗虧。", example: "他因為說了實話，就被主管穿小鞋，處處刁難。", deep: "典故由來：據說源自舊時婚俗——婆家送去一雙小鞋，媳婦硬穿只能忍痛，卻說不出口。\n字面意思：讓人穿不合腳的小鞋。\n引申意思：暗中刁難、給人吃暗虧。它的特點是「表面看不出來」，被整的人有苦難言。" },
  { id: "s353", grade: 9, term: "敲竹槓", kind: "俚語", meaning: "比喻利用別人的弱點或藉機抬高價錢，索取財物。", example: "觀光區有些店家專敲遊客竹槓，一瓶水賣三倍價。", deep: "這句話怎麼來的：從前船運貨物用竹槓挑扛，稅吏或幫派敲一敲竹槓，藉口貨有問題就趁機索財。\n字面意思：敲一敲竹槓。\n引申意思：藉機抬價或勒索。它的重點在「藉口」——理由是隨便找的，目的是要錢。" },
  { id: "s354", grade: 9, term: "下馬威", kind: "俚語", meaning: "原指官員上任時先顯威風，比喻一開始就給人厲害的顏色看。", example: "新教練第一天就加練體能，給大家來了個下馬威。", deep: "典故由來：出自《漢書．敘傳》的「下車作威」，後演變成「下馬威」——官員一到任先立威，讓下屬不敢造次。\n字面意思：剛下馬就先擺出威風。\n引申意思：一開始就給人厲害的顏色看。它強調的是「時機」——威要立在最前面才有效。" },
  { id: "s355", grade: 9, term: "黃連樹下彈琴——苦中作樂", kind: "歇後語", meaning: "黃連極苦，在黃連樹下彈琴，比喻在困苦的處境中自尋樂趣。", example: "工地生活辛苦，他們晚上圍著唱歌，黃連樹下彈琴——苦中作樂。", deep: "這句話怎麼來的：黃連是最苦的藥材，人坐在黃連樹下還彈起琴來，苦是真的苦，樂也是真的找出來的。\n字面意思：在黃連樹下彈琴。\n引申意思：在困苦中自尋樂趣。它不是說苦不存在，而是說人可以在苦裡面替自己挖一點空間。" },
  { id: "s356", grade: 9, term: "老鼠鑽風箱——兩頭受氣", kind: "歇後語", meaning: "風箱兩頭進出風，老鼠鑽進去兩邊都挨吹，比喻夾在中間兩面不討好。", example: "他夾在婆媳之間，老鼠鑽風箱——兩頭受氣。", deep: "這句話怎麼來的：風箱是兩頭進出風的，老鼠鑽進去，推也吹、拉也吹，兩邊都躲不掉。\n字面意思：老鼠鑽進風箱，兩頭都被吹。\n引申意思：夾在中間兩面不討好。它的畫面說明了為什麼難受——不是有人針對你，是位置本身就在風口。" },
  { id: "s357", grade: 10, term: "疾風知勁草", kind: "諺語", meaning: "狂風中才看得出哪株草堅韌不倒，比喻危難時刻才能考驗出人的堅強品格。", example: "公司最困難時他不離不棄，疾風知勁草，患難見真情。", deep: "典故由來：出自《後漢書．王霸傳》。光武帝劉秀對王霸說「疾風知勁草」，稱讚他在眾人離去時仍留下來。\n字面意思：狂風吹過，才看得出哪株草夠韌。\n引申意思：危難時才看得出真正堅強的人。原典是在患難之後說的，所以它是對留下來的人的肯定。" },
  { id: "s358", grade: 10, term: "山雨欲來風滿樓", kind: "諺語", meaning: "大雨來臨前滿樓狂風，比喻重大事件爆發前，已有緊張的徵兆和氣氛。", example: "兩家公司高層頻頻放話，山雨欲來風滿樓，購併戰恐怕一觸即發。", deep: "典故由來：出自唐代許渾〈咸陽城東樓〉：「溪雲初起日沉閣，山雨欲來風滿樓。」\n字面意思：山中的大雨快來了，滿樓都是風。\n引申意思：大事發生前已經有徵兆。它形容的是那種「還沒發生但空氣已經變了」的緊張感。" },
  { id: "s359", grade: 10, term: "塞翁失馬，焉知非福", kind: "諺語", meaning: "邊塞老翁丟了馬反而因禍得福，比喻一時的損失未必是壞事，禍福常會互相轉化。", example: "沒考上第一志願反而遇到好老師，塞翁失馬，焉知非福。", deep: "典故由來：出自《淮南子．人間訓》。邊塞老翁的馬跑掉，鄰人來安慰，他說未必是壞事；後來馬帶回一匹好馬，兒子騎馬摔斷腿，卻因此免於徵兵。\n字面意思：邊塞老翁丟了馬，怎麼知道不是福氣。\n引申意思：禍福會互相轉化。原典的重點是「當下判斷不了」，不是說壞事一定會變好事。" },
  { id: "s360", grade: 10, term: "巧婦難為無米之炊", kind: "諺語", meaning: "再能幹的主婦沒有米也煮不出飯，比喻缺乏必要條件，再有本事也難成事。", example: "沒有預算什麼活動都辦不成，巧婦難為無米之炊。", deep: "典故由來：出自宋代陸游《老學庵筆記》所引的俗語「巧婦難為無米之炊」。\n字面意思：再能幹的主婦，沒有米也煮不出飯。\n引申意思：缺少必要條件，本事再大也沒用。它是替被責備的人說話的——先看條件夠不夠，再談能力。" },
  { id: "s361", grade: 10, term: "良禽擇木而棲", kind: "諺語", meaning: "好鳥會選擇良木築巢，比喻賢者會選擇值得效力的對象或環境。", example: "良禽擇木而棲，人才自然流向重視他們的公司。", deep: "典故由來：出自《左傳．哀公十一年》。孔子說「鳥則擇木，木豈能擇鳥」，表示賢者可以選擇效力的對象。\n字面意思：好鳥會挑好樹來築巢。\n引申意思：有才能的人會選擇值得投靠的環境。原句還有下半段——樹不能挑鳥，所以主動權在人才手上。" },
  { id: "s362", grade: 10, term: "人往高處走，水往低處流", kind: "諺語", meaning: "人應該力求上進，就像水自然往低處流一樣是常理。", example: "他決定出國進修，人往高處走，大家都祝福他。", deep: "這句話怎麼來的：民間常語，把人的上進心和水往低處流並列，說兩者都是自然而然的事。\n字面意思：人要往高處走，水會往低處流。\n引申意思：追求更好是人的本性。它用自然規律替上進心背書，等於說「這件事不需要理由」。" },
  { id: "s363", grade: 10, term: "兵來將擋，水來土掩", kind: "諺語", meaning: "敵兵來了派將抵擋，大水來了用土掩蓋，比喻不管遇到什麼情況，都有相應的辦法對付。", example: "對手出什麼招都別慌，兵來將擋，水來土掩。", deep: "典故由來：出自元曲《大戰邳彤》等劇本的常語，也寫成「將擋兵，土掩水」。\n字面意思：敵兵來了派將去擋，大水來了用土去堵。\n引申意思：不管什麼情況都有對付的辦法。它的語氣是沉著，重點在「見招拆招」而不是預先算好。" },
  { id: "s364", grade: 10, term: "車到山前必有路", kind: "諺語", meaning: "車行到山前自然會出現道路，比喻事到臨頭總會有解決的辦法，不必過分憂慮。", example: "先別擔心經費，車到山前必有路，一步一步來。", deep: "這句話怎麼來的：從前趕車走山路，遠看山壁像一堵牆，走近才發現有路繞過去。\n字面意思：車開到山前，自然會有路。\n引申意思：事到臨頭總有辦法。它常和「船到橋頭自然直」連用，兩句都在勸人別提前焦慮。" },
  { id: "s365", grade: 10, term: "樹倒猢猻散", kind: "諺語", meaning: "大樹倒了，樹上的猴子一哄而散，比喻有權勢的人一垮台，依附的人便紛紛離去。", example: "董事長一被收押，昔日圍著他的人全不見了，正是樹倒猢猻散。", deep: "典故由來：出自宋代龐元英《談藪》。南宋的曹詠依附權臣秦檜，秦檜一死，有人寫了〈樹倒猢猻散賦〉送給他。\n字面意思：大樹一倒，樹上的猴子就散了。\n引申意思：靠山垮了，依附的人就散。它的角度很冷——散的人不是背叛，是本來就只是在樹上。" },
  { id: "s366", grade: 10, term: "有燒香有保庇", kind: "俚語", meaning: "（台語）有燒香就有神明保佑，比喻有付出、有準備，總會有相應的回報。", example: "平時有練習有實力，有燒香有保庇，上場就不怕。", deep: "這句話怎麼來的：臺灣的閩南語俗諺。有去廟裡上香的人，才有神明保佑，沒去的當然沒有。\n字面意思：有燒香，才有保佑。\n引申意思：有付出才有回報。它表面在講拜拜，實際上講的是「先做了才有得談」。" },
  { id: "s367", grade: 10, term: "牛牽到北京嘛是牛", kind: "俚語", meaning: "（台語）牛就算牽到北京還是牛，比喻本性難改，換了環境依然故我。", example: "他到新公司還是遲到，唉，牛牽到北京嘛是牛。", deep: "這句話怎麼來的：臺灣的閩南語俗諺。北京是最遠最繁華的地方，但牛牽到那裡還是牛，不會因此變成別的。\n字面意思：牛牽到北京，還是一頭牛。\n引申意思：本性難改，換環境也一樣。它是帶著無奈的斷語，多半用在勸過很多次還是沒用的人身上。" },
  { id: "s368", grade: 10, term: "破天荒", kind: "俚語", meaning: "唐代荊州多年無人考中進士，稱「天荒」，後有人考中打破紀錄，比喻從未有過、頭一次發生的事。", example: "他破天荒主動留下來打掃，大家都嚇了一跳。", deep: "典故由來：唐代荊州長年沒有人考中進士，被稱為「天荒」；後來劉蛻考上了，人們就說他「破天荒」。\n字面意思：打破了「天荒」的紀錄。\n引申意思：從來沒有過、頭一次發生。它原本專指科舉，現在泛用在任何「第一次」上。" },
  { id: "s369", grade: 10, term: "打圓場", kind: "俚語", meaning: "比喻出面調解尷尬或僵持的場面，讓雙方都有台階下。", example: "兩人吵得下不了台，還好班長出來打圓場。", deep: "這句話怎麼來的：「圓場」原是戲曲術語，演員在台上繞圈走表示趕路；後來借來指把僵住的場面繞回來。\n字面意思：把場面繞成一個圓。\n引申意思：出面調解，讓雙方都有台階下。它的技巧在於「不判誰對誰錯」，只是把場面接回去。" },
  { id: "s370", grade: 10, term: "張飛繡花——粗中有細", kind: "歇後語", meaning: "猛將張飛做細活，比喻外表粗獷的人做事也有細心的一面。", example: "別看他大剌剌的，帳目記得一清二楚，張飛繡花——粗中有細。", deep: "典故由來：出自《三國演義》裡張飛的形象。張飛以勇猛出名，卻也用過計謀（如義釋嚴顏），所以後人說他粗中有細。\n字面意思：張飛拿起針線繡花。\n引申意思：外表粗獷的人也有細心的一面。它是稱讚的話，重點在「反差」。" },
  { id: "s371", grade: 11, term: "由儉入奢易，由奢入儉難", kind: "諺語", meaning: "從節儉變奢侈很容易，從奢侈回到節儉卻很難，勸人守住儉樸的生活習慣。", example: "富起來也別亂花，由儉入奢易，由奢入儉難。", deep: "典故由來：出自宋代司馬光〈訓儉示康〉，是他寫給兒子的家訓。\n字面意思：從節儉變奢侈很容易，從奢侈回到節儉很難。\n引申意思：生活水準往上調容易，往下調難。它提醒的是——享受過的東西會變成「基本需求」，所以要小心一開始怎麼過。" },
  { id: "s372", grade: 11, term: "良言一句三冬暖，惡語傷人六月寒", kind: "諺語", meaning: "一句善意的話讓人在寒冬也覺得溫暖，一句惡毒的話讓人在盛夏也感到心寒，勸人謹慎言語。", example: "說話前多想想，良言一句三冬暖，惡語傷人六月寒。", deep: "典故由來：出自明代《增廣賢文》所收的俗語。\n字面意思：一句好話讓人在三冬也覺得暖，一句惡話讓人在六月也覺得冷。\n引申意思：話語的溫度勝過天氣。它用冬和夏兩個極端的季節對照，說明話的力量能反過來蓋過環境。" },
  { id: "s373", grade: 11, term: "靜坐常思己過，閒談莫論人非", kind: "諺語", meaning: "獨處時常反省自己的過錯，閒聊時不要議論別人的是非，是修身處世的格言。", example: "把「靜坐常思己過，閒談莫論人非」貼在書桌前提醒自己。", deep: "典故由來：出自清代《朱子家訓》一系的格言（一般題為朱柏廬），常寫成對聯掛在廳堂。\n字面意思：一個人靜坐時常想自己的過錯，聊天時不要說別人的是非。\n引申意思：對自己嚴、對別人寬。它把「反省」和「不論人非」放在一起，是因為兩者都靠同一種自制。" },
  { id: "s374", grade: 11, term: "來說是非者，便是是非人", kind: "諺語", meaning: "主動來搬弄是非的人，本身往往就是製造是非的人，提醒人提防搬弄口舌者。", example: "他一來就數落同事不是，來說是非者，便是是非人，聽聽就好。", deep: "典故由來：出自《增廣賢文》：「來說是非者，便是是非人。」\n字面意思：跑來跟你講是非的人，本身就是是非的來源。\n引申意思：搬弄口舌的人要提防。它的推論很利落——他今天能跟你講別人，明天就能跟別人講你。" },
  { id: "s375", grade: 11, term: "有理走遍天下，無理寸步難行", kind: "諺語", meaning: "有道理到哪裡都行得通，沒道理則處處受阻，強調做事要站得住理。", example: "不用怕對方聲音大，有理走遍天下，無理寸步難行。", deep: "典故由來：出自元曲及《增廣賢文》的常語。\n字面意思：有道理走遍天下都通，沒道理連一步都難走。\n引申意思：做事要站得住理。它描述的是理想狀態，現實裡不一定成立——但它要說的是「先把理站穩」這件事本身有價值。" },
  { id: "s376", grade: 11, term: "只許州官放火，不許百姓點燈", kind: "諺語", meaning: "官員自己放火卻不准百姓點燈，比喻在上位者自己胡作非為，卻嚴禁他人正當行為的雙重標準。", example: "主管自己天天遲到卻嚴懲部屬，真是只許州官放火，不許百姓點燈。", deep: "典故由來：出自宋代陸游《老學庵筆記》。有位太守叫田登，忌諱別人說「登」字，元宵放燈時公告寫成「本州依例放火三日」。\n字面意思：只准州官放火，不准百姓點燈。\n引申意思：在上位者的雙重標準。它的力道來自原典的荒謬——「放火」兩個字是他自己改出來的。" },
  { id: "s377", grade: 11, term: "聽君一席話，勝讀十年書", kind: "諺語", meaning: "聽對方一番話，勝過苦讀十年書，形容別人的見解使自己受益極大。", example: "前輩把行業門道一一點破，聽君一席話，勝讀十年書。", deep: "這句話怎麼來的：民間常語，多用在受教之後向對方致謝。\n字面意思：聽你講這一席話，勝過我讀十年書。\n引申意思：對方的見解讓自己收穫極大。它是客套話，但也點出一件事——好的對話可以省掉很多摸索。" },
  { id: "s378", grade: 11, term: "行百里者半九十", kind: "諺語", meaning: "走一百里路，走了九十里只能算走一半，比喻越接近成功越艱難，越要堅持到底。", example: "論文只剩最後一章更要穩住，行百里者半九十。", deep: "典故由來：出自《戰國策．秦策》：「行百里者半於九十，此言末路之難也。」\n字面意思：走一百里的人，走到九十里只能算走了一半。\n引申意思：越接近終點越難，要撐到最後。它的算法故意不合理，就是為了強調最後那十里的份量。" },
  { id: "s379", grade: 11, term: "食米毋知米價", kind: "俚語", meaning: "（台語）吃米卻不知道米的價錢，比喻不知人間疾苦、不懂生活現實。", example: "伸手要錢卻嫌爸媽小氣，真是食米毋知米價。", deep: "這句話怎麼來的：臺灣的閩南語俗諺。天天吃米飯，卻不知道一斤米多少錢。\n字面意思：吃米卻不知道米的價錢。\n引申意思：不知人間疾苦、不懂生活現實。它罵的多半是被照顧得太好的人，語氣是搖頭而不是憤怒。" },
  { id: "s380", grade: 11, term: "近山剉無柴，近溪擔無水", kind: "俚語", meaning: "（台語）住在山邊反而沒柴燒，住在溪邊反而沒水挑，比喻擁有便利條件反而不知珍惜利用。", example: "住在圖書館對面卻從不進去，近山剉無柴，近溪擔無水。", deep: "這句話怎麼來的：臺灣的閩南語俗諺。「剉」是砍。住山邊的人覺得柴隨時砍得到，就一直不去砍；住溪邊的人覺得水隨時挑得到，就一直不去挑。\n字面意思：住山邊反而沒柴，住溪邊反而沒水。\n引申意思：條件太方便反而不去利用。它點破的是拖延的心理——「隨時可以」等於「一直沒有」。" },
  { id: "s381", grade: 11, term: "未曾學行先學飛", kind: "俚語", meaning: "（台語）還沒學會走路就想學飛，比喻不按部就班，好高騖遠。", example: "基本功都沒練就想挑戰高難度，未曾學行先學飛。", deep: "這句話怎麼來的：臺灣的閩南語俗諺。小孩要先會爬、會走，才談得上跑；還不會走就想飛，順序整個錯了。\n字面意思：還沒學會走路，先學飛。\n引申意思：不按部就班、好高騖遠。它強調的是順序，不是說不能有大志向。" },
  { id: "s382", grade: 11, term: "有量才有福", kind: "俚語", meaning: "（台語）有度量的人才有福氣，勸人心胸寬大、不斤斤計較。", example: "跟人計較這些小事做什麼？有量才有福啦。", deep: "這句話怎麼來的：臺灣的閩南語俗諺。「量」是度量、氣量，肚量大的人容得下事，福氣也跟著來。\n字面意思：有度量，才有福氣。\n引申意思：心胸寬大的人日子好過。它把「福」講成度量的結果，而不是運氣的安排。" },
  { id: "s383", grade: 11, term: "灶王爺上天——有一說一", kind: "歇後語", meaning: "傳說灶神年終上天稟報人間事，比喻據實直說，不誇大也不隱瞞。", example: "問他什麼都直說，灶王爺上天——有一說一。", deep: "這句話怎麼來的：傳說灶神一整年待在灶上看著這家人，年終上天向玉皇大帝報告，所以民間過年前要拜灶神、供甜食。\n字面意思：灶王爺上天報告，有一句說一句。\n引申意思：據實直說，不誇大也不隱瞞。有趣的是民間拜灶神供麥芽糖，正是希望他嘴甜一點——這句話和那個習俗剛好相反。" },
  { id: "s384", grade: 11, term: "唐僧念經——一本正經", kind: "歇後語", meaning: "唐僧念經自然正經專注，形容態度莊重認真，有時也帶點嘲諷過於古板。", example: "他連玩桌遊都唐僧念經——一本正經地宣讀規則。", deep: "這句話怎麼來的：《西遊記》裡的唐僧念經時神情最為專注端正，「一本正經」剛好也是現成的成語。\n字面意思：唐僧念經，捧著一本正經書。\n引申意思：態度莊重認真。它也常帶點嘲諷——形容人板著臉、太過拘謹。" },
  { id: "s385", grade: 11, term: "木匠戴枷——自作自受", kind: "歇後語", meaning: "枷是木匠做的，木匠自己戴上，比喻自己做的錯事，由自己承擔惡果。", example: "熬夜打電動隔天考試睡著，木匠戴枷——自作自受。", deep: "這句話怎麼來的：枷是套在犯人脖子上的刑具，本來就是木匠做的；木匠做的枷最後套在自己脖子上。\n字面意思：木匠戴上自己做的枷。\n引申意思：自己做的錯事由自己承擔。它比一般的「自作自受」多了一層——那個工具還是你親手打造的。" },
  { id: "s386", grade: 12, term: "天下興亡，匹夫有責", kind: "諺語", meaning: "國家民族的興盛衰亡，每一個平民都有責任。", example: "他投身公共事務，抱的是天下興亡，匹夫有責的信念。", deep: "典故由來：出自明末清初顧炎武《日知錄》的意思，原文是「保天下者，匹夫之賤，與有責焉耳矣」，後人濃縮成這八個字。\n字面意思：國家的興盛衰亡，每一個平民都有責任。\n引申意思：公共的事人人有份。顧炎武原本區分了「亡國」和「亡天下」——他說匹夫有責的是後者，也就是文化和價值的存亡。" },
  { id: "s387", grade: 12, term: "疑人不用，用人不疑", kind: "諺語", meaning: "懷疑的人就不要任用，既然任用就要充分信任，是用人的基本原則。", example: "老闆敢放手讓年輕人做決定，疑人不用，用人不疑。", deep: "典故由來：出自《金史．熙宗本紀》一類的說法，也見於《宋史》，是歷代用人的原則。\n字面意思：懷疑的人不要用，用了的人不要懷疑。\n引申意思：任用就要充分信任。它的難處在於——判斷要放在用之前，一旦開始用，再回頭懷疑就兩頭落空。" },
  { id: "s388", grade: 12, term: "千軍易得，一將難求", kind: "諺語", meaning: "招募千軍容易，尋得一位良將困難，比喻傑出的領導人才極為難得。", example: "公司不怕缺人手，怕的是千軍易得，一將難求。", deep: "典故由來：出自元代馬致遠《漢宮秋》：「千軍易得，一將難求。」\n字面意思：招募一千個兵容易，找到一個好將領難。\n引申意思：領導人才最難得。它比較的是「數量」和「質量」——兵可以用數的，將不行。" },
  { id: "s389", grade: 12, term: "擒賊先擒王", kind: "諺語", meaning: "捉賊要先捉首領，比喻解決問題要先抓住關鍵或核心。", example: "要整頓交通亂象，先從違規大戶開罰，擒賊先擒王。" },
  { id: "s390", grade: 12, term: "木秀於林，風必摧之", kind: "諺語", meaning: "樹木高出樹林，風必先吹折它，比喻人才出眾或鋒芒太露，容易招致嫉妒與打擊。", example: "他年紀輕輕升上高位便流言纏身，正是木秀於林，風必摧之。" },
  { id: "s391", grade: 12, term: "智者千慮，必有一失", kind: "諺語", meaning: "再聰明的人考慮再周密，也難免有疏漏，提醒人不可自恃聰明。", example: "計畫再完備也要留備案，智者千慮，必有一失。" },
  { id: "s392", grade: 12, term: "不怕慢，只怕站", kind: "諺語", meaning: "進步慢不要緊，最怕停下來不動，勉勵人持續前進。", example: "每天背十個單字就好，不怕慢，只怕站。" },
  { id: "s393", grade: 12, term: "強龍不壓地頭蛇", kind: "諺語", meaning: "再強的外來勢力，也難壓制盤據當地的勢力，比喻外來者須尊重在地實力。", example: "國際大廠來台展店也得入境隨俗，強龍不壓地頭蛇。" },
  { id: "s394", grade: 12, term: "贏贏筊，跋甲輸輸去", kind: "俚語", meaning: "（台語）本來穩贏的賭局，卻打到輸光，比喻大好局面因輕忽或貪心而斷送。", example: "領先二十分還輸球，真是贏贏筊，跋甲輸輸去。" },
  { id: "s395", grade: 12, term: "在生一粒豆，較贏死了拜豬頭", kind: "俚語", meaning: "（台語）父母在世時奉養一粒豆子，勝過死後用豬頭祭拜，勸人及時行孝。", example: "有空多回家陪爸媽，在生一粒豆，較贏死了拜豬頭。" },
  { id: "s396", grade: 12, term: "好田地，不如好子弟", kind: "俚語", meaning: "（台語）留給子孫良田，不如把子孫教育好，強調教養重於財產。", example: "阿公不留房產卻堅持栽培孫子讀書，他說好田地，不如好子弟。" },
  { id: "s397", grade: 12, term: "歹瓜厚籽，歹人厚言語", kind: "俚語", meaning: "（台語）不好的瓜籽特別多，品行差的人藉口和閒話特別多，諷刺多辯多話之人。", example: "他犯了錯理由一大堆，正是歹瓜厚籽，歹人厚言語。" },
  { id: "s398", grade: 12, term: "白骨精遇上孫悟空——原形畢露", kind: "歇後語", meaning: "白骨精再會變化也逃不過孫悟空的火眼金睛，比喻偽裝在行家面前徹底暴露。", example: "假幣一放進驗鈔機，白骨精遇上孫悟空——原形畢露。" },
  { id: "s399", grade: 12, term: "擺渡不成翻了船——弄巧成拙", kind: "歇後語", meaning: "想幫人渡河卻把船弄翻，比喻本想取巧做好事，反而把事情搞砸。", example: "他想幫同學圓謊結果越描越黑，擺渡不成翻了船——弄巧成拙。" },
  { id: "s400", grade: 12, term: "愚公的居處——開門見山", kind: "歇後語", meaning: "傳說愚公家門正對太行、王屋二山，比喻說話或寫文章直截了當，一開頭就進入正題。", example: "他報告一開場就先講結論，愚公的居處——開門見山。" },
  // 2026-08-07 擴充批次一（s401-s420）
  { id: "s401", grade: 2, term: "一分耕耘，一分收穫", kind: "諺語", meaning: "付出多少努力，就得到多少成果；成果與努力成正比。", example: "他每天苦練投籃終於入選校隊，真是一分耕耘，一分收穫。" },
  { id: "s402", grade: 2, term: "不打不相識", kind: "諺語", meaning: "經過一次衝突或較量之後，反而變成互相了解的朋友。", example: "他們為了球場上的判決吵過一架，後來不打不相識，成了好搭檔。", deep: "典故由來：出自《水滸傳》。李逵和張順在江邊打了一場，被浪裡白條整得狼狽，之後兩人反而結為兄弟，宋江就說「不打不相識」。\n字面意思：不打一架，就不會認識。\n引申意思：衝突有時是認識彼此的開始。它說的是「打完之後願意握手」，不是鼓勵先去打架。", deep: "典故由來：出自《水滸傳》。李逵和張順在江邊打了一場，被浪裡白條整得狼狽，之後兩人反而結為兄弟，宋江就說「不打不相識」。\n字面意思：不打一架，就不會認識。\n引申意思：衝突有時是認識彼此的開始。它說的是「打完之後願意握手」，不是鼓勵先去打架。" },
  { id: "s403", grade: 3, term: "一朝被蛇咬，十年怕草繩", kind: "諺語", meaning: "吃過一次虧之後，看到類似的東西就會過度害怕。", example: "上次投資賠光了，他現在一朝被蛇咬，十年怕草繩，什麼都不敢碰。", deep: "這句話怎麼來的：被蛇咬過的人，走在草叢裡看到一條彎彎的草繩，第一個反應也是往後跳。\n字面意思：被蛇咬過一次，十年看到草繩都會怕。\n引申意思：一次痛苦的經驗留下了長期的陰影。它同時指出兩件事——恐懼是真的，但那條繩子並不是蛇。", deep: "這句話怎麼來的：被蛇咬過的人，走在草叢裡看到一條彎彎的草繩，第一個反應也是往後跳。\n字面意思：被蛇咬過一次，十年看到草繩都會怕。\n引申意思：一次痛苦的經驗留下了長期的陰影。它同時指出兩件事——恐懼是真的，但那條繩子並不是蛇。" },
  { id: "s404", grade: 3, term: "天下無不散的筵席", kind: "諺語", meaning: "再好的相聚也總有結束的一天，要學會接受離別。", example: "畢業典禮上大家都哭了，但天下無不散的筵席。", deep: "這句話怎麼來的：明清小說裡常見的說法，《紅樓夢》中也用它來寫賈府盛極而衰、眾人終要各奔東西。\n字面意思：天底下沒有不會散場的宴席。\n引申意思：聚會終有結束，關係也會變化。它的語氣是接受而不是悲觀，常用來安慰捨不得分開的人。", deep: "這句話怎麼來的：明清小說裡常見的說法，《紅樓夢》中也用它來寫賈府盛極而衰、眾人終要各奔東西。\n字面意思：天底下沒有不會散場的宴席。\n引申意思：聚會終有結束，關係也會變化。它的語氣是接受而不是悲觀，常用來安慰捨不得分開的人。" },
  { id: "s405", grade: 4, term: "人心齊，泰山移", kind: "諺語", meaning: "大家同心協力，連泰山都能搬動，比喻團結就能發揮巨大的力量。", example: "全班分工合作布置會場，人心齊，泰山移，一個下午就完成了。" },
  { id: "s406", grade: 4, term: "入境隨俗", kind: "諺語", meaning: "到一個地方，就順從當地的風俗習慣。", example: "到日本泡溫泉要先沖洗身體，入境隨俗，別失了禮數。" },
  { id: "s407", grade: 5, term: "啞子吃湯圓——心裡有數", kind: "歇後語", meaning: "啞巴吃了幾顆湯圓說不出來，但自己清楚，比喻心中明白，只是不說。", example: "這次考得如何他嘴上不講，啞子吃湯圓——心裡有數。" },
  { id: "s408", grade: 5, term: "近朱者赤，近墨者黑", kind: "諺語", meaning: "接近硃砂會變紅，接近墨會變黑，比喻環境與朋友對人的影響很大。", example: "近朱者赤，近墨者黑，跟自律的同學同組，你也會跟著認真。" },
  { id: "s409", grade: 6, term: "隔牆有耳", kind: "諺語", meaning: "說話要小心，牆的另一邊可能有人在聽。", example: "這件事先別在辦公室談，隔牆有耳。", deep: "典故由來：出自《管子．君臣下》：「牆有耳，伏寇在側也。」意思是牆會聽見，敵人就藏在旁邊。\n字面意思：牆的另一邊也長著耳朵。\n引申意思：祕密容易外洩，說話要看場合。它提醒的是說話的人，不是在罵偷聽的人。", deep: "典故由來：出自《管子．君臣下》：「牆有耳，伏寇在側也。」意思是牆會聽見，敵人就藏在旁邊。\n字面意思：牆的另一邊也長著耳朵。\n引申意思：祕密容易外洩，說話要看場合。它提醒的是說話的人，不是在罵偷聽的人。" },
  { id: "s410", grade: 6, term: "隔行如隔山", kind: "諺語", meaning: "不同行業之間差異極大，外行人難以了解另一行的門道。", example: "別看修錶好像簡單，隔行如隔山，沒學過根本無從下手。" },
  { id: "s411", grade: 7, term: "好漢不吃眼前虧", kind: "俚語", meaning: "聰明人懂得避開眼前明顯不利的處境，先保全自己再作打算。", example: "對方人多勢眾，好漢不吃眼前虧，我們先離開再報警處理。" },
  { id: "s412", grade: 7, term: "熟讀唐詩三百首，不會作詩也會吟", kind: "諺語", meaning: "反覆熟讀名作，即使不會創作也能吟誦模仿；強調熟讀與累積的功效。", example: "多背範文吧，熟讀唐詩三百首，不會作詩也會吟，作文自然進步。" },
  { id: "s413", grade: 8, term: "心急吃不了熱豆腐", kind: "俚語", meaning: "豆腐太燙急著吃會燙嘴，比喻做事急躁反而辦不成，要有耐心。", example: "申請流程要一關一關來，心急吃不了熱豆腐。" },
  { id: "s414", grade: 8, term: "江山易改，本性難移", kind: "諺語", meaning: "山河面貌都比人的本性容易改變，形容人的性格習氣極難改變。", example: "他戒了又犯、犯了又戒，唉，江山易改，本性難移。" },
  { id: "s415", grade: 9, term: "騎驢找馬", kind: "俚語", meaning: "先將就目前的位置，同時另尋更好的機會，多指一邊工作一邊找新職。", example: "這份工作先做著，騎驢找馬，有更好的缺再跳槽。" },
  { id: "s416", grade: 9, term: "放長線，釣大魚", kind: "俚語", meaning: "把釣線放長才能釣到大魚，比喻從長計議、先投入耐心以獲取更大的成果。", example: "警方沒有立刻收網，而是放長線，釣大魚，要一舉逮捕幕後主嫌。" },
  { id: "s417", grade: 10, term: "貪小便宜吃大虧", kind: "俚語", meaning: "為了貪圖眼前的小利益，結果蒙受更大的損失。", example: "路邊來歷不明的廉價手機別買，小心貪小便宜吃大虧。" },
  { id: "s418", grade: 10, term: "人怕出名豬怕肥", kind: "俚語", meaning: "豬養肥了就會被宰，人出了名便容易招來麻煩與是非。", example: "他中樂透後親戚紛紛上門借錢，真是人怕出名豬怕肥。" },
  { id: "s419", grade: 11, term: "吃虧就是占便宜", kind: "俚語", meaning: "表面上吃了虧，實際上可能累積信用、人緣或經驗，反而獲益。", example: "多做一點不會少塊肉，吃虧就是占便宜，主管都看在眼裡。" },
  { id: "s420", grade: 12, term: "船過水無痕", kind: "諺語", meaning: "船駛過水面不留痕跡，比喻事情過後不留影響，或譏人事過即忘、不念舊情。", example: "當年大家幫他度過難關，如今他船過水無痕，一句感謝也沒有。" },
  { id: "s421", grade: 5, term: "頭過身就過", kind: "俚語", meaning: "台語俗諺：頭鑽得過去，身體就跟著過得去，比喻最難的第一關通過了，後面就順利了。", example: "第一次上台最緊張，頭過身就過，之後你就敢講了。" },
  { id: "s422", grade: 6, term: "曲不離口，拳不離手", kind: "諺語", meaning: "唱曲要常開口練，打拳要常動手練，比喻技藝必須天天練習才不會生疏。", example: "老師勉勵我們曲不離口，拳不離手，樂器一天不碰就會退步。" },
  { id: "s423", grade: 6, term: "甘蔗無雙頭甜", kind: "諺語", meaning: "台語俗諺：甘蔗不會兩頭都甜，比喻凡事難以十全十美，有所得必有所失。", example: "想住市中心又要房租便宜？甘蔗無雙頭甜，總得取捨。" },
  { id: "s424", grade: 7, term: "目睭花花，匏仔看做菜瓜", kind: "俚語", meaning: "台語俗諺：眼睛昏花，把匏瓜看成絲瓜，笑人看走了眼、認錯對象或東西。", example: "那不是你同學啦，你目睭花花，匏仔看做菜瓜。" },
  { id: "s425", grade: 8, term: "生食都無夠，哪有通曝乾", kind: "諺語", meaning: "台語俗諺：生吃都不夠了，哪還有多餘的拿去曬成乾？比喻收入僅夠餬口，毫無剩餘可儲存。", example: "薪水繳完房租就見底，生食都無夠，哪有通曝乾，怎麼存錢？" },
  { id: "s426", grade: 8, term: "嘴上無毛，辦事不牢", kind: "俚語", meaning: "譏笑人年輕、閱歷淺，做事不夠穩當可靠。", example: "老師傅起初嫌他嘴上無毛，辦事不牢，後來卻對他的細心刮目相看。" },
  { id: "s427", grade: 9, term: "三年一閏，好歹照輪", kind: "諺語", meaning: "台語俗諺：曆法三年一閏、循環有序，比喻運勢好壞輪流轉，不會永遠是同一人得意或失意。", example: "別得意得太早，三年一閏，好歹照輪，風水輪流轉。" },
  { id: "s428", grade: 10, term: "別人的囝死袂了", kind: "諺語", meaning: "台語俗諺：反正死的是別人的孩子，死不完也不心疼，譏諷人自私冷血，慷他人之慨、不顧他人死活。", example: "把危險的工作全推給新人，真是別人的囝死袂了。" },
  { id: "s429", grade: 4, term: "惦惦吃三碗公", kind: "俚語", meaning: "台語俗諺：不聲不響卻吃下三大碗公飯，形容人外表安靜低調，私下卻大有作為或大有斬獲，深藏不露。", example: "他平常不吭聲，段考卻拿下全校第一，真是惦惦吃三碗公。" },
  { id: "s430", grade: 5, term: "一波未平，一波又起", kind: "諺語", meaning: "一個麻煩還沒解決，另一個麻煩又接著來。", example: "設備才剛修好又停電，真是一波未平，一波又起。", deep: "典故由來：出自宋代姜夔《白石道人詩說》，原本是在講寫詩的章法——句子要像波浪一樣一層推一層。\n字面意思：前一個浪還沒平息，後一個浪又起來了。\n引申意思：麻煩接連不斷。有趣的是它本來是誇獎文章有起伏的好話，後來被借去形容倒霉事一件接一件。" },
  { id: "s431", grade: 6, term: "摸蜆仔兼洗褲", kind: "俚語", meaning: "台語俗諺：下水摸蜆的同時順便把褲子洗了，比喻做一件事同時收到兩種好處，一舉兩得。", example: "陪爺爺散步運動，還能順路買早餐，正是摸蜆仔兼洗褲。" },
  { id: "s432", grade: 7, term: "生雞卵無，放雞屎有", kind: "俚語", meaning: "台語俗諺：要牠生蛋沒有，拉屎倒是不少，譏人正事做不成、只會添亂，成事不足敗事有餘。", example: "叫他幫忙整理資料，反而把檔案弄丟，真是生雞卵無，放雞屎有。" },
  { id: "s433", grade: 8, term: "三十六計，走為上策", kind: "諺語", meaning: "情勢明顯不利的時候，及時離開才是最好的選擇。", example: "對方人多又不講理，三十六計走為上策，先離開再說。", deep: "典故由來：出自《南齊書．王敬則傳》：「檀公三十六策，走是上計。」講的是南朝名將檀道濟在打不贏的時候果斷撤退。\n字面意思：三十六種計策裡，逃走是最上等的一計。\n引申意思：打不贏就先保住自己。它強調的是判斷力——知道什麼時候該走，不是鼓勵遇事就跑。" },
  { id: "s434", grade: 8, term: "有錢能使鬼推磨", kind: "諺語", meaning: "有了錢，很多本來辦不成的事也辦得成。", example: "這麼難訂的位子他都訂到了，真是有錢能使鬼推磨。", deep: "這句話怎麼來的：明代小說裡已經在用，把「連鬼都肯替你推石磨」當成錢的力量的極端形容。\n字面意思：有錢連鬼都會幫你推磨。\n引申意思：金錢的影響力很大。這句話的語氣是感嘆甚至諷刺，不是在稱讚有錢好。", deep: "這句話怎麼來的：明代小說裡已經在用，把「連鬼都肯替你推石磨」當成錢的力量的極端形容。\n字面意思：有錢連鬼都會幫你推磨。\n引申意思：金錢的影響力很大。這句話的語氣是感嘆甚至諷刺，不是在稱讚有錢好。" },
  { id: "s435", grade: 9, term: "井水不犯河水", kind: "俚語", meaning: "雙方各管各的，互不干涉也互不往來。", example: "你走你的，我走我的，井水不犯河水。", deep: "這句話怎麼來的：井水從地下來，河水在地面流，兩邊各有各的來源，本來就不會混在一起。\n字面意思：井裡的水不會流進河裡。\n引申意思：各守本分、互不干涉。說這句話的時候通常帶著劃清界線的口氣，不是在講和睦相處。", deep: "這句話怎麼來的：井水從地下來，河水在地面流，兩邊各有各的來源，本來就不會混在一起。\n字面意思：井裡的水不會流進河裡。\n引申意思：各守本分、互不干涉。說這句話的時候通常帶著劃清界線的口氣，不是在講和睦相處。" },
  { id: "s436", grade: 10, term: "拍斷手骨顛倒勇", kind: "諺語", meaning: "台語俗諺：手骨折斷了，癒合後反而更強壯，比喻歷經挫折不被打倒，愈挫愈勇、更加堅強。", example: "創業失敗兩次他都重新站起來，拍斷手骨顛倒勇，第三次終於成功。" },
  { id: "s437", grade: 4, term: "蚊子叮牛角", kind: "俚語", meaning: "台語俗諺：蚊子叮在堅硬的牛角上，牛毫無感覺，比喻絲毫不起作用、無關痛癢。", example: "對屢勸不聽的人講道理，就像蚊子叮牛角，一點用也沒有。" },
  { id: "s438", grade: 5, term: "這山望著那山高", kind: "諺語", meaning: "總覺得別人擁有的比自己好，得到了又想要別的。", example: "他換了三次工作還是不滿意，這山望著那山高。", deep: "這句話怎麼來的：爬山的人站在這座山頂，看對面那座山總覺得更高，等真的爬過去，回頭看又覺得原來那座比較高。\n字面意思：站在這座山上，覺得那座山比較高。\n引申意思：不滿足於眼前，一直羨慕別處。它點出的是「距離造成的錯覺」，不只是貪心。" },
  { id: "s439", grade: 5, term: "求人不如求己", kind: "諺語", meaning: "與其開口拜託別人，不如自己想辦法解決。", example: "與其等別人教，不如自己查資料，求人不如求己。", deep: "這句話怎麼來的：民間流傳的故事說，有人到廟裡看見觀音自己也在拜觀音，問為什麼，答「求人不如求己」。\n字面意思：求別人不如求自己。\n引申意思：把主動權放回自己手上。它不是叫人不要求助，而是提醒別把希望全押在別人身上。", deep: "這句話怎麼來的：民間流傳的故事說，有人到廟裡看見觀音自己也在拜觀音，問為什麼，答「求人不如求己」。\n字面意思：求別人不如求自己。\n引申意思：把主動權放回自己手上。它不是叫人不要求助，而是提醒別把希望全押在別人身上。" },
  { id: "s440", grade: 6, term: "醜媳婦總要見公婆", kind: "俚語", meaning: "比喻無法迴避的事情，遲早都要面對，躲不掉的。", example: "成績單再難看也得拿回家簽名，醜媳婦總要見公婆，早給早安心。" },
  { id: "s441", grade: 7, term: "剃頭擔子一頭熱", kind: "俚語", meaning: "從前剃頭挑子一頭放熱水爐、一頭放工具，只有一頭是熱的，比喻一廂情願，只有單方面熱心。", example: "他熱心籌辦同學會，大家卻愛理不理，成了剃頭擔子一頭熱。" },
  { id: "s442", grade: 8, term: "儉腸凹肚", kind: "俚語", meaning: "台語俗諺：勒緊腸胃、餓扁肚子，形容省吃儉用、極度節省的樣子。", example: "爸媽儉腸凹肚供我們讀書，我們更要努力向學。" },
  { id: "s443", grade: 9, term: "火燒罟寮——全無望", kind: "歇後語", meaning: "台語歇後語：存放漁網的罟寮失火，漁網（台語「網」與「望」同音）全燒光了，「全無網」諧音「全無望」，指事情毫無希望。", example: "資金被騙光又欠下債務，這間公司恐怕是火燒罟寮——全無望了。" },
  { id: "s444", grade: 10, term: "目睭金金，人傷重", kind: "俚語", meaning: "台語俗諺：眼睛睜得大大的，人卻病重無力，形容眼睜睜看著事情發生，卻無能為力的無奈。", example: "股價一路下跌卻早已賣不掉，他只能目睭金金，人傷重。" },
  // 批4（2026-08-11）：s445-s452
  { id: "s445", grade: 4, term: "鴨仔聽雷", kind: "俚語", meaning: "台語俗諺：鴨子聽打雷，完全聽不懂，比喻聽了半天卻一點也不明白。", example: "老師講解程式原理，我像鴨仔聽雷，一句也沒聽懂。" },
  { id: "s446", grade: 5, term: "孔子公搬家——盡是書（輸）", kind: "歇後語", meaning: "孔子搬家，搬的全是書；「書」與「輸」諧音，指一直輸、每次都輸。", example: "這支隊伍本季戰績像孔子公搬家——盡是輸，教練壓力很大。" },
  { id: "s447", grade: 6, term: "惡馬惡人騎", kind: "俚語", meaning: "台語俗諺：兇悍的馬自有更兇悍的人來駕馭，比喻再難纏的人，也會遇到能制得住他的人；一物剋一物。", example: "這位新教官治好了全班的散漫，果然是惡馬惡人騎。" },
  { id: "s448", grade: 7, term: "城門失火，殃及池魚", kind: "諺語", meaning: "城門著火，取護城河的水救火，水乾了魚也遭殃，比喻無辜受到牽連而遭災。", example: "兩大廠商互告專利，下游小供應商城門失火，殃及池魚，訂單全被凍結。" },
  { id: "s449", grade: 8, term: "拆東牆補西牆", kind: "俚語", meaning: "挪用這裡的資源去補那裡的缺口，問題其實沒有解決。", example: "用信用卡繳另一張卡的帳單，這是拆東牆補西牆。", deep: "這句話怎麼來的：房子的東牆倒了，就把西牆的磚拆下來補，東邊補好了，西邊又破一個洞。\n字面意思：拆掉東邊的牆，去補西邊的牆。\n引申意思：用挖洞補洞的方式應急。它指出的重點是「總量沒有增加」，所以問題只是被推到後面。" },
  { id: "s450", grade: 9, term: "眼不見為淨", kind: "俚語", meaning: "看不到就當作沒事，用不去看來讓自己心裡好過。", example: "房間亂成這樣他也不整理，關上門眼不見為淨。", deep: "這句話怎麼來的：原本是講吃東西——不去看廚房怎麼弄的，吃起來就比較安心，後來擴大到各種不想面對的事。\n字面意思：眼睛看不到，就當作是乾淨的。\n引申意思：用迴避換取心安。它描述的是一種逃避，語氣多半是自嘲或無奈，不是在推薦這種做法。" },
  { id: "s451", grade: 10, term: "大姑娘上轎——頭一回", kind: "歇後語", meaning: "第一次做這件事，沒有經驗，難免緊張生疏。", example: "我上台報告大姑娘上轎——頭一回，手一直發抖。", deep: "這句話怎麼來的：從前女子出嫁才會坐上花轎，一生就這麼一次，所以「大姑娘上轎」就是第一次的代名詞。\n字面意思：姑娘坐上花轎，這是頭一次。\n引申意思：初次上陣、毫無經驗。它帶著體諒的語氣，常用來替自己或別人的生疏找台階。", deep: "這句話怎麼來的：從前女子出嫁才會坐上花轎，一生就這麼一次，所以「大姑娘上轎」就是第一次的代名詞。\n字面意思：姑娘坐上花轎，這是頭一次。\n引申意思：初次上陣、毫無經驗。它帶著體諒的語氣，常用來替自己或別人的生疏找台階。" },
  { id: "s452", grade: 11, term: "前怕狼，後怕虎", kind: "俚語", meaning: "想東想西什麼都怕，結果什麼事都不敢做。", example: "你這樣前怕狼後怕虎，機會早就被別人拿走了。", deep: "這句話怎麼來的：走在山路上，怕前面有狼、又怕後面有虎，兩邊都怕就只能站在原地不動。\n字面意思：怕前面的狼，也怕後面的老虎。\n引申意思：顧慮太多而不敢行動。它批評的是「怕到動不了」，不是說謹慎不好。", deep: "這句話怎麼來的：走在山路上，怕前面有狼、又怕後面有虎，兩邊都怕就只能站在原地不動。\n字面意思：怕前面的狼，也怕後面的老虎。\n引申意思：顧慮太多而不敢行動。它批評的是「怕到動不了」，不是說謹慎不好。" }
];
